CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_task_subtask_counts()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE affected_task_id UUID;
BEGIN
  affected_task_id := COALESCE(NEW.task_id, OLD.task_id);
  UPDATE tasks SET
    subtask_count = (SELECT COUNT(*) FROM subtasks WHERE task_id = affected_task_id),
    subtask_completed_count = (SELECT COUNT(*) FROM subtasks WHERE task_id = affected_task_id AND is_completed)
  WHERE id = affected_task_id;
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_self_privilege_escalation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF auth.uid() = OLD.id AND OLD.role <> 'admin' THEN
    IF NEW.role IS DISTINCT FROM OLD.role THEN NEW.role := OLD.role; END IF;
    IF NEW.org_id IS DISTINCT FROM OLD.org_id THEN NEW.org_id := OLD.org_id; END IF;
    IF NEW.is_active IS DISTINCT FROM OLD.is_active THEN NEW.is_active := OLD.is_active; END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_user_preferences_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.org_in_my_subtree(target_org uuid, caller_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller_path text;
begin
  caller_path := public.auth_org_path(caller_id);
  if caller_path is null then
    return false;
  end if;
  return exists (
    select 1
    from public.organizations o
    where o.id = target_org
      and (o.path::text = caller_path or o.path::text like caller_path || '.%')
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.is_project_member(target_project uuid, caller_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return exists (
    select 1 from public.project_members m
    where m.project_id = target_project and m.user_id = caller_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_task_chat_channel()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_channel_id uuid;
  v_member_ids uuid[];
begin
  v_member_ids := array(
    select distinct member_id
    from unnest(
      array[new.assigned_to::uuid]
      || coalesce(new.team_member_ids::uuid[], '{}'::uuid[])
    ) as member_id
    where member_id is not null
  );

  if coalesce(cardinality(v_member_ids), 0) = 0 then
    return new;
  end if;

  select id into v_channel_id
  from public.chat_channels
  where task_id = new.id;

  if v_channel_id is null then
    insert into public.chat_channels (channel_type, task_id, name)
    values ('task', new.id, new.title)
    returning id into v_channel_id;
  else
    update public.chat_channels
    set name = new.title
    where id = v_channel_id;
  end if;

  delete from public.chat_channel_members as channel_member
  where channel_member.channel_id = v_channel_id
    and channel_member.user_id <> all(v_member_ids);

  insert into public.chat_channel_members (channel_id, user_id)
  select v_channel_id, member_id
  from unnest(v_member_ids) as member_id
  on conflict (channel_id, user_id) do nothing;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.assign_accounting_document_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  request_row public.petty_cash_requests;
  fiscal_year_value int;
begin
  select cash_request.* into request_row
  from public.petty_cash_requests cash_request
  where cash_request.id = new.request_id;

  select budget.fiscal_year into fiscal_year_value
  from public.department_fiscal_budgets budget
  where budget.id = request_row.fiscal_budget_id;

  if tg_table_name = 'petty_cash_releases' then
    if new.voucher_number is null then
      new.voucher_number := format('DV-%s-%s-%s', fiscal_year_value,
        lpad(request_row.request_number::text, 5, '0'),
        upper(right(replace(new.id::text, '-', ''), 6)));
    end if;
  elsif tg_table_name = 'petty_cash_liquidations' then
    if new.liquidation_number is null then
      new.liquidation_number := format('LIQ-%s-%s-%s', fiscal_year_value,
        lpad(request_row.request_number::text, 5, '0'),
        lpad(new.version::text, 2, '0'));
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.post_cash_release_general_journal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  request public.petty_cash_requests;
  settings public.department_accounting_settings;
  journal_id uuid;
  cash_title text;
  advance_title text;
begin
  if new.status <> 'released' or old.status = 'released' then return new; end if;
  select * into request from public.petty_cash_requests where id = new.request_id;
  select * into settings from public.department_accounting_settings where fiscal_budget_id = request.fiscal_budget_id;
  select title into cash_title from public.accounting_accounts where code = settings.cash_account_code;
  select title into advance_title from public.accounting_accounts where code = settings.advance_account_code;
  insert into public.general_journal_entries(
    fiscal_budget_id, org_id, entry_date, reference_number, source_type, source_id, memo, posted_by
  ) values (
    request.fiscal_budget_id, request.org_id, coalesce(new.released_at::date, current_date),
    new.voucher_number, 'cash_release', new.id,
    format('Release to %s for %s', coalesce(request.cash_recipient_id::text, 'recipient'), request.purpose),
    new.released_by
  ) returning id into journal_id;
  insert into public.general_journal_lines(journal_entry_id, line_number, account_code, account_title, debit, credit) values
    (journal_id, 1, settings.advance_account_code, advance_title, new.amount, 0),
    (journal_id, 2, settings.cash_account_code, cash_title, 0, new.amount);
  return new;
exception when unique_violation then return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.post_liquidation_general_journal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  request public.petty_cash_requests;
  settings public.department_accounting_settings;
  journal_id uuid;
  expense_code text;
  expense_title text;
  cash_title text;
  advance_title text;
  next_line int := 1;
  released_value numeric;
begin
  if new.status <> 'approved' or old.status = 'approved' then return new; end if;
  select * into request from public.petty_cash_requests where id = new.request_id;
  select * into settings from public.department_accounting_settings where fiscal_budget_id = request.fiscal_budget_id;
  select coalesce(mapping.account_code, settings.default_expense_account_code)
    into expense_code
  from (select 1) seed
  left join public.department_budget_account_mappings mapping on mapping.allocation_line_id = request.allocation_line_id;
  select title into expense_title from public.accounting_accounts where code = expense_code;
  select title into cash_title from public.accounting_accounts where code = settings.cash_account_code;
  select title into advance_title from public.accounting_accounts where code = settings.advance_account_code;
  released_value := new.declared_spent + new.returned_amount;
  insert into public.general_journal_entries(
    fiscal_budget_id, org_id, entry_date, reference_number, source_type, source_id, memo, posted_by
  ) values (
    request.fiscal_budget_id, request.org_id, coalesce(new.decided_at::date, current_date),
    new.liquidation_number, 'liquidation', new.id,
    format('Settlement for %s', request.purpose), coalesce(new.decided_by, auth.uid())
  ) returning id into journal_id;
  if new.declared_spent > 0 then
    insert into public.general_journal_lines(journal_entry_id, line_number, account_code, account_title, debit, credit)
    values (journal_id, next_line, expense_code, expense_title, new.declared_spent, 0);
    next_line := next_line + 1;
  end if;
  if new.returned_amount > 0 then
    insert into public.general_journal_lines(journal_entry_id, line_number, account_code, account_title, debit, credit)
    values (journal_id, next_line, settings.cash_account_code, cash_title, new.returned_amount, 0);
    next_line := next_line + 1;
  end if;
  insert into public.general_journal_lines(journal_entry_id, line_number, account_code, account_title, debit, credit)
  values (journal_id, next_line, settings.advance_account_code, advance_title, 0, released_value);
  return new;
exception when unique_violation then return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_accounting_petty_cash_release(p_release_id uuid, p_release_method text DEFAULT 'cash'::text, p_cheque_number text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  release public.petty_cash_releases;
  cash_request public.petty_cash_requests;
  budget public.department_fiscal_budgets;
  released_total numeric;
  used_today numeric;
begin
  if caller is null then
    raise exception 'Sign in before recording a release' using errcode = '42501';
  end if;
  if p_release_method not in ('cash', 'cheque') then
    raise exception 'Choose cash or cheque release' using errcode = '22023';
  end if;
  if p_release_method = 'cheque' and nullif(btrim(p_cheque_number), '') is null then
    raise exception 'Enter the cheque number before release' using errcode = '22023';
  end if;

  select request_row.* into cash_request
  from public.petty_cash_releases release_row
  join public.petty_cash_requests request_row on request_row.id = release_row.request_id
  where release_row.id = p_release_id
  for update of request_row;
  if not found then
    raise exception 'Scheduled release not found' using errcode = 'P0002';
  end if;
  if not public.can_manage_department_accounting(cash_request.org_id, caller) then
    raise exception 'Only the department accounting staff, Head, or Assistant Head can record a release' using errcode = '42501';
  end if;

  select * into budget
  from public.department_fiscal_budgets
  where id = cash_request.fiscal_budget_id and status = 'locked'
  for update;
  if not found then
    raise exception 'The annual department budget is no longer open' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('eflow:cash-release:' || cash_request.org_id::text, 0));
  select * into release from public.petty_cash_releases where id = p_release_id for update;
  if release.status <> 'scheduled' then
    raise exception 'This release has already been processed' using errcode = '22023';
  end if;
  if release.scheduled_date > current_date then
    raise exception 'This release is scheduled for %. A Head must use the audited schedule override.', release.scheduled_date using errcode = '22023';
  end if;
  if cash_request.status not in ('approved', 'scheduled_for_release', 'partially_released') or cash_request.approved_amount is null then
    raise exception 'The request must be fiscally approved before release' using errcode = '22023';
  end if;

  select coalesce(sum(amount), 0) into released_total
  from public.petty_cash_releases
  where request_id = cash_request.id and status = 'released';
  if released_total + release.amount > cash_request.approved_amount then
    raise exception 'This release would exceed the approved request amount' using errcode = '22023';
  end if;
  select coalesce(sum(amount), 0) into used_today
  from public.petty_cash_releases
  where org_id = cash_request.org_id and id <> release.id and (
    (status = 'released' and coalesce(released_at::date, scheduled_date) = current_date)
    or (status = 'scheduled' and scheduled_date = current_date)
  );
  if used_today + release.amount > budget.daily_petty_cash_release_limit then
    raise exception 'Daily release ceiling exceeded' using errcode = '22023';
  end if;

  update public.petty_cash_releases
  set status = 'released', released_by = caller, released_at = now(),
      release_method = p_release_method,
      cheque_number = case when p_release_method = 'cheque' then btrim(p_cheque_number) else null end
  where id = release.id;

  released_total := released_total + release.amount;
  update public.petty_cash_requests
  set released_amount = released_total,
      status = case when released_total >= approved_amount then 'released' else 'partially_released' end,
      liquidation_due_at = case when released_total >= approved_amount then now() + budget.liquidation_due_days * interval '1 day' else liquidation_due_at end,
      updated_at = now()
  where id = cash_request.id;

  insert into public.budget_ledger_entries(
    fiscal_budget_id, org_id, commitment_id, allocation_id, petty_cash_request_id,
    task_id, subtask_id, allocation_line_id, entry_type, amount, description,
    actor_id, actor_role, previous_state, new_state, metadata
  )
  select cash_request.fiscal_budget_id, cash_request.org_id, cash_request.commitment_id,
    cash_request.allocation_id, cash_request.id, cash_request.task_id,
    cash_request.subtask_id, cash_request.allocation_line_id, 'petty_cash_released',
    release.amount,
    case when p_release_method = 'cheque' then 'Cheque issued and recorded as released' else 'Cash released to recipient' end,
    caller, profile.role::text, 'scheduled', 'released',
    jsonb_build_object('releaseId', release.id, 'voucherNumber', release.voucher_number,
      'releaseMethod', p_release_method, 'chequeNumber', p_cheque_number)
  from public.profiles profile
  where profile.id = caller;
end;
$function$

CREATE OR REPLACE FUNCTION public.rollup_task_subtasks()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'DELETE' then
    perform public.refresh_task_subtask_rollup(old.task_id, true);
    return old;
  end if;

  if tg_op = 'UPDATE' and old.task_id is distinct from new.task_id then
    perform public.refresh_task_subtask_rollup(old.task_id, true);
  end if;
  perform public.refresh_task_subtask_rollup(new.task_id, true);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.can_manage_project(target_project uuid, caller_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  project_row public.projects;
begin
  if caller_id is null or public.auth_role(caller_id) = 'admin' then return false; end if;
  select * into project_row from public.projects where id = target_project;
  if not found then return false; end if;
  if project_row.source_collaboration_draft_id is not null then
    return public.can_manage_collaboration_project(target_project, caller_id);
  end if;
  return project_row.owner_id = caller_id
    or project_row.created_by = caller_id
    or public.can_access_org(caller_id, project_row.org_id, 'manage');
end;
$function$

CREATE OR REPLACE FUNCTION public.set_department_accounting_staff(p_user_id uuid, p_assigned boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_profile public.profiles;
  target_profile public.profiles;
  organization public.organizations;
begin
  if caller is null then raise exception 'Sign in before managing department access' using errcode = '42501'; end if;
  select * into caller_profile from public.profiles where id = caller and is_active for update;
  if not found or caller_profile.role not in ('dept_head', 'department_head') then
    raise exception 'Only the Department Head can manage department accounting access' using errcode = '42501';
  end if;
  select * into organization from public.organizations where id = caller_profile.org_id and is_active for update;
  if not found or organization.head_user_id is distinct from caller then
    raise exception 'You can manage accounting access only for the department you currently head' using errcode = '42501';
  end if;
  select * into target_profile from public.profiles where id = p_user_id for update;
  if not found or not target_profile.is_active or target_profile.org_id is distinct from organization.id then
    raise exception 'Choose an active person in your own department' using errcode = '22023';
  end if;
  if target_profile.role not in ('employee', 'accounting_staff') then
    raise exception 'Head, Assistant Head, and administrator roles cannot be changed from this department control' using errcode = '42501';
  end if;
  update public.profiles
  set role = case when p_assigned then 'accounting_staff' else 'employee' end,
      updated_at = now()
  where id = target_profile.id;
  insert into public.audit_events(
    actor_id, actor_name, entity_type, entity_id, action, before_data, after_data, org_id
  ) values (
    caller, caller_profile.full_name, 'profile', target_profile.id::text,
    case when p_assigned then 'accounting_access_assigned' else 'accounting_access_removed' end,
    jsonb_build_object('role', target_profile.role),
    jsonb_build_object('role', case when p_assigned then 'accounting_staff' else 'employee' end),
    organization.id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.can_contribute_task(target_task uuid, caller_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  row_task public.tasks;
  caller_role text;
begin
  if caller_id is null then return false; end if;
  caller_role := public.auth_role(caller_id);
  if caller_role = 'admin' then return true; end if;

  select *
    into row_task
  from public.tasks
  where id = target_task
    and deleted_at is null;
  if not found then return false; end if;

  return (
    row_task.assigned_to = caller_id
    or row_task.recommendation_lead_id = caller_id
    or coalesce(to_jsonb(row_task.team_member_ids), '[]'::jsonb)
      ? caller_id::text
    or (
      caller_role in ('dept_head', 'department_head')
      and public.org_in_my_subtree(row_task.org_id, caller_id)
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_accounting_cash_liquidation(p_request_id uuid, p_declared_spent numeric, p_note text, p_receipts jsonb, p_idempotency_key uuid, p_refund_receipt_number text DEFAULT NULL::text, p_refund_date date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare liquidation_id uuid; returned_value numeric;
begin
  select coalesce(released_amount, 0) - p_declared_spent into returned_value
  from public.petty_cash_requests where id = p_request_id;
  if returned_value > 0 and (nullif(btrim(p_refund_receipt_number), '') is null or p_refund_date is null) then
    raise exception 'Enter the official refund receipt number and return date for unused cash' using errcode = '22023';
  end if;
  liquidation_id := public.submit_contextual_cash_liquidation(
    p_request_id, p_declared_spent, p_note, p_receipts, p_idempotency_key
  );
  update public.petty_cash_liquidations
  set refund_receipt_number = case when returned_value > 0 then btrim(p_refund_receipt_number) else null end,
      refund_date = case when returned_value > 0 then p_refund_date else null end
  where id = liquidation_id and submitted_by = auth.uid();
  return liquidation_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.acknowledge_accounting_release(p_release_id uuid, p_voucher_number text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare release public.petty_cash_releases;
begin
  select * into release from public.petty_cash_releases where id = p_release_id;
  if not found then raise exception 'Release not found' using errcode = 'P0002'; end if;
  if upper(btrim(coalesce(p_voucher_number, ''))) is distinct from upper(release.voucher_number) then
    raise exception 'Voucher number does not match this release' using errcode = '22023';
  end if;
  perform public.acknowledge_petty_cash_release(p_release_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_task_project_links()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.milestone_id is null then return new; end if;
  if new.linked_project_id is null then
    raise exception 'A milestone link requires a canonical project link'
      using errcode = '23514';
  end if;
  if not exists (
    select 1
    from public.milestones
    where id = new.milestone_id
      and project_id = new.linked_project_id
  ) then
    raise exception 'Milestone does not belong to the linked project'
      using errcode = '23514';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_subtask_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  target_task uuid;
  parent_status text;
begin
  target_task := case when tg_op = 'DELETE' then old.task_id else new.task_id end;
  select status
    into parent_status
  from public.tasks
  where id = target_task
    and deleted_at is null;

  if parent_status in ('for_review', 'completed') then
    raise exception 'Subtasks are locked while work is under review or completed'
      using errcode = '22023';
  end if;

  if tg_op = 'UPDATE' and old.task_id is distinct from new.task_id then
    select status
      into parent_status
    from public.tasks
    where id = old.task_id
      and deleted_at is null;
    if parent_status in ('for_review', 'completed') then
      raise exception 'Subtasks are locked while work is under review or completed'
        using errcode = '22023';
    end if;
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.transition_task_status(p_task_id uuid, p_to_status text, p_feedback text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS SETOF tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_role text;
  caller_name text;
  t public.tasks;
  prev_status text;
  is_manager boolean;
  is_reviewer boolean;
  recipient uuid;
begin
  if caller is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  select role::text, full_name
    into caller_role, caller_name
  from public.profiles
  where id = caller;

  select *
    into t
  from public.tasks
  where id = p_task_id
    and deleted_at is null
  for update;
  if not found then raise exception 'Task not found'; end if;
  prev_status := t.status;

  if t.archived_at is not null then
    raise exception 'Archived tasks cannot change status'
      using errcode = '22023';
  end if;
  if not public.can_see_task(t.id, caller) then
    raise exception 'Task is outside your allowed scope'
      using errcode = '42501';
  end if;
  if p_to_status = prev_status then
    raise exception 'Task is already %', replace(prev_status, '_', ' ')
      using errcode = '22023';
  end if;

  is_manager := public.can_manage_task(t.id, caller);
  is_reviewer := is_manager;

  if not public.is_allowed_task_transition(t.status, p_to_status) then
    raise exception 'Illegal task transition: % -> %', t.status, p_to_status
      using errcode = '22023';
  end if;

  if p_to_status = 'todo' and t.status = 'pending_assignment' then
    if not is_manager then
      raise exception 'Only a manager may assign work' using errcode = '42501';
    end if;
    if t.assigned_to is null then
      raise exception 'Assign an owner before moving to To do' using errcode = '22023';
    end if;
  elsif p_to_status = 'in_progress' and t.status = 'todo' then
    if not public.can_contribute_task(t.id, caller) then
      raise exception 'Only a task participant may start work'
        using errcode = '42501';
    end if;
  elsif p_to_status = 'in_progress' and t.status = 'changes_requested' then
    if not (t.assigned_to = caller or is_manager) then
      raise exception 'Only the assignee may resume rework' using errcode = '42501';
    end if;
  elsif p_to_status = 'for_review' then
    if not (t.assigned_to = caller or is_manager) then
      raise exception 'Only the assignee may submit for review' using errcode = '42501';
    end if;
    if t.latest_submission is null
       or coalesce(btrim(t.latest_submission ->> 'note'), '') = '' then
      raise exception 'A completion note is required before review'
        using errcode = '22023';
    end if;
  elsif p_to_status in ('completed', 'changes_requested') then
    if not is_reviewer then
      raise exception 'Only the designated reviewer may decide a review'
        using errcode = '42501';
    end if;
    if p_to_status = 'changes_requested'
       and coalesce(btrim(p_feedback), '') = '' then
      raise exception 'Feedback is required when requesting changes'
        using errcode = '22023';
    end if;
  elsif p_to_status = 'in_progress' and t.status = 'completed' then
    if not is_manager then
      raise exception 'Only a manager may reopen a completed task'
        using errcode = '42501';
    end if;
    if coalesce(btrim(p_reason), '') = '' then
      raise exception 'A reason is required to reopen'
        using errcode = '22023';
    end if;
  end if;

  perform set_config('eflow.allow_status_write', 'on', true);

  update public.tasks
  set
    status = p_to_status,
    percent_complete = case
      when p_to_status in ('for_review', 'completed') then 100
      when p_to_status = 'in_progress'
       and prev_status in ('changes_requested', 'completed')
       and percent_complete >= 100 then 99
      else percent_complete
    end,
    feedback = case
      when p_to_status in ('completed', 'changes_requested') then p_feedback
      else feedback
    end,
    rejection_note = case
      when p_to_status = 'changes_requested' then coalesce(p_feedback, p_reason)
      when p_to_status = 'completed' then null
      else rejection_note
    end,
    rejected_at = case
      when p_to_status = 'changes_requested' then now()
      when p_to_status = 'completed' then null
      else rejected_at
    end,
    reopen_reason = case
      when prev_status = 'completed' and p_to_status = 'in_progress'
        then p_reason
      else reopen_reason
    end,
    reopened_at = case
      when prev_status = 'completed' and p_to_status = 'in_progress'
        then now()
      else reopened_at
    end,
    reopened_by_id = case
      when prev_status = 'completed' and p_to_status = 'in_progress'
        then caller
      else reopened_by_id
    end,
    last_activity_at = now()
  where id = p_task_id
  returning * into t;

  perform set_config('eflow.allow_status_write', 'off', true);

  insert into public.task_status_history (
    task_id,
    from_status,
    to_status,
    actor_id,
    actor_name,
    note
  )
  values (
    p_task_id,
    prev_status,
    p_to_status,
    caller,
    coalesce(caller_name, 'User'),
    coalesce(p_feedback, p_reason)
  );

  insert into public.task_activities (
    task_id,
    type,
    content,
    actor_id,
    actor_name
  )
  values (
    p_task_id,
    p_to_status,
    coalesce(
      p_feedback,
      p_reason,
      'Status changed to ' || replace(p_to_status, '_', ' ')
    ),
    caller,
    coalesce(caller_name, 'User')
  );

  insert into public.audit_events (
    actor_id,
    actor_name,
    entity_type,
    entity_id,
    action,
    reason,
    before_data,
    after_data,
    org_id
  )
  values (
    caller,
    coalesce(caller_name, 'User'),
    'task',
    p_task_id::text,
    'task.transition.' || p_to_status,
    coalesce(p_reason, p_feedback),
    jsonb_build_object('status', prev_status),
    jsonb_build_object(
      'status',
      p_to_status,
      'percent_complete',
      t.percent_complete
    ),
    t.org_id
  );

  if p_to_status = 'for_review' then
    recipient := case
      when t.recommendation_lead_id is not null
       and t.recommendation_lead_id <> caller
        then t.recommendation_lead_id
      else t.created_by
    end;
  else
    recipient := t.assigned_to;
  end if;

  if recipient is not null and recipient <> caller then
    insert into public.notifications (
      user_id,
      type,
      title,
      message,
      task_id,
      task_title,
      actor_id,
      actor_name,
      status_from,
      status_to,
      reason
    )
    values (
      recipient,
      case
        when p_to_status = 'completed' then 'completed'
        when p_to_status = 'for_review' then 'approval_needed'
        else 'status_change'
      end,
      'Task ' || replace(p_to_status, '_', ' '),
      coalesce(caller_name, 'Someone') || ' moved "' || t.title ||
        '" to ' || replace(p_to_status, '_', ' ') || '.',
      p_task_id,
      t.title,
      caller,
      coalesce(caller_name, 'User'),
      prev_status,
      p_to_status,
      coalesce(p_reason, p_feedback, '')
    );
  end if;

  return query select * from public.tasks where id = p_task_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.is_organization_approver(target_organization uuid, caller_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  organization_row public.organizations;
  profile_row public.profiles;
begin
  if target_organization is null or caller_id is null then return false; end if;
  select * into profile_row from public.profiles where id = caller_id and is_active;
  if not found then return false; end if;
  if profile_row.role = 'admin' then return false; end if;

  select * into organization_row
  from public.organizations
  where id = target_organization and is_active;
  if not found then return false; end if;

  if caller_id in (organization_row.head_user_id, organization_row.assistant_head_user_id) then
    return true;
  end if;

  return exists (
    select 1 from public.organization_memberships membership
    where membership.organization_id = target_organization
      and membership.user_id = caller_id
      and membership.membership_role in ('primary_approver', 'backup_approver')
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.override_accounting_petty_cash_release_schedule(p_release_id uuid, p_reason text, p_release_method text DEFAULT 'cash'::text, p_cheque_number text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  release public.petty_cash_releases;
  cash_request public.petty_cash_requests;
  budget public.department_fiscal_budgets;
  released_total numeric;
  used_today numeric;
  override_reason text := nullif(btrim(p_reason), '');
  actor_role_value text;
begin
  if caller is null then raise exception 'Sign in before recording a release' using errcode = '42501'; end if;
  if p_release_method not in ('cash', 'cheque') then raise exception 'Choose cash or cheque release' using errcode = '22023'; end if;
  if p_release_method = 'cheque' and nullif(btrim(p_cheque_number), '') is null then raise exception 'Enter the cheque number before release' using errcode = '22023'; end if;
  if override_reason is null or length(override_reason) < 10 or length(override_reason) > 1000 then
    raise exception 'Explain the schedule override in 10 to 1000 characters' using errcode = '22023';
  end if;

  select request_row.* into cash_request
  from public.petty_cash_releases release_row
  join public.petty_cash_requests request_row on request_row.id = release_row.request_id
  where release_row.id = p_release_id
  for update of request_row;
  if not found then raise exception 'Scheduled release not found' using errcode = 'P0002'; end if;
  if not public.can_manage_department_accounting(cash_request.org_id, caller) then
    raise exception 'Only the department accounting staff, Head, or Assistant Head can record a release' using errcode = '42501';
  end if;
  select * into budget from public.department_fiscal_budgets where id = cash_request.fiscal_budget_id and status = 'locked' for update;
  if not found then raise exception 'The annual department budget is no longer open' using errcode = '22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('eflow:cash-release:' || cash_request.org_id::text, 0));
  select * into release from public.petty_cash_releases where id = p_release_id for update;
  if release.status <> 'scheduled' then raise exception 'This release has already been processed' using errcode = '22023'; end if;
  if release.scheduled_date <= current_date then raise exception 'This release is already due; use the normal release confirmation' using errcode = '22023'; end if;
  if cash_request.status not in ('approved', 'scheduled_for_release', 'partially_released') or cash_request.approved_amount is null then
    raise exception 'The request must be fiscally approved before release' using errcode = '22023';
  end if;
  select coalesce(sum(amount), 0) into released_total from public.petty_cash_releases where request_id = cash_request.id and status = 'released';
  if released_total + release.amount > cash_request.approved_amount then raise exception 'This release would exceed the approved request amount' using errcode = '22023'; end if;
  select coalesce(sum(amount), 0) into used_today from public.petty_cash_releases
  where org_id = cash_request.org_id and id <> release.id and (
    (status = 'released' and coalesce(released_at::date, scheduled_date) = current_date)
    or (status = 'scheduled' and scheduled_date = current_date)
  );
  if used_today + release.amount > budget.daily_petty_cash_release_limit then
    raise exception 'Daily release ceiling exceeded' using errcode = '22023';
  end if;

  update public.petty_cash_releases
  set status = 'released', released_by = caller, released_at = now(), release_method = p_release_method,
      cheque_number = case when p_release_method = 'cheque' then btrim(p_cheque_number) else null end
  where id = release.id;
  released_total := released_total + release.amount;
  update public.petty_cash_requests
  set released_amount = released_total,
      status = case when released_total >= approved_amount then 'released' else 'partially_released' end,
      liquidation_due_at = case when released_total >= approved_amount then now() + budget.liquidation_due_days * interval '1 day' else liquidation_due_at end,
      updated_at = now()
  where id = cash_request.id;
  select role::text into actor_role_value from public.profiles where id = caller;
  insert into public.budget_ledger_entries(
    fiscal_budget_id, org_id, commitment_id, allocation_id, petty_cash_request_id, task_id, subtask_id, allocation_line_id,
    entry_type, amount, description, actor_id, actor_role, previous_state, new_state, reason, metadata
  ) values (
    cash_request.fiscal_budget_id, cash_request.org_id, cash_request.commitment_id, cash_request.allocation_id,
    cash_request.id, cash_request.task_id, cash_request.subtask_id, cash_request.allocation_line_id,
    'financial_override', 0, 'Early cash release recorded with schedule override', caller, actor_role_value,
    'scheduled', 'released', override_reason,
    jsonb_build_object('overrideType', 'cash_release_schedule', 'releaseId', release.id,
      'voucherNumber', release.voucher_number, 'originalScheduledDate', release.scheduled_date,
      'actualReleaseDate', current_date, 'releaseAmount', release.amount,
      'releaseMethod', p_release_method, 'chequeNumber', p_cheque_number)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.assign_task(p_task_id uuid, p_assignee uuid, p_assignee_name text DEFAULT NULL::text)
 RETURNS SETOF tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_role text;
  caller_name text;
  t public.tasks;
  prev_status text;
  is_manager boolean;
  previous_assignee uuid;
  resolved_assignee_name text;
  assignee_org uuid;
  assignee_active boolean;
begin
  if caller is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  select role::text, full_name
    into caller_role, caller_name
  from public.profiles
  where id = caller;

  select *
    into t
  from public.tasks
  where id = p_task_id
    and deleted_at is null
  for update;
  if not found then raise exception 'Task not found'; end if;
  prev_status := t.status;
  previous_assignee := t.assigned_to;

  if t.archived_at is not null then
    raise exception 'Archived tasks cannot be reassigned'
      using errcode = '22023';
  end if;
  if t.status in ('for_review', 'completed') then
    raise exception 'Reviewed work must be reopened before reassignment'
      using errcode = '22023';
  end if;

  is_manager := public.can_manage_task(t.id, caller);
  if not is_manager then
    raise exception 'Not allowed to assign this task' using errcode = '42501';
  end if;

  if p_assignee is null then
    if t.status not in ('pending_assignment', 'todo') then
      raise exception 'Active work must be reopened or reassigned, not cleared'
        using errcode = '22023';
    end if;
    resolved_assignee_name := '';
  else
    select full_name, org_id, is_active
      into resolved_assignee_name, assignee_org, assignee_active
    from public.profiles
    where id = p_assignee;
    if not found or not coalesce(assignee_active, false) then
      raise exception 'Assignee is not an active profile'
        using errcode = '22023';
    end if;

    if caller_role <> 'admin' then
      if caller_role in ('dept_head', 'department_head') then
        if not public.org_in_my_subtree(assignee_org, caller) then
          raise exception 'Assignee is outside your organization scope'
            using errcode = '42501';
        end if;
      elsif assignee_org is distinct from t.org_id then
        raise exception 'Task leads may assign only within the task organization'
          using errcode = '42501';
      end if;
    end if;
  end if;

  perform set_config('eflow.allow_status_write', 'on', true);
  update public.tasks
  set
    assigned_to = p_assignee,
    assignee_name = resolved_assignee_name,
    status = case
      when p_assignee is not null and status = 'pending_assignment' then 'todo'
      when p_assignee is null then 'pending_assignment'
      else status
    end,
    last_activity_at = now()
  where id = p_task_id
  returning * into t;
  perform set_config('eflow.allow_status_write', 'off', true);

  if t.status is distinct from prev_status then
    insert into public.task_status_history (
      task_id,
      from_status,
      to_status,
      actor_id,
      actor_name,
      note
    )
    values (
      p_task_id,
      prev_status,
      t.status,
      caller,
      coalesce(caller_name, 'User'),
      'Assignment'
    );
  end if;

  insert into public.task_activities (
    task_id,
    type,
    content,
    actor_id,
    actor_name
  )
  values (
    p_task_id,
    'assigned',
    case
      when p_assignee is null then 'Assignment cleared'
      else 'Assigned to ' || resolved_assignee_name
    end,
    caller,
    coalesce(caller_name, 'User')
  );

  insert into public.audit_events (
    actor_id,
    actor_name,
    entity_type,
    entity_id,
    action,
    before_data,
    after_data,
    org_id
  )
  values (
    caller,
    coalesce(caller_name, 'User'),
    'task',
    p_task_id::text,
    'task.assigned',
    jsonb_build_object('assigned_to', previous_assignee, 'status', prev_status),
    jsonb_build_object('assigned_to', p_assignee, 'status', t.status),
    t.org_id
  );

  if p_assignee is not null and p_assignee <> caller then
    insert into public.notifications (
      user_id,
      type,
      title,
      message,
      task_id,
      task_title,
      actor_id,
      actor_name,
      status_to
    )
    values (
      p_assignee,
      'assignment',
      'New Task Assigned',
      'You have been assigned to "' || t.title || '".',
      p_task_id,
      t.title,
      caller,
      coalesce(caller_name, 'User'),
      t.status
    );
  end if;

  return query select * from public.tasks where id = p_task_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_organization_approvers(p_organization_id uuid, p_primary_approver_id uuid, p_backup_approver_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
begin
  if p_primary_approver_id is not null and p_primary_approver_id = p_backup_approver_id then
    raise exception 'Board Head and Board Assistant Head must be different people' using errcode = '22023';
  end if;
  if public.auth_role(caller) <> 'admin'
     and not public.is_organization_approver(p_organization_id, caller) then
    raise exception 'Only an organization approver or Admin may configure approvers' using errcode = '42501';
  end if;
  if exists (
    select 1 from unnest(array[p_primary_approver_id, p_backup_approver_id]) candidate
    left join public.profiles profile on profile.id = candidate and profile.is_active
    where candidate is not null and profile.id is null
  ) then raise exception 'Board approvers must be active eFlow users' using errcode = '22023'; end if;
  delete from public.organization_memberships
  where organization_id = p_organization_id and membership_role in ('primary_approver', 'backup_approver');
  if p_primary_approver_id is not null then
    insert into public.organization_memberships (organization_id, user_id, membership_role, created_by)
    values (p_organization_id, p_primary_approver_id, 'primary_approver', caller)
    on conflict (organization_id, user_id) do update set membership_role = excluded.membership_role, updated_at = now();
  end if;
  if p_backup_approver_id is not null then
    insert into public.organization_memberships (organization_id, user_id, membership_role, created_by)
    values (p_organization_id, p_backup_approver_id, 'backup_approver', caller)
    on conflict (organization_id, user_id) do update set membership_role = excluded.membership_role, updated_at = now();
  end if;
  insert into public.audit_events (actor_id, actor_name, entity_type, entity_id, action, after_data, org_id)
  values (caller, coalesce((select full_name from public.profiles where id = caller), 'User'),
    'organization_membership', p_organization_id::text, 'organization.approvers.updated',
    jsonb_build_object('primaryApproverId', p_primary_approver_id, 'backupApproverId', p_backup_approver_id), p_organization_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.autosave_collaboration_draft(p_draft_id uuid, p_title text, p_snapshot jsonb)
 RETURNS proposal_collaboration_drafts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  draft_row public.proposal_collaboration_drafts;
  organization_item jsonb;
  target_org uuid;
  target_role text;
  previous_org_ids uuid[] := '{}'::uuid[];
  previous_org_id uuid;
  caller_name text := '';
begin
  if not public.can_manage_collaboration_draft(p_draft_id, caller) then
    raise exception 'Only the owning organization may autosave this draft' using errcode = '42501';
  end if;
  if nullif(btrim(p_title), '') is null or jsonb_typeof(coalesce(p_snapshot, '{}'::jsonb)) <> 'object' then
    raise exception 'Draft title and snapshot are required' using errcode = '22023';
  end if;
  select * into draft_row from public.proposal_collaboration_drafts where id = p_draft_id for update;
  if draft_row.status <> 'draft' then
    raise exception 'Autosave is available only before collaboration review starts' using errcode = '22023';
  end if;
  select coalesce(array_agg(org_id), '{}'::uuid[]) into previous_org_ids
  from public.proposal_collaboration_orgs
  where draft_id = p_draft_id and participation_role <> 'owner';
  select coalesce(full_name, 'Owner') into caller_name from public.profiles where id = caller;

  delete from public.proposal_collaboration_orgs
  where draft_id = p_draft_id and participation_role <> 'owner';
  for organization_item in
    select value from jsonb_array_elements(coalesce(p_snapshot -> 'organizations', '[]'::jsonb))
  loop
    target_org := nullif(organization_item ->> 'orgId', '')::uuid;
    target_role := coalesce(nullif(organization_item ->> 'participationRole', ''), 'participant');
    if target_org is null or target_org = draft_row.owner_org_id then continue; end if;
    if target_role not in ('participant', 'governance', 'observer')
       or not exists (select 1 from public.organizations where id = target_org and is_active) then
      raise exception 'Autosave contains an invalid collaboration organization' using errcode = '22023';
    end if;
    insert into public.proposal_collaboration_orgs (
      draft_id, org_id, participation_role, staffing_enabled, requested_by
    ) values (
      p_draft_id, target_org, target_role,
      case
        when target_role in ('governance', 'observer') then false
        else coalesce((organization_item ->> 'staffingEnabled')::boolean, true)
      end,
      caller
    );
    if not (previous_org_ids @> array[target_org]) then
      insert into public.audit_events (actor_id, actor_name, entity_type, entity_id, action, after_data, org_id)
      values (caller, caller_name, 'collaboration_draft', p_draft_id::text,
        'collaboration.organization_added',
        jsonb_build_object('organizationId', target_org, 'participationRole', target_role), draft_row.owner_org_id);
    end if;
  end loop;

  foreach previous_org_id in array previous_org_ids loop
    if not exists (
      select 1 from jsonb_array_elements(coalesce(p_snapshot -> 'organizations', '[]'::jsonb)) selected
      where nullif(selected ->> 'orgId', '')::uuid = previous_org_id
    ) then
      insert into public.audit_events (actor_id, actor_name, entity_type, entity_id, action, after_data, org_id)
      values (caller, caller_name, 'collaboration_draft', p_draft_id::text,
        'collaboration.organization_removed',
        jsonb_build_object('organizationId', previous_org_id), draft_row.owner_org_id);
    end if;
  end loop;

  update public.proposal_collaboration_drafts
  set title = btrim(p_title), working_snapshot = p_snapshot
  where id = p_draft_id
  returning * into draft_row;
  return draft_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.soft_delete_collaboration_draft(p_draft_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  draft_row public.proposal_collaboration_drafts;
  caller_name text := '';
begin
  if not public.can_manage_collaboration_draft(p_draft_id, caller) then
    raise exception 'Only the owning organization may delete this draft' using errcode = '42501';
  end if;
  if nullif(btrim(p_reason), '') is null then raise exception 'Deletion reason is required' using errcode = '22023'; end if;
  update public.proposal_collaboration_drafts
  set status = 'deleted', deleted_at = now()
  where id = p_draft_id and status <> 'committed'
  returning * into draft_row;
  if not found then raise exception 'Committed drafts cannot be deleted' using errcode = '22023'; end if;
  select coalesce(full_name, 'User') into caller_name from public.profiles where id = caller;
  insert into public.audit_events (actor_id, actor_name, entity_type, entity_id, action, reason, org_id)
  values (caller, caller_name, 'collaboration_draft', p_draft_id::text, 'collaboration.deleted', btrim(p_reason), draft_row.owner_org_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_task_reviewers()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  reviewer_active boolean;
begin
  if new.reviewer_id is not null then
    if new.reviewer_id = new.assigned_to then
      raise exception 'The assignee cannot review their own task'
        using errcode = '22023';
    end if;
    select is_active into reviewer_active
    from public.profiles where id = new.reviewer_id;
    if not coalesce(reviewer_active, false) then
      raise exception 'Primary reviewer must be an active profile'
        using errcode = '22023';
    end if;
  end if;

  if new.backup_reviewer_id is not null then
    if new.backup_reviewer_id = new.assigned_to
       or new.backup_reviewer_id = new.reviewer_id then
      raise exception 'Backup reviewer must differ from assignee and primary reviewer'
        using errcode = '22023';
    end if;
    select is_active into reviewer_active
    from public.profiles where id = new.backup_reviewer_id;
    if not coalesce(reviewer_active, false) then
      raise exception 'Backup reviewer must be an active profile'
        using errcode = '22023';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_task_for_review(p_task_id uuid, p_submission jsonb)
 RETURNS tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_name text;
  completion_note text;
  submission_id uuid;
  submission_version int;
  attachment jsonb;
  normalized_submission jsonb;
  t public.tasks;
  resolved_reviewer uuid;
begin
  if caller is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  completion_note := nullif(btrim(p_submission ->> 'note'), '');
  if completion_note is null then
    raise exception 'Completion note is required' using errcode = '22023';
  end if;
  if p_submission ? 'attachments'
     and jsonb_typeof(p_submission -> 'attachments') <> 'array' then
    raise exception 'Submission attachments must be an array' using errcode = '22023';
  end if;

  select full_name into caller_name
  from public.profiles where id = caller;

  select * into t
  from public.tasks
  where id = p_task_id and deleted_at is null
  for update;
  if not found then raise exception 'Task not found'; end if;
  if t.archived_at is not null or t.status <> 'in_progress' then
    raise exception 'Only in-progress work can be submitted' using errcode = '22023';
  end if;
  if not (t.assigned_to = caller or t.recommendation_lead_id = caller) then
    raise exception 'Only the assignee or task lead may submit this work'
      using errcode = '42501';
  end if;

  resolved_reviewer := case
    when t.reviewer_id is not null
      and t.reviewer_id <> caller
      and t.reviewer_id is distinct from t.assigned_to then t.reviewer_id
    when t.backup_reviewer_id is not null
      and t.backup_reviewer_id <> caller
      and t.backup_reviewer_id is distinct from t.assigned_to then t.backup_reviewer_id
    when t.created_by is not null
      and t.created_by <> caller
      and t.created_by is distinct from t.assigned_to then t.created_by
    else null
  end;
  if resolved_reviewer is null then
    select o.head_user_id into resolved_reviewer
    from public.organizations o
    where o.id = t.org_id
      and o.head_user_id is not null
      and o.head_user_id <> caller
      and o.head_user_id is distinct from t.assigned_to;
  end if;
  if resolved_reviewer is null then
    raise exception 'Assign a reviewer who is not the submitter before submitting'
      using errcode = '22023';
  end if;

  submission_id := case
    when coalesce(p_submission ->> 'id', '') ~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
      then (p_submission ->> 'id')::uuid
    else gen_random_uuid()
  end;
  select coalesce(max(version), 0) + 1 into submission_version
  from public.task_submissions where task_id = p_task_id;

  insert into public.task_submissions (
    id, task_id, version, submitter_id, submitter_name, note
  ) values (
    submission_id,
    p_task_id,
    submission_version,
    caller,
    coalesce(caller_name, 'User'),
    completion_note
  );

  for attachment in
    select value from jsonb_array_elements(
      coalesce(p_submission -> 'attachments', '[]'::jsonb)
    )
  loop
    insert into public.task_attachments (
      task_id,
      submission_id,
      uploaded_by,
      uploader_name,
      file_name,
      file_path,
      file_size,
      mime_type
    ) values (
      p_task_id,
      submission_id,
      caller,
      coalesce(caller_name, 'User'),
      coalesce(attachment ->> 'fileName', 'Attachment'),
      attachment ->> 'filePath',
      case
        when coalesce(attachment ->> 'fileSize', '') ~ '^\d+$'
          then (attachment ->> 'fileSize')::bigint
        else 0
      end,
      coalesce(attachment ->> 'mimeType', '')
    );
  end loop;

  normalized_submission := jsonb_build_object(
    'id', submission_id::text,
    'version', submission_version,
    'note', completion_note,
    'submitterId', caller::text,
    'submitterName', coalesce(caller_name, 'User'),
    'submittedAt', floor(extract(epoch from clock_timestamp()) * 1000)::bigint,
    'attachments', coalesce(p_submission -> 'attachments', '[]'::jsonb)
  );

  perform set_config('eflow.allow_status_write', 'on', true);
  update public.tasks
  set
    reviewer_id = resolved_reviewer,
    latest_submission = normalized_submission,
    feedback = null,
    percent_complete = 100,
    status = 'for_review',
    last_activity_at = now()
  where id = p_task_id
  returning * into t;
  perform set_config('eflow.allow_status_write', 'off', true);

  insert into public.task_status_history (
    task_id, from_status, to_status, actor_id, actor_name, note
  ) values (
    p_task_id, 'in_progress', 'for_review', caller,
    coalesce(caller_name, 'User'), completion_note
  );

  insert into public.task_activities (
    task_id, type, content, actor_id, actor_name
  ) values (
    p_task_id, 'for_review', completion_note, caller,
    coalesce(caller_name, 'User')
  );

  insert into public.audit_events (
    actor_id, actor_name, entity_type, entity_id, action,
    reason, before_data, after_data, org_id
  ) values (
    caller, coalesce(caller_name, 'User'), 'task', p_task_id::text,
    'task.transition.for_review', completion_note,
    jsonb_build_object('status', 'in_progress'),
    jsonb_build_object(
      'status', 'for_review',
      'submissionId', submission_id,
      'submissionVersion', submission_version,
      'reviewerId', resolved_reviewer
    ),
    t.org_id
  );

  if resolved_reviewer <> caller then
    insert into public.notifications (
      user_id, type, title, message, task_id, task_title,
      actor_id, actor_name, status_from, status_to, reason
    ) values (
      resolved_reviewer, 'approval_needed', 'Task ready for review',
      coalesce(caller_name, 'Someone') || ' submitted "' || t.title || '" for review.',
      p_task_id, t.title, caller, coalesce(caller_name, 'User'),
      'in_progress', 'for_review', completion_note
    );
  end if;

  return t;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_task_archived(p_task_id uuid, p_archived boolean)
 RETURNS tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_name text;
  before_task public.tasks;
  changed_task public.tasks;
begin
  if caller is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  select full_name into caller_name from public.profiles where id = caller;
  select * into before_task from public.tasks
  where id = p_task_id and deleted_at is null
  for update;
  if not found then raise exception 'Task not found'; end if;
  if not public.can_manage_task(p_task_id, caller) then
    raise exception 'Not allowed to archive this task' using errcode = '42501';
  end if;

  update public.tasks
  set archived_at = case when p_archived then now() else null end,
      last_activity_at = now()
  where id = p_task_id
  returning * into changed_task;

  insert into public.audit_events (
    actor_id, actor_name, entity_type, entity_id, action,
    before_data, after_data, org_id
  ) values (
    caller, coalesce(caller_name, 'Manager'), 'task', p_task_id::text,
    case when p_archived then 'task.archived' else 'task.unarchived' end,
    jsonb_build_object('archived', before_task.archived_at is not null),
    jsonb_build_object('archived', p_archived),
    before_task.org_id
  );

  return changed_task;
end;
$function$

CREATE OR REPLACE FUNCTION public.soft_delete_task(p_task_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_name text;
  t public.tasks;
begin
  if caller is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  select full_name into caller_name from public.profiles where id = caller;
  select * into t from public.tasks
  where id = p_task_id and deleted_at is null
  for update;
  if not found then raise exception 'Task not found'; end if;
  if not public.can_manage_task(p_task_id, caller) then
    raise exception 'Not allowed to delete this task' using errcode = '42501';
  end if;

  update public.tasks set deleted_at = now(), last_activity_at = now()
  where id = p_task_id;

  insert into public.audit_events (
    actor_id, actor_name, entity_type, entity_id, action,
    before_data, after_data, org_id
  ) values (
    caller, coalesce(caller_name, 'Manager'), 'task', p_task_id::text,
    'task.deleted', to_jsonb(t), jsonb_build_object('deleted', true), t.org_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_subtask_contributor_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  workflow_authorized boolean :=
    coalesce(current_setting('eflow.subtask_workflow_authorized', true), 'off') = 'on';
begin
  if workflow_authorized then
    return new;
  end if;

  if new.is_completed is distinct from old.is_completed
     or new.completed_by is distinct from old.completed_by
     or new.completed_at is distinct from old.completed_at
     or new.status is distinct from old.status
     or new.percent_complete is distinct from old.percent_complete
     or new.reviewer_id is distinct from old.reviewer_id
     or new.latest_submission_id is distinct from old.latest_submission_id then
    raise exception 'Open the subtask and submit evidence for review; direct check-off is disabled'
      using errcode = '42501';
  end if;

  if public.can_manage_subtasks(old.task_id, caller) then
    return new;
  end if;

  if not (
    old.assigned_to = caller
    or caller = any(coalesce(old.assigned_to_ids, '{}'::uuid[]))
  ) then
    raise exception 'This subtask is not assigned to you' using errcode = '42501';
  end if;

  if new.task_id is distinct from old.task_id
     or new.title is distinct from old.title
     or new.position is distinct from old.position
     or new.is_standalone is distinct from old.is_standalone
     or new.source is distinct from old.source
     or new.created_by is distinct from old.created_by
     or new.assigned_to is distinct from old.assigned_to
     or new.assigned_to_ids is distinct from old.assigned_to_ids then
    raise exception 'Only a task lead may edit, reassign, or change the execution rule of a subtask'
      using errcode = '42501';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_task_submission_readiness()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  unresolved_count int;
begin
  if new.status = 'for_review' and old.status is distinct from 'for_review' then
    select count(*) into unresolved_count
    from unnest(new.dependency_ids) dependency_id
    left join public.tasks dependency on dependency.id = dependency_id
    where dependency.id is null
       or dependency.deleted_at is not null
       or dependency.status <> 'completed';

    if unresolved_count > 0 then
      raise exception 'Complete all task dependencies before submitting for review'
        using errcode = '22023';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_task(p_task_id uuid, p_reason text)
 RETURNS tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_name text;
  t public.tasks;
  previous_status text;
begin
  if caller is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'A cancellation reason is required' using errcode = '22023';
  end if;

  select full_name into caller_name
  from public.profiles where id = caller;
  select * into t from public.tasks
  where id = p_task_id and deleted_at is null
  for update;
  if not found then raise exception 'Task not found'; end if;
  previous_status := t.status;
  if t.status in ('completed', 'cancelled') then
    raise exception 'Completed or cancelled tasks cannot be cancelled'
      using errcode = '22023';
  end if;
  if not public.can_manage_task(p_task_id, caller) then
    raise exception 'Not allowed to cancel this task' using errcode = '42501';
  end if;

  perform set_config('eflow.allow_status_write', 'on', true);
  update public.tasks
  set status = 'cancelled',
      cancellation_reason = btrim(p_reason),
      cancelled_at = now(),
      cancelled_by = caller,
      last_activity_at = now()
  where id = p_task_id
  returning * into t;
  perform set_config('eflow.allow_status_write', 'off', true);

  insert into public.task_status_history (
    task_id, from_status, to_status, actor_id, actor_name, note
  ) values (
    p_task_id, previous_status, 'cancelled', caller,
    coalesce(caller_name, 'Manager'), btrim(p_reason)
  );

  insert into public.task_activities (
    task_id, type, content, actor_id, actor_name
  ) values (
    p_task_id, 'cancelled', btrim(p_reason), caller,
    coalesce(caller_name, 'Manager')
  );

  insert into public.audit_events (
    actor_id, actor_name, entity_type, entity_id, action,
    reason, before_data, after_data, org_id
  ) values (
    caller, coalesce(caller_name, 'Manager'), 'task', p_task_id::text,
    'task.cancelled', btrim(p_reason),
    jsonb_build_object('status', previous_status),
    jsonb_build_object('status', 'cancelled'), t.org_id
  );

  insert into public.notifications (
    user_id, type, title, message, task_id, task_title,
    actor_id, actor_name, status_from, status_to, reason
  )
  select recipient, 'status_change', 'Task cancelled',
    '"' || t.title || '" was cancelled.', p_task_id, t.title,
    caller, coalesce(caller_name, 'Manager'), previous_status,
    'cancelled', btrim(p_reason)
  from (
    select distinct recipient from unnest(
      array_remove(array[t.assigned_to, t.reviewer_id, t.backup_reviewer_id], null)
    ) recipient
  ) recipients
  where recipient <> caller;

  return t;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_organization_leadership(p_org_id uuid, p_head_user_id uuid DEFAULT NULL::uuid, p_assistant_head_user_id uuid DEFAULT NULL::uuid)
 RETURNS organizations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_name text;
  previous_head uuid;
  previous_assistant uuid;
  selected_profile public.profiles;
  updated_org public.organizations;
begin
  if caller is null or not public.is_super_admin(caller) then
    raise exception 'Admin access is required'
      using errcode = '42501';
  end if;

  if p_head_user_id is not null
     and p_head_user_id = p_assistant_head_user_id then
    raise exception 'Head and Assistant Head must be different people'
      using errcode = '22023';
  end if;

  select head_user_id, assistant_head_user_id
    into previous_head, previous_assistant
  from public.organizations
  where id = p_org_id and is_active
  for update;
  if not found then
    raise exception 'Organization not found or inactive'
      using errcode = '22023';
  end if;

  if p_head_user_id is not null then
    select * into selected_profile
    from public.profiles where id = p_head_user_id for update;
    if not found or not coalesce(selected_profile.is_active, false) then
      raise exception 'Head must be an active user'
        using errcode = '22023';
    end if;
    if selected_profile.role = 'admin' then
      raise exception 'A Admin account cannot be reassigned as Head'
        using errcode = '22023';
    end if;
    if exists (
      select 1 from public.organizations
      where id <> p_org_id
        and (head_user_id = p_head_user_id
          or assistant_head_user_id = p_head_user_id)
    ) then
      raise exception 'The selected Head already holds a leadership position in another organization'
        using errcode = '22023';
    end if;
  end if;

  if p_assistant_head_user_id is not null then
    select * into selected_profile
    from public.profiles where id = p_assistant_head_user_id for update;
    if not found or not coalesce(selected_profile.is_active, false) then
      raise exception 'Assistant Head must be an active user'
        using errcode = '22023';
    end if;
    if selected_profile.role = 'admin' then
      raise exception 'A Admin account cannot be reassigned as Assistant Head'
        using errcode = '22023';
    end if;
    if exists (
      select 1 from public.organizations
      where id <> p_org_id
        and (head_user_id = p_assistant_head_user_id
          or assistant_head_user_id = p_assistant_head_user_id)
    ) then
      raise exception 'The selected Assistant Head already holds a leadership position in another organization'
        using errcode = '22023';
    end if;
  end if;

  update public.organizations
  set
    head_user_id = p_head_user_id,
    assistant_head_user_id = p_assistant_head_user_id,
    updated_at = now()
  where id = p_org_id
  returning * into updated_org;

  if p_head_user_id is not null then
    update public.profiles
    set role = 'dept_head', org_id = p_org_id, updated_at = now()
    where id = p_head_user_id;
  end if;

  if p_assistant_head_user_id is not null then
    update public.profiles
    set role = 'assistant_head', org_id = p_org_id, updated_at = now()
    where id = p_assistant_head_user_id;
  end if;

  if previous_head is not null
     and previous_head is distinct from p_head_user_id
     and previous_head is distinct from p_assistant_head_user_id
     and not exists (
       select 1 from public.organizations
       where head_user_id = previous_head or assistant_head_user_id = previous_head
     ) then
    update public.profiles
    set role = 'employee', updated_at = now()
    where id = previous_head
      and role in ('dept_head', 'department_head', 'assistant_head');
  end if;

  if previous_assistant is not null
     and previous_assistant is distinct from p_head_user_id
     and previous_assistant is distinct from p_assistant_head_user_id
     and not exists (
       select 1 from public.organizations
       where head_user_id = previous_assistant
          or assistant_head_user_id = previous_assistant
     ) then
    update public.profiles
    set role = 'employee', updated_at = now()
    where id = previous_assistant
      and role in ('dept_head', 'department_head', 'assistant_head');
  end if;

  -- Re-run the task routing trigger for active work in this organization.
  update public.tasks
  set reviewer_id = reviewer_id
  where org_id = p_org_id
    and deleted_at is null
    and status not in ('completed', 'cancelled')
    and p_head_user_id is not null
    and p_assistant_head_user_id is not null;

  select full_name into caller_name from public.profiles where id = caller;
  insert into public.audit_events (
    actor_id, actor_name, entity_type, entity_id, action,
    before_data, after_data, org_id
  ) values (
    caller,
    coalesce(caller_name, 'Admin'),
    'organization',
    p_org_id::text,
    'organization.leadership_changed',
    jsonb_build_object(
      'headUserId', previous_head,
      'assistantHeadUserId', previous_assistant
    ),
    jsonb_build_object(
      'headUserId', p_head_user_id,
      'assistantHeadUserId', p_assistant_head_user_id
    ),
    p_org_id
  );

  return updated_org;
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_subtask_reviewer(target_task tasks, submitter uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare candidate uuid;
begin
  foreach candidate in array array[
    coalesce(target_task.assigned_to, target_task.recommendation_lead_id),
    target_task.reviewer_id, target_task.backup_reviewer_id, target_task.created_by
  ] loop
    if candidate is not null and candidate <> submitter and exists (
      select 1 from public.profiles p where p.id = candidate and p.is_active
    ) then return candidate; end if;
  end loop;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_subtask_progress(p_subtask_id uuid, p_percent_complete integer, p_blocker_category text DEFAULT NULL::text, p_blocker text DEFAULT NULL::text, p_next_step text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_attachment_path text DEFAULT NULL::text, p_attachment_name text DEFAULT NULL::text)
 RETURNS subtasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_name text;
  subtask_row public.subtasks;
  task_row public.tasks;
begin
  if caller is null then raise exception 'Not authenticated' using errcode = '42501'; end if;
  if p_percent_complete < 0 or p_percent_complete >= 100 then
    raise exception 'Use Submit for Leader Review when progress reaches 100%%'
      using errcode = '22023';
  end if;

  select * into subtask_row from public.subtasks where id = p_subtask_id for update;
  if not found then raise exception 'Subtask not found' using errcode = 'P0002'; end if;

  if not (
    subtask_row.assigned_to = caller
    or caller = any(coalesce(subtask_row.assigned_to_ids, '{}'::uuid[]))
  ) then
    raise exception 'This subtask is not assigned to you' using errcode = '42501';
  end if;

  if subtask_row.status in ('for_review', 'completed') then
    raise exception 'This subtask is locked while under review or completed'
      using errcode = '22023';
  end if;

  select * into task_row from public.tasks
  where id = subtask_row.task_id and deleted_at is null;
  if not found or task_row.status in ('for_review', 'completed', 'cancelled') then
    raise exception 'The parent task is not open for subtask progress'
      using errcode = '22023';
  end if;

  select full_name into caller_name from public.profiles where id = caller;

  perform set_config('eflow.subtask_workflow_authorized', 'on', true);
  update public.subtasks
  set
    percent_complete = p_percent_complete,
    status = case when p_percent_complete > 0 then 'in_progress' else 'todo' end,
    is_completed = false,
    completed_by = null,
    completed_at = null
  where id = p_subtask_id
  returning * into subtask_row;
  perform set_config('eflow.subtask_workflow_authorized', 'off', true);

  insert into public.subtask_progress_updates (
    subtask_id, task_id, author_id, author_name, percent_complete,
    blocker_category, blocker, next_step, note, attachment_path, attachment_name
  ) values (
    p_subtask_id, subtask_row.task_id, caller, coalesce(caller_name, 'User'),
    p_percent_complete, nullif(btrim(p_blocker_category), ''),
    nullif(btrim(p_blocker), ''), nullif(btrim(p_next_step), ''),
    nullif(btrim(p_note), ''), nullif(p_attachment_path, ''),
    nullif(p_attachment_name, '')
  );

  insert into public.task_activities (task_id, type, content, actor_id, actor_name)
  values (
    subtask_row.task_id, 'subtask_progress',
    'Updated "' || subtask_row.title || '" to ' || p_percent_complete || '%',
    caller, coalesce(caller_name, 'User')
  );

  return subtask_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.decide_task_review(p_task_id uuid, p_approve boolean, p_feedback text DEFAULT NULL::text, p_audit_hash text DEFAULT NULL::text)
 RETURNS tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_role text;
  caller_name text;
  task_row public.tasks;
  submission public.task_submissions;
  next_status text;
  decision_hash text;
  recipient_id uuid;
begin
  if caller is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if not p_approve and coalesce(btrim(p_feedback), '') = '' then
    raise exception 'Feedback is required when requesting changes'
      using errcode = '22023';
  end if;

  select role::text, full_name
    into caller_role, caller_name
  from public.profiles
  where id = caller;

  select *
    into task_row
  from public.tasks
  where id = p_task_id
    and deleted_at is null
  for update;

  if not found then
    raise exception 'Task not found' using errcode = 'P0002';
  end if;

  if task_row.status <> 'for_review' then
    raise exception 'Task is not awaiting review' using errcode = '22023';
  end if;

  select *
    into submission
  from public.task_submissions
  where task_id = p_task_id
  order by version desc
  limit 1
  for update;

  if not found then
    raise exception 'No review submission exists' using errcode = '22023';
  end if;

  if submission.submitter_id = caller then
    raise exception 'You cannot review your own submission' using errcode = '42501';
  end if;

  if not (
    caller_role = 'admin'
    or task_row.reviewer_id = caller
    or task_row.backup_reviewer_id = caller
  ) then
    raise exception 'Only the assigned reviewer may decide this submission'
      using errcode = '42501';
  end if;

  next_status := case when p_approve then 'completed' else 'changes_requested' end;
  decision_hash := case when p_approve then encode(
    extensions.digest(
      p_task_id::text || ':' || submission.id::text || ':' || caller::text || ':' ||
      clock_timestamp()::text,
      'sha256'
    ),
    'hex'
  ) else null end;

  perform set_config('eflow.allow_status_write', 'on', true);
  perform set_config('eflow.review_decision_authorized', 'on', true);

  update public.tasks
  set
    status = next_status,
    percent_complete = case when p_approve then 100 else 99 end,
    feedback = nullif(btrim(p_feedback), ''),
    rejection_note = case
      when p_approve then rejection_note
      else nullif(btrim(p_feedback), '')
    end,
    rejected_at = case when p_approve then rejected_at else now() end,
    audit_hash = coalesce(decision_hash, audit_hash),
    last_activity_at = now()
  where id = p_task_id
  returning * into task_row;

  perform set_config('eflow.review_decision_authorized', 'off', true);
  perform set_config('eflow.allow_status_write', 'off', true);

  update public.task_submissions
  set
    status = case when p_approve then 'approved' else 'changes_requested' end,
    decided_by = caller,
    decided_by_name = coalesce(caller_name, 'Reviewer'),
    decision_feedback = nullif(btrim(p_feedback), ''),
    decided_at = now()
  where id = submission.id;

  insert into public.task_status_history (
    task_id, from_status, to_status, actor_id, actor_name, note
  ) values (
    p_task_id, 'for_review', next_status, caller,
    coalesce(caller_name, 'Reviewer'), nullif(btrim(p_feedback), '')
  );

  insert into public.task_activities (
    task_id, type, content, actor_id, actor_name
  ) values (
    p_task_id, next_status,
    coalesce(
      nullif(btrim(p_feedback), ''),
      case when p_approve then 'Review approved' else 'Changes requested' end
    ),
    caller, coalesce(caller_name, 'Reviewer')
  );

  insert into public.audit_events (
    actor_id, actor_name, entity_type, entity_id, action,
    reason, before_data, after_data, org_id
  ) values (
    caller, coalesce(caller_name, 'Reviewer'), 'task', p_task_id::text,
    'task.transition.' || next_status, nullif(btrim(p_feedback), ''),
    jsonb_build_object('status', 'for_review', 'submissionId', submission.id),
    jsonb_build_object('status', next_status, 'auditHash', decision_hash),
    task_row.org_id
  );

  for recipient_id in
    select distinct recipient.user_id
    from unnest(array[
      task_row.assigned_to,
      submission.submitter_id,
      task_row.recommendation_lead_id
    ]) as recipient(user_id)
    where recipient.user_id is not null
      and recipient.user_id <> caller
  loop
    insert into public.notifications (
      user_id, type, title, message, task_id, task_title,
      actor_id, actor_name, status_from, status_to, reason
    ) values (
      recipient_id,
      case when p_approve then 'completed' else 'status_change' end,
      case when p_approve then 'Task approved' else 'Changes requested' end,
      case
        when p_approve then 'Your work on "' || task_row.title || '" was approved.'
        else 'Changes were requested for "' || task_row.title || '".'
      end,
      p_task_id, task_row.title, caller, coalesce(caller_name, 'Reviewer'),
      'for_review', next_status, coalesce(nullif(btrim(p_feedback), ''), '')
    );
  end loop;

  return task_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_cash_request_needed_by()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.needed_by is not null and new.needed_by < current_date then
    raise exception 'Needed-by date cannot be earlier than today' using errcode = '22023';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_late_liquidation_head_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  request_row public.petty_cash_requests;
  caller_role text;
begin
  if new.status = 'approved' and old.status is distinct from 'approved' then
    select * into request_row
    from public.petty_cash_requests
    where id = new.request_id;

    if request_row.liquidation_due_at is not null
       and new.submitted_at > request_row.liquidation_due_at then
      select profile.role::text into caller_role
      from public.profiles profile
      where profile.id = auth.uid();

      if caller_role is null or caller_role not in ('dept_head', 'department_head') then
        raise exception 'This liquidation was submitted after its deadline and requires Department Head approval'
          using errcode = '42501';
      end if;
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_subtask_for_review(p_subtask_id uuid, p_submission jsonb)
 RETURNS subtasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_name text;
  subtask_row public.subtasks;
  task_row public.tasks;
  reviewer uuid;
  submission_id uuid;
  next_version int;
  previous_status text;
  note_text text;
  attachment jsonb;
  attachment_count int;
begin
  if caller is null then raise exception 'Not authenticated' using errcode = '42501'; end if;

  note_text := btrim(coalesce(p_submission ->> 'note', ''));
  if note_text = '' then raise exception 'Completion note is required' using errcode = '22023'; end if;
  attachment_count := jsonb_array_length(coalesce(p_submission -> 'attachments', '[]'::jsonb));
  if attachment_count = 0 then
    raise exception 'At least one evidence file is required for subtask review'
      using errcode = '22023';
  end if;

  select * into subtask_row from public.subtasks where id = p_subtask_id for update;
  if not found then raise exception 'Subtask not found' using errcode = 'P0002'; end if;

  if not (
    subtask_row.assigned_to = caller
    or caller = any(coalesce(subtask_row.assigned_to_ids, '{}'::uuid[]))
  ) then
    raise exception 'This subtask is not assigned to you' using errcode = '42501';
  end if;
  if subtask_row.status in ('for_review', 'completed') then
    raise exception 'This subtask is already under review or completed'
      using errcode = '22023';
  end if;
  previous_status := subtask_row.status;

  select * into task_row from public.tasks
  where id = subtask_row.task_id and deleted_at is null
  for update;
  if not found or task_row.status in ('for_review', 'completed', 'cancelled') then
    raise exception 'The parent task is not open for subtask submission'
      using errcode = '22023';
  end if;

  reviewer := public.resolve_subtask_reviewer(task_row, caller);
  if reviewer is null then
    raise exception 'No eligible Team Leader or task reviewer is available'
      using errcode = '22023';
  end if;

  select full_name into caller_name from public.profiles where id = caller;
  submission_id := coalesce(nullif(p_submission ->> 'id', '')::uuid, gen_random_uuid());
  select coalesce(max(version), 0) + 1 into next_version
  from public.subtask_submissions where subtask_id = p_subtask_id;

  insert into public.subtask_submissions (
    id, subtask_id, task_id, version, submitter_id, submitter_name,
    reviewer_id, note
  ) values (
    submission_id, p_subtask_id, subtask_row.task_id, next_version,
    caller, coalesce(caller_name, 'User'), reviewer, note_text
  );

  for attachment in select value from jsonb_array_elements(p_submission -> 'attachments') loop
    insert into public.subtask_submission_attachments (
      submission_id, subtask_id, task_id, uploaded_by,
      file_name, file_path, file_size, mime_type
    ) values (
      submission_id, p_subtask_id, subtask_row.task_id, caller,
      coalesce(nullif(attachment ->> 'fileName', ''), 'Evidence'),
      attachment ->> 'filePath',
      coalesce((attachment ->> 'fileSize')::bigint, 0),
      coalesce(attachment ->> 'mimeType', '')
    );
  end loop;

  perform set_config('eflow.subtask_workflow_authorized', 'on', true);
  update public.subtasks
  set
    status = 'for_review',
    percent_complete = 100,
    reviewer_id = reviewer,
    latest_submission_id = submission_id,
    is_completed = false,
    completed_by = null,
    completed_at = null
  where id = p_subtask_id
  returning * into subtask_row;
  perform set_config('eflow.subtask_workflow_authorized', 'off', true);

  insert into public.task_activities (task_id, type, content, actor_id, actor_name)
  values (
    subtask_row.task_id, 'subtask_for_review',
    coalesce(caller_name, 'User') || ' submitted subtask "' || subtask_row.title || '" for review',
    caller, coalesce(caller_name, 'User')
  );

  insert into public.audit_events (
    actor_id, actor_name, entity_type, entity_id, action, after_data, org_id
  ) values (
    caller, coalesce(caller_name, 'User'), 'subtask', p_subtask_id::text,
    'subtask.submitted',
    jsonb_build_object('submissionId', submission_id, 'version', next_version, 'reviewerId', reviewer),
    task_row.org_id
  );

  insert into public.notifications (
    user_id, type, title, message, task_id, task_title,
    actor_id, actor_name, status_from, status_to, reason
  ) values (
    reviewer, 'approval_needed', 'Subtask evidence ready for review',
    coalesce(caller_name, 'A team member') || ' submitted "' || subtask_row.title || '".',
    task_row.id, task_row.title, caller, coalesce(caller_name, 'User'),
    previous_status, 'for_review', note_text
  );

  return subtask_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_subtask_template_governance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
begin
  -- Privileged migrations seed starter templates without a JWT. Anonymous
  -- clients still cannot write because RLS rejects their table operation.
  if caller is null then return new; end if;

  if tg_op = 'INSERT' then
    if new.owner_id is null then new.owner_id := caller; end if;
    if new.owner_id <> caller and not public.can_approve_work_templates(new.org_id, caller) then
      raise exception 'Template ownership cannot be assigned to another user'
        using errcode = '42501';
    end if;
    new.approval_status := case
      when new.visibility = 'personal' then 'approved'
      when public.can_approve_work_templates(new.org_id, caller) then 'approved'
      else 'pending'
    end;
    return new;
  end if;

  if new.org_id is distinct from old.org_id
     or new.owner_id is distinct from old.owner_id
     or new.is_starter is distinct from old.is_starter then
    raise exception 'Template organization, ownership, and starter status are immutable'
      using errcode = '42501';
  end if;

  if not public.can_approve_work_templates(new.org_id, caller) then
    if new.approval_status is distinct from old.approval_status then
      raise exception 'Only a Head or Assistant Head may decide department template approval'
        using errcode = '42501';
    end if;
    new.approval_status := case
      when new.visibility = 'personal' then 'approved'
      when new.title is distinct from old.title
        or new.description is distinct from old.description
        or new.visibility is distinct from old.visibility then 'pending'
      else old.approval_status
    end;
  elsif new.visibility = 'personal' then
    new.approval_status := 'approved';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_recurring_template_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.assignee_id is not null and not exists (
    select 1 from public.profiles p
    where p.id = new.assignee_id and p.is_active and p.org_id = new.org_id
  ) then
    raise exception 'Recurring-task assignee must be an active member directly assigned to this department'
      using errcode = '42501';
  end if;
  if new.reviewer_id is not null and not exists (
    select 1 from public.profiles p
    where p.id = new.reviewer_id and p.is_active and p.org_id = new.org_id
  ) then
    raise exception 'Recurring-task reviewer must be an active member directly assigned to this department'
      using errcode = '42501';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.decide_subtask_review(p_subtask_id uuid, p_approve boolean, p_feedback text DEFAULT NULL::text)
 RETURNS subtasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_name text;
  caller_role text;
  subtask_row public.subtasks;
  task_row public.tasks;
  submission_row public.subtask_submissions;
  next_status text;
begin
  if caller is null then raise exception 'Not authenticated' using errcode = '42501'; end if;
  if not p_approve and btrim(coalesce(p_feedback, '')) = '' then
    raise exception 'Feedback is required when requesting changes'
      using errcode = '22023';
  end if;

  select role::text, full_name into caller_role, caller_name
  from public.profiles where id = caller;
  select * into subtask_row from public.subtasks where id = p_subtask_id for update;
  if not found then raise exception 'Subtask not found' using errcode = 'P0002'; end if;
  if subtask_row.status <> 'for_review' then
    raise exception 'Subtask is not awaiting review' using errcode = '22023';
  end if;

  select * into submission_row from public.subtask_submissions
  where id = subtask_row.latest_submission_id and status = 'pending'
  for update;
  if not found then raise exception 'Pending subtask submission not found' using errcode = '22023'; end if;
  if submission_row.submitter_id = caller then
    raise exception 'You cannot review your own subtask submission' using errcode = '42501';
  end if;
  if caller_role <> 'admin' and submission_row.reviewer_id <> caller then
    raise exception 'Only the assigned Team Leader may review this subtask'
      using errcode = '42501';
  end if;

  select * into task_row from public.tasks where id = subtask_row.task_id;
  next_status := case when p_approve then 'completed' else 'changes_requested' end;

  perform set_config('eflow.subtask_workflow_authorized', 'on', true);
  update public.subtasks
  set
    status = next_status,
    percent_complete = case when p_approve then 100 else 99 end,
    is_completed = p_approve,
    completed_by = case when p_approve then submission_row.submitter_id else null end,
    completed_at = case when p_approve then now() else null end
  where id = p_subtask_id
  returning * into subtask_row;
  perform set_config('eflow.subtask_workflow_authorized', 'off', true);

  update public.subtask_submissions
  set
    status = case when p_approve then 'approved' else 'changes_requested' end,
    decided_by = caller,
    decided_by_name = coalesce(caller_name, 'Team Leader'),
    decision_feedback = nullif(btrim(p_feedback), ''),
    decided_at = now()
  where id = submission_row.id;

  insert into public.task_activities (task_id, type, content, actor_id, actor_name)
  values (
    subtask_row.task_id, 'subtask_' || next_status,
    'Subtask "' || subtask_row.title || '" ' ||
      case when p_approve then 'was approved' else 'needs changes' end,
    caller, coalesce(caller_name, 'Team Leader')
  );

  insert into public.audit_events (
    actor_id, actor_name, entity_type, entity_id, action, reason,
    before_data, after_data, org_id
  ) values (
    caller, coalesce(caller_name, 'Team Leader'), 'subtask', p_subtask_id::text,
    'subtask.' || next_status, nullif(btrim(p_feedback), ''),
    jsonb_build_object('status', 'for_review', 'submissionId', submission_row.id),
    jsonb_build_object('status', next_status, 'completed', p_approve),
    task_row.org_id
  );

  insert into public.notifications (
    user_id, type, title, message, task_id, task_title,
    actor_id, actor_name, status_from, status_to, reason
  ) values (
    submission_row.submitter_id,
    case when p_approve then 'completed' else 'status_change' end,
    case when p_approve then 'Subtask approved' else 'Subtask changes requested' end,
    case
      when p_approve then 'Your evidence for "' || subtask_row.title || '" was approved.'
      else 'Changes were requested for "' || subtask_row.title || '".'
    end,
    task_row.id, task_row.title, caller, coalesce(caller_name, 'Team Leader'),
    'for_review', next_status, coalesce(nullif(btrim(p_feedback), ''), '')
  );

  return subtask_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_subtask_progress_leader()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  subtask_row public.subtasks;
  task_row public.tasks;
  recipient_id uuid;
  detail_text text;
begin
  select * into subtask_row
  from public.subtasks
  where id = new.subtask_id;
  if not found then return new; end if;

  select * into task_row
  from public.tasks
  where id = new.task_id and deleted_at is null;
  if not found then return new; end if;

  recipient_id := public.resolve_subtask_reviewer(task_row, new.author_id);
  if recipient_id is null or recipient_id = new.author_id then return new; end if;

  detail_text := concat_ws(
    ' · ',
    nullif(btrim(new.note), ''),
    case
      when nullif(btrim(new.blocker_category), '') is not null
       and new.blocker_category <> 'None'
        then 'Blocker: ' || new.blocker_category ||
          case when nullif(btrim(new.blocker), '') is not null then ' — ' || btrim(new.blocker) else '' end
      else null
    end,
    case when nullif(btrim(new.next_step), '') is not null then 'Next: ' || btrim(new.next_step) else null end,
    case when nullif(btrim(new.attachment_name), '') is not null then 'Attachment: ' || new.attachment_name else null end
  );

  insert into public.notifications (
    user_id, type, title, message, task_id, task_title,
    actor_id, actor_name, status_from, status_to, reason
  ) values (
    recipient_id,
    'status_change',
    'Subtask progress updated',
    coalesce(new.author_name, 'A team member') || ' updated "' ||
      subtask_row.title || '" to ' || new.percent_complete || '%.' ||
      case when detail_text <> '' then ' ' || detail_text else '' end,
    task_row.id,
    task_row.title,
    new.author_id,
    coalesce(new.author_name, 'Team member'),
    '',
    new.percent_complete || '%',
    ''
  );

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_collaboration_owner_decision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if exists (
    select 1 from public.proposal_collaboration_orgs participant
    where participant.draft_id = new.draft_id
      and participant.org_id = new.organization_id
      and participant.participation_role = 'owner'
  ) and (
    pg_trigger_depth() < 2
    or new.decision <> 'approved'
    or new.approved_by <> (select draft.owner_user_id from public.proposal_collaboration_drafts draft where draft.id = new.draft_id)
  ) then
    raise exception 'The owning organization is accepted automatically and cannot submit a review decision' using errcode = '42501';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_subtask_template(p_template_id uuid, p_payload jsonb)
 RETURNS subtask_templates
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_name text;
  target_org uuid;
  template_row public.subtask_templates;
  item jsonb;
  item_count int;
begin
  if caller is null then raise exception 'Not authenticated' using errcode = '42501'; end if;
  if btrim(coalesce(p_payload ->> 'title', '')) = '' then
    raise exception 'Template name is required' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_payload -> 'items', '[]'::jsonb)) <> 'array' then
    raise exception 'Template items must be an array' using errcode = '22023';
  end if;
  item_count := jsonb_array_length(coalesce(p_payload -> 'items', '[]'::jsonb));
  if item_count = 0 then raise exception 'Add at least one subtask' using errcode = '22023'; end if;

  if p_template_id is null then
    target_org := nullif(p_payload ->> 'orgId', '')::uuid;
    if target_org is null or not public.can_use_work_templates(target_org, caller) then
      raise exception 'You may only create templates for the department where you lead work'
        using errcode = '42501';
    end if;
    select full_name into caller_name from public.profiles where id = caller;
    insert into public.subtask_templates (
      org_id, owner_id, owner_name, title, description, visibility
    ) values (
      target_org,
      caller,
      coalesce(caller_name, 'User'),
      btrim(p_payload ->> 'title'),
      btrim(coalesce(p_payload ->> 'description', '')),
      case when p_payload ->> 'visibility' = 'department' then 'department' else 'personal' end
    ) returning * into template_row;
  else
    select * into template_row
    from public.subtask_templates
    where id = p_template_id
    for update;
    if not found then raise exception 'Template not found' using errcode = 'P0002'; end if;
    if template_row.owner_id <> caller
       and not (
         template_row.visibility = 'department'
         and public.can_approve_work_templates(template_row.org_id, caller)
       ) then
      raise exception 'You cannot edit this template' using errcode = '42501';
    end if;
    update public.subtask_templates
    set
      title = btrim(p_payload ->> 'title'),
      description = btrim(coalesce(p_payload ->> 'description', '')),
      visibility = case when p_payload ->> 'visibility' = 'department' then 'department' else 'personal' end
    where id = p_template_id
    returning * into template_row;
    delete from public.subtask_template_items where template_id = p_template_id;
  end if;

  for item in select value from jsonb_array_elements(p_payload -> 'items') loop
    if btrim(coalesce(item ->> 'title', '')) = '' then
      raise exception 'Every checklist item needs a title' using errcode = '22023';
    end if;
    insert into public.subtask_template_items (template_id, title, position)
    values (
      template_row.id,
      btrim(item ->> 'title'),
      coalesce((item ->> 'position')::int, 0)
    );
  end loop;

  select * into template_row from public.subtask_templates where id = template_row.id;
  return template_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.review_subtask_template(p_template_id uuid, p_approve boolean)
 RETURNS subtask_templates
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  template_row public.subtask_templates;
begin
  select * into template_row from public.subtask_templates where id = p_template_id for update;
  if not found then raise exception 'Template not found' using errcode = 'P0002'; end if;
  if template_row.visibility <> 'department' then
    raise exception 'Personal templates do not require approval' using errcode = '22023';
  end if;
  if not public.can_approve_work_templates(template_row.org_id, caller) then
    raise exception 'Only a Head or Assistant Head may approve department templates'
      using errcode = '42501';
  end if;
  update public.subtask_templates
  set approval_status = case when p_approve then 'approved' else 'rejected' end
  where id = p_template_id
  returning * into template_row;
  return template_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_subtask_template(p_template_id uuid, p_task_id uuid, p_mode text, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_name text;
  template_row public.subtask_templates;
  task_row public.tasks;
  item jsonb;
  assigned_ids uuid[];
  next_position int;
  created_count int := 0;
  skipped_count int := 0;
  replaced_count int := 0;
  item_title text;
begin
  if caller is null then raise exception 'Not authenticated' using errcode = '42501'; end if;
  if p_mode not in ('merge', 'replace') then
    raise exception 'Apply mode must be merge or replace' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(p_items, '[]'::jsonb)) = 0 then
    raise exception 'Keep at least one checklist item' using errcode = '22023';
  end if;

  select * into template_row from public.subtask_templates where id = p_template_id;
  if not found then raise exception 'Template not found' using errcode = 'P0002'; end if;
  if template_row.visibility = 'personal' and template_row.owner_id <> caller then
    raise exception 'This personal template belongs to another user'
      using errcode = '42501';
  end if;
  if template_row.approval_status <> 'approved' then
    raise exception 'This department template is not approved yet' using errcode = '22023';
  end if;

  select * into task_row
  from public.tasks
  where id = p_task_id and deleted_at is null
  for update;
  if not found then raise exception 'Task not found' using errcode = 'P0002'; end if;
  if task_row.org_id is distinct from template_row.org_id then
    raise exception 'Template and task must belong to the same department'
      using errcode = '42501';
  end if;
  if task_row.archived_at is not null
     or task_row.status in ('for_review', 'completed', 'cancelled') then
    raise exception 'This task is locked and cannot receive template subtasks'
      using errcode = '22023';
  end if;
  if not public.can_manage_subtasks(p_task_id, caller) then
    raise exception 'Only the Team Lead may apply a subtask template to this task'
      using errcode = '42501';
  end if;

  if p_mode = 'replace' then
    if exists (
      select 1 from public.subtasks s
      where s.task_id = p_task_id
        and (
          s.status <> 'todo'
          or s.percent_complete > 0
          or s.is_completed
          or s.latest_submission_id is not null
        )
    ) then
      raise exception 'A subtask is already in progress or has review history and cannot be deleted or overridden'
        using errcode = '22023';
    end if;
    select count(*) into replaced_count from public.subtasks where task_id = p_task_id;
    delete from public.subtasks where task_id = p_task_id;
  end if;

  select coalesce(max(position), -1) + 1 into next_position
  from public.subtasks where task_id = p_task_id;
  select full_name into caller_name from public.profiles where id = caller;

  for item in select value from jsonb_array_elements(p_items) loop
    item_title := btrim(coalesce(item ->> 'title', ''));
    if item_title = '' then raise exception 'Every checklist item needs a title' using errcode = '22023'; end if;

    if p_mode = 'merge' and exists (
      select 1 from public.subtasks s
      where s.task_id = p_task_id and lower(btrim(s.title)) = lower(item_title)
    ) then
      skipped_count := skipped_count + 1;
      continue;
    end if;

    begin
      select coalesce(array_agg(value::uuid), '{}'::uuid[])
      into assigned_ids
      from jsonb_array_elements_text(coalesce(item -> 'assignedToIds', '[]'::jsonb));
    exception when invalid_text_representation then
      raise exception 'A selected subtask assignee is invalid' using errcode = '22023';
    end;

    if exists (
      select 1
      from unnest(assigned_ids) assigned_id
      left join public.profiles p on p.id = assigned_id
      where p.id is null or not p.is_active or p.org_id is distinct from task_row.org_id
    ) then
      raise exception 'Subtask assignees must be active members directly assigned to this department'
        using errcode = '42501';
    end if;

    insert into public.subtasks (
      task_id, title, source, position, created_by,
      assigned_to, assigned_to_ids
    ) values (
      p_task_id, item_title, 'template', next_position, caller,
      assigned_ids[1], assigned_ids
    );

    insert into public.notifications (
      user_id, type, title, message, task_id, task_title,
      actor_id, actor_name
    )
    select
      assigned_id,
      'assignment',
      'New Subtask Assignment',
      coalesce(caller_name, 'Your Team Lead') || ' assigned you to subtask "' || item_title || '" in "' || task_row.title || '".',
      task_row.id,
      task_row.title,
      caller,
      coalesce(caller_name, 'Team Lead')
    from unnest(assigned_ids) assigned_id
    where assigned_id <> caller;

    created_count := created_count + 1;
    next_position := next_position + 1;
  end loop;

  insert into public.audit_events (
    actor_id, actor_name, entity_type, entity_id, action, after_data, org_id
  ) values (
    caller,
    coalesce(caller_name, 'Team Lead'),
    'task',
    p_task_id::text,
    'subtask_template.applied',
    jsonb_build_object(
      'templateId', p_template_id,
      'mode', p_mode,
      'created', created_count,
      'skipped', skipped_count,
      'replaced', replaced_count
    ),
    task_row.org_id
  );

  return jsonb_build_object(
    'created', created_count,
    'skipped', skipped_count,
    'replaced', replaced_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.materialize_due_task_templates()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  template public.task_templates;
  generated_task public.tasks;
  generated_count int := 0;
  interval_count int;
  next_run timestamptz;
begin
  for template in
    select * from public.task_templates
    where is_active and next_run_at <= now()
    order by next_run_at
    for update skip locked
  loop
    if exists (
      select 1 from public.task_template_runs
      where template_id = template.id and scheduled_for = template.next_run_at
    ) then
      interval_count := case
        when coalesce(template.recurrence_rule ->> 'interval', '') ~ '^\d+$'
          then greatest((template.recurrence_rule ->> 'interval')::int, 1)
        else 1
      end;
      next_run := case template.recurrence_rule ->> 'frequency'
        when 'daily' then template.next_run_at + make_interval(days => interval_count)
        when 'monthly' then template.next_run_at + make_interval(months => interval_count)
        else template.next_run_at + make_interval(weeks => interval_count)
      end;
      update public.task_templates set next_run_at = next_run where id = template.id;
      continue;
    end if;

    insert into public.tasks (
      title, description, status, priority, tags,
      acceptance_criteria, definition_of_done, org_id,
      assigned_to, reviewer_id, team_member_ids,
      created_by, last_activity_at
    ) values (
      template.title,
      template.description,
      case when template.assignee_id is null then 'pending_assignment' else 'todo' end,
      template.priority,
      template.tags,
      template.acceptance_criteria,
      template.definition_of_done,
      template.org_id,
      template.assignee_id,
      template.reviewer_id,
      case
        when template.assignee_id is null then '{}'::uuid[]
        else array[template.assignee_id]::uuid[]
      end,
      template.created_by,
      now()
    ) returning * into generated_task;

    insert into public.task_template_runs (template_id, task_id, scheduled_for)
    values (template.id, generated_task.id, template.next_run_at);

    if template.assignee_id is not null then
      insert into public.notifications (user_id, type, title, message, task_id, task_title)
      values (
        template.assignee_id,
        'assignment',
        'Recurring task assigned',
        'A recurring task was created: "' || template.title || '".',
        generated_task.id,
        template.title
      );
    end if;

    interval_count := case
      when coalesce(template.recurrence_rule ->> 'interval', '') ~ '^\d+$'
        then greatest((template.recurrence_rule ->> 'interval')::int, 1)
      else 1
    end;
    next_run := case template.recurrence_rule ->> 'frequency'
      when 'daily' then template.next_run_at + make_interval(days => interval_count)
      when 'monthly' then template.next_run_at + make_interval(months => interval_count)
      else template.next_run_at + make_interval(weeks => interval_count)
    end;
    update public.task_templates set next_run_at = next_run where id = template.id;
    generated_count := generated_count + 1;
  end loop;
  return generated_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.can_access_org(p_user_id uuid, p_org_id uuid, p_access_level text DEFAULT 'read'::text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  requested_rank integer;
  caller_role text;
begin
  if p_user_id is null or p_org_id is null then return false; end if;
  requested_rank := case p_access_level
    when 'read' then 1
    when 'review' then 2
    when 'manage' then 3
    else 99
  end;
  if requested_rank = 99 then return false; end if;

  caller_role := public.auth_role(p_user_id);
  if caller_role = 'admin' then return true; end if;

  -- Preserve the existing Head/Assistant Head organization subtree scope.
  if caller_role in ('dept_head', 'department_head', 'assistant_head')
     and public.org_in_my_subtree(p_org_id, p_user_id) then
    return true;
  end if;

  -- An explicit grant covers the selected organization and its descendants.
  return exists (
    select 1
    from public.user_org_scope_grants grant_row
    join public.organizations grant_org on grant_org.id = grant_row.org_id
    join public.organizations target_org on target_org.id = p_org_id
    where grant_row.user_id = p_user_id
      and (grant_row.expires_at is null or grant_row.expires_at > now())
      and (
        target_org.path::text = grant_org.path::text
        or target_org.path::text like grant_org.path::text || '.%'
      )
      and case grant_row.access_level
        when 'read' then 1
        when 'review' then 2
        when 'manage' then 3
        else 0
      end >= requested_rank
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.audit_access_control_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_name text := '';
  entity_key text;
  target_org uuid;
begin
  select coalesce(full_name, '') into caller_name
  from public.profiles where id = caller;

  if tg_table_name = 'role_permissions' then
    entity_key := coalesce(new.role, old.role) || ':' || coalesce(new.permission, old.permission);
  elsif tg_table_name = 'user_permission_overrides' then
    entity_key := coalesce(new.user_id, old.user_id)::text || ':' || coalesce(new.permission, old.permission);
  else
    entity_key := coalesce(new.id, old.id)::text;
    target_org := coalesce(new.org_id, old.org_id);
  end if;

  insert into public.audit_events (
    actor_id, actor_name, entity_type, entity_id, action,
    before_data, after_data, org_id
  ) values (
    caller, caller_name, tg_table_name, entity_key,
    'access.' || tg_table_name || '.' || lower(tg_op),
    case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) else null end,
    case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) else null end,
    target_org
  );
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.reorder_task_subtasks(p_task_id uuid, p_ordered_ids uuid[])
 RETURNS SETOF subtasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_name text := '';
  parent_task public.tasks;
  existing_count integer;
  supplied_count integer;
  matching_count integer;
  before_order jsonb;
  after_order jsonb;
begin
  if caller is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  select * into parent_task
  from public.tasks
  where id = p_task_id and deleted_at is null
  for update;
  if not found then
    raise exception 'Parent task was not found' using errcode = 'P0002';
  end if;
  if not public.can_manage_subtasks(p_task_id, caller) then
    raise exception 'Only the task lead or an authorized manager can reorder subtasks'
      using errcode = '42501';
  end if;
  if parent_task.archived_at is not null
     or parent_task.status in ('for_review', 'completed', 'cancelled') then
    raise exception 'Subtask order is locked while the parent task is under review, completed, cancelled, or archived'
      using errcode = '22023';
  end if;

  perform 1 from public.subtasks where task_id = p_task_id for update;
  select count(*), coalesce(jsonb_agg(
    jsonb_build_object('id', id, 'position', position)
    order by position, created_at, id
  ), '[]'::jsonb)
  into existing_count, before_order
  from public.subtasks
  where task_id = p_task_id;

  supplied_count := coalesce(cardinality(p_ordered_ids), 0);
  if supplied_count <> existing_count then
    raise exception 'The ordered list must contain every subtask exactly once'
      using errcode = '22023';
  end if;
  if exists (select 1 from unnest(p_ordered_ids) id where id is null)
     or (select count(distinct id) from unnest(p_ordered_ids) id) <> supplied_count then
    raise exception 'The ordered list contains a missing or duplicate subtask ID'
      using errcode = '22023';
  end if;

  select count(*) into matching_count
  from public.subtasks
  where task_id = p_task_id and id = any(p_ordered_ids);
  if matching_count <> existing_count then
    raise exception 'Every supplied subtask must belong to the same parent task'
      using errcode = '22023';
  end if;

  perform set_config('eflow.subtask_workflow_authorized', 'on', true);
  set constraints subtasks_task_position_unique deferred;
  update public.subtasks subtask
  set position = ordered.ordinality - 1
  from unnest(p_ordered_ids) with ordinality as ordered(id, ordinality)
  where subtask.id = ordered.id and subtask.task_id = p_task_id;
  set constraints subtasks_task_position_unique immediate;
  perform set_config('eflow.subtask_workflow_authorized', 'off', true);

  select coalesce(jsonb_agg(
    jsonb_build_object('id', id, 'position', position)
    order by position
  ), '[]'::jsonb)
  into after_order
  from public.subtasks where task_id = p_task_id;

  select coalesce(full_name, '') into caller_name
  from public.profiles where id = caller;
  insert into public.audit_events (
    actor_id, actor_name, entity_type, entity_id, action,
    before_data, after_data, org_id
  ) values (
    caller, caller_name, 'task', p_task_id::text, 'subtasks.reordered',
    jsonb_build_object('order', before_order),
    jsonb_build_object('order', after_order),
    parent_task.org_id
  );

  return query
  select * from public.subtasks
  where task_id = p_task_id
  order by position, created_at, id;
exception when others then
  perform set_config('eflow.subtask_workflow_authorized', 'off', true);
  raise;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_subtask_execution_dependencies()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  workflow_authorized boolean :=
    coalesce(current_setting('eflow.subtask_workflow_authorized', true), 'off') = 'on';
  blocking_title text;
  blocking_step integer;
begin
  -- Direct edits are handled by guard_subtask_contributor_update. Execution
  -- dependencies apply to the evidence/progress RPC workflow only.
  if not workflow_authorized then
    if new.is_standalone is distinct from old.is_standalone
       and (old.status <> 'todo' or old.percent_complete > 0) then
      raise exception 'Execution mode cannot change after subtask work has started'
        using errcode = '22023',
          hint = 'Reset or finish the existing work before changing between sequential and standalone.';
    end if;
    return new;
  end if;

  -- A reviewer must still be able to approve or request changes for evidence
  -- that was valid when submitted.
  if old.status = 'for_review' or new.is_standalone then
    return new;
  end if;

  select prerequisite.title, (
    select count(*)::integer
    from public.subtasks numbered
    where numbered.task_id = prerequisite.task_id
      and numbered.is_standalone = false
      and numbered.position <= prerequisite.position
  )
    into blocking_title, blocking_step
  from public.subtasks prerequisite
  where prerequisite.task_id = new.task_id
    and prerequisite.id <> new.id
    and prerequisite.position < new.position
    and prerequisite.is_standalone = false
    and prerequisite.is_completed = false
  order by prerequisite.position, prerequisite.created_at, prerequisite.id
  limit 1;

  if blocking_title is not null then
    raise exception 'Complete Step %: "%" before starting this subtask',
      blocking_step, blocking_title
      using errcode = '22023',
        detail = 'Ordered subtasks must be approved in sequence.',
        hint = 'Ask the Team Lead to mark this subtask Standalone only when it is genuinely independent.';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_subtask_due_date(p_subtask_id uuid, p_due_date date, p_reason text DEFAULT NULL::text)
 RETURNS subtasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_name text := '';
  subtask public.subtasks;
  parent_task public.tasks;
  reason_required boolean;
  previous_due date;
begin
  if caller is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  select * into subtask
  from public.subtasks
  where id = p_subtask_id
  for update;
  if not found then raise exception 'Subtask not found' using errcode = 'P0002'; end if;

  select * into parent_task
  from public.tasks
  where id = subtask.task_id and deleted_at is null
  for update;
  if not found then raise exception 'Parent task not found' using errcode = 'P0002'; end if;

  if not public.can_manage_subtasks(subtask.task_id, caller) then
    raise exception 'Only the Task Lead or an authorized manager may change a subtask deadline'
      using errcode = '42501';
  end if;
  if public.auth_role(caller) = 'admin' then
    raise exception 'Admin task oversight is read-only' using errcode = '42501';
  end if;
  if parent_task.archived_at is not null
     or parent_task.status in ('for_review', 'completed', 'cancelled') then
    raise exception 'Subtask deadlines are locked while the parent task is under review, completed, cancelled, or archived'
      using errcode = '22023';
  end if;
  if p_due_date is null then
    raise exception 'A subtask due date is required' using errcode = '22023';
  end if;
  if p_due_date is not null and (
    (parent_task.due_date ~ '^\d{4}-\d{2}-\d{2}' and p_due_date > left(parent_task.due_date, 10)::date)
    or (not coalesce(parent_task.due_date ~ '^\d{4}-\d{2}-\d{2}', false) and coalesce(parent_task.deadline ~ '^\d{4}-\d{2}-\d{2}', false) and p_due_date > left(parent_task.deadline, 10)::date)
  ) then
    raise exception 'Subtask due date cannot be later than its parent task due date'
      using errcode = '22023';
  end if;

  if subtask.due_date is not distinct from p_due_date then return subtask; end if;
  previous_due := subtask.due_date;
  reason_required := subtask.status <> 'todo' or subtask.percent_complete > 0;
  if reason_required and coalesce(btrim(p_reason), '') = '' then
    raise exception 'A reason is required after subtask work has started'
      using errcode = '22023';
  end if;

  select coalesce(full_name, 'Task Lead') into caller_name
  from public.profiles where id = caller;

  perform set_config('eflow.subtask_deadline_authorized', 'on', true);
  update public.subtasks
  set due_date = p_due_date,
      due_date_change_reason = nullif(btrim(p_reason), ''),
      due_date_changed_at = now(),
      due_date_changed_by = caller,
      updated_at = now()
  where id = p_subtask_id
  returning * into subtask;
  perform set_config('eflow.subtask_deadline_authorized', 'off', true);

  insert into public.audit_events (
    actor_id, actor_name, entity_type, entity_id, action, reason,
    before_data, after_data, org_id
  ) values (
    caller, caller_name, 'subtask', subtask.id::text, 'subtask.deadline.updated',
    nullif(btrim(p_reason), ''),
    jsonb_build_object('dueDate', previous_due),
    jsonb_build_object('dueDate', p_due_date), parent_task.org_id
  );

  insert into public.notifications (
    user_id, type, title, message, task_id, task_title, actor_id, actor_name,
    reason, project_id, proposal_id, org_id, entity_type
  )
  select recipient_id, 'status_change', 'Subtask deadline updated',
    caller_name || ' changed the deadline for "' || subtask.title || '" to ' || coalesce(to_char(p_due_date, 'Mon DD, YYYY'), 'No deadline') || '.',
    parent_task.id, parent_task.title, caller, caller_name,
    nullif(btrim(p_reason), ''), parent_task.linked_project_id,
    parent_task.proposal_id, parent_task.org_id, 'subtask'
  from (
    select distinct recipient_id
    from unnest(
      coalesce(subtask.assigned_to_ids, '{}'::uuid[])
      || array_remove(array[subtask.assigned_to], null)
    ) recipient_id
  ) recipients
  where recipient_id <> caller;

  return subtask;
exception when others then
  perform set_config('eflow.subtask_deadline_authorized', 'off', true);
  raise;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_profile_leadership_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.is_active and new.role in ('dept_head', 'department_head') then
    if new.org_id is null or not exists (
      select 1 from public.organizations o
      where o.id = new.org_id and o.head_user_id = new.id and o.is_active
    ) then
      raise exception 'Assign Head through the organization leadership slot'
        using errcode = '23514';
    end if;
  elsif new.is_active and new.role = 'assistant_head' then
    if new.org_id is null or not exists (
      select 1 from public.organizations o
      where o.id = new.org_id and o.assistant_head_user_id = new.id and o.is_active
    ) then
      raise exception 'Assign Assistant Head through the organization leadership slot'
        using errcode = '23514';
    end if;
  end if;

  if tg_op = 'UPDATE' and exists (
    select 1 from public.organizations o
    where o.head_user_id = old.id
      and (not new.is_active or new.role not in ('dept_head', 'department_head') or new.org_id is distinct from o.id)
  ) then
    raise exception 'Clear or replace this user in the organization Head slot first'
      using errcode = '23514';
  end if;

  if tg_op = 'UPDATE' and exists (
    select 1 from public.organizations o
    where o.assistant_head_user_id = old.id
      and (not new.is_active or new.role <> 'assistant_head' or new.org_id is distinct from o.id)
  ) then
    raise exception 'Clear or replace this user in the organization Assistant Head slot first'
      using errcode = '23514';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_project_with_details(p_payload jsonb)
 RETURNS projects
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_profile public.profiles;
  target_org uuid;
  selected_owner uuid;
  project_status text := coalesce(nullif(trim(p_payload ->> 'status'), ''), 'planning');
  project_priority text := coalesce(nullif(trim(p_payload ->> 'priority'), ''), 'medium');
  project_source text := coalesce(nullif(trim(p_payload ->> 'source_type'), ''), 'standalone');
  created_project public.projects;
  member_value text;
  milestone_value jsonb;
begin
  if caller is null then raise exception 'Authentication is required to create a project' using errcode = '42501'; end if;
  select * into caller_profile from public.profiles where id = caller and is_active;
  if not found then raise exception 'An active eFlow profile is required to create a project' using errcode = '42501'; end if;
  if nullif(trim(p_payload ->> 'title'), '') is null then raise exception 'Project title is required' using errcode = '22023'; end if;
  if project_status not in ('planning', 'active', 'on_hold', 'completed', 'archived') then raise exception 'Invalid project status' using errcode = '22023'; end if;
  if project_priority not in ('low', 'medium', 'high') then raise exception 'Invalid project priority' using errcode = '22023'; end if;
  if project_source not in ('ai_pdf', 'manual', 'standalone') then raise exception 'Invalid project source type' using errcode = '22023'; end if;

  target_org := coalesce(nullif(p_payload ->> 'org_id', '')::uuid, caller_profile.org_id);
  if not public.can_create_scoped_work(target_org, caller) then raise exception 'You cannot create projects in this organization' using errcode = '42501'; end if;
  selected_owner := coalesce(nullif(p_payload ->> 'owner_id', '')::uuid, caller);
  if not exists (select 1 from public.profiles where id = selected_owner and is_active) then raise exception 'Project owner must be an active eFlow user' using errcode = '22023'; end if;

  insert into public.projects (
    title, description, org_id, owner_id, status, priority, start_date, target_date,
    created_by, proposal_id, proposal_title, program_id, program_title, source_type, source_file_name
  ) values (
    trim(p_payload ->> 'title'), coalesce(p_payload ->> 'description', ''), target_org,
    selected_owner, project_status, project_priority, nullif(p_payload ->> 'start_date', '')::date,
    nullif(p_payload ->> 'target_date', '')::date, caller, nullif(p_payload ->> 'proposal_id', ''),
    nullif(p_payload ->> 'proposal_title', ''), nullif(p_payload ->> 'program_id', ''),
    nullif(p_payload ->> 'program_title', ''), project_source, nullif(p_payload ->> 'source_file_name', '')
  ) returning * into created_project;

  insert into public.project_members (project_id, user_id, role)
  values (created_project.id, selected_owner, 'owner')
  on conflict (project_id, user_id) do update set role = excluded.role;

  for member_value in select value from jsonb_array_elements_text(coalesce(p_payload -> 'member_ids', '[]'::jsonb)) loop
    if member_value <> '' and member_value::uuid <> selected_owner then
      if not exists (select 1 from public.profiles where id = member_value::uuid and is_active) then raise exception 'Every project member must be an active eFlow user' using errcode = '22023'; end if;
      insert into public.project_members (project_id, user_id, role)
      values (created_project.id, member_value::uuid, 'member')
      on conflict (project_id, user_id) do nothing;
    end if;
  end loop;

  for milestone_value in select value from jsonb_array_elements(coalesce(p_payload -> 'milestones', '[]'::jsonb)) loop
    if nullif(trim(milestone_value ->> 'title'), '') is not null then
      insert into public.milestones (project_id, title, description, due_date, sort_order)
      values (created_project.id, trim(milestone_value ->> 'title'), coalesce(milestone_value ->> 'description', ''), nullif(milestone_value ->> 'due_date', '')::date, coalesce((milestone_value ->> 'sort_order')::int, 0));
    end if;
  end loop;
  return created_project;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_super_admin_project_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is not null and public.is_super_admin(auth.uid()) then
    raise exception 'Admin project access is read-only. Ask the organization Head or Assistant Head to make this change.'
      using errcode = '42501';
