CREATE OR REPLACE FUNCTION public.guard_subtask_due_date_bounds()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  parent_due date;
begin
  select case
    when task.due_date ~ '^\d{4}-\d{2}-\d{2}' then left(task.due_date, 10)::date
    when task.deadline ~ '^\d{4}-\d{2}-\d{2}' then left(task.deadline, 10)::date
    else null
  end
  into parent_due
  from public.tasks task
  where task.id = new.task_id and task.deleted_at is null;

  if tg_op = 'INSERT' and new.due_date is null then
    new.due_date := parent_due;
  end if;
  if new.due_date is null then return new; end if;

  if parent_due is not null and new.due_date > parent_due then
    raise exception 'Subtask due date cannot be later than its parent task due date (%)', parent_due
      using errcode = '22023';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.is_collaboration_participant(target_draft uuid, caller_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare draft_row public.proposal_collaboration_drafts;
begin
  if target_draft is null or caller_id is null then return false; end if;
  select * into draft_row from public.proposal_collaboration_drafts
  where id = target_draft and deleted_at is null;
  if not found then return false; end if;
  if public.auth_role(caller_id) = 'admin' then return true; end if;
  if draft_row.owner_user_id = caller_id
     or public.is_organization_approver(draft_row.owner_org_id, caller_id)
     or public.is_organization_member(draft_row.owner_org_id, caller_id) then
    return true;
  end if;
  if exists (
    select 1 from public.proposal_collaboration_orgs participant
    where participant.draft_id = target_draft
      and (
        public.is_organization_approver(participant.org_id, caller_id)
        or public.is_organization_member(participant.org_id, caller_id)
      )
  ) then return true; end if;
  if exists (
    select 1
    from public.projects project
    left join public.project_members member
      on member.project_id = project.id and member.user_id = caller_id
    where project.source_collaboration_draft_id = target_draft
      and (project.owner_id = caller_id or project.created_by = caller_id or member.user_id is not null)
  ) then return true; end if;
  return exists (
    select 1
    from public.tasks task
    where task.source_collaboration_draft_id = target_draft
      and task.deleted_at is null
      and (
        task.assigned_to = caller_id
        or task.recommendation_lead_id = caller_id
        or task.reviewer_id = caller_id
        or task.backup_reviewer_id = caller_id
        or coalesce(to_jsonb(task.team_member_ids), '[]'::jsonb) ? caller_id::text
        or exists (
          select 1 from public.subtasks subtask
          where subtask.task_id = task.id
            and coalesce(subtask.assigned_to_ids, '{}'::uuid[]) @> array[caller_id]
        )
      )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.collaboration_storage_draft_id(object_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
begin
  return split_part(object_name, '/', 1)::uuid;
exception when others then return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.refresh_collaboration_readiness(target_draft uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  readiness jsonb;
  was_ready boolean;
  now_ready boolean;
  draft_row public.proposal_collaboration_drafts;
begin
  select * into draft_row from public.proposal_collaboration_drafts where id = target_draft for update;
  if not found then return false; end if;
  was_ready := draft_row.status = 'ready_to_commit';
  readiness := public.collaboration_readiness(target_draft);
  now_ready := coalesce((readiness ->> 'ready')::boolean, false);
  update public.proposal_collaboration_drafts
  set status = case
    when now_ready then 'ready_to_commit'
    when status in ('ready_to_commit', 'in_review') then 'in_review'
    else status
  end
  where id = target_draft;

  if now_ready and not was_ready then
    insert into public.notifications (
      user_id, type, title, message, proposal_id, org_id, entity_type
    ) values (
      draft_row.owner_user_id, 'collaboration_ready', 'Proposal ready to commit',
      'All required organizations approved "' || draft_row.title || '". The proposal is ready for atomic commit.',
      target_draft::text, draft_row.owner_org_id, 'collaboration_draft'
    );
    insert into public.audit_events (actor_name, entity_type, entity_id, action, after_data, org_id)
    values ('eFlow', 'collaboration_draft', target_draft::text, 'collaboration.ready_to_commit', readiness, draft_row.owner_org_id);
  end if;
  return now_ready;
end;
$function$

CREATE OR REPLACE FUNCTION public.send_collaboration_message(p_draft_id uuid, p_message text, p_target_type text DEFAULT 'proposal'::text, p_target_key text DEFAULT NULL::text, p_message_type text DEFAULT 'comment'::text)
 RETURNS proposal_collaboration_messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  profile_row public.profiles;
  draft_row public.proposal_collaboration_drafts;
  message_row public.proposal_collaboration_messages;
begin
  if not public.is_collaboration_participant(p_draft_id, caller) then raise exception 'Not allowed to participate in this collaboration' using errcode = '42501'; end if;
  if nullif(btrim(p_message), '') is null then raise exception 'Message is required' using errcode = '22023'; end if;
  if p_message_type not in ('comment', 'system', 'change_request_comment') or p_message_type = 'system' then
    raise exception 'Invalid message type' using errcode = '22023';
  end if;
  select * into profile_row from public.profiles where id = caller and is_active;
  select * into draft_row from public.proposal_collaboration_drafts where id = p_draft_id;
  insert into public.proposal_collaboration_messages (
    draft_id, revision_id, author_id, author_org_id, message, message_type, target_type, target_key
  ) values (
    p_draft_id, draft_row.current_revision_id, caller, profile_row.org_id,
    btrim(p_message), p_message_type, p_target_type, nullif(btrim(p_target_key), '')
  ) returning * into message_row;

  insert into public.notifications (user_id, type, title, message, actor_id, actor_name, proposal_id, org_id, entity_type)
  select distinct approver_id, 'collaboration_message', 'New collaboration message',
    profile_row.full_name || ' commented on "' || draft_row.title || '".',
    caller, profile_row.full_name, p_draft_id::text, participating.org_id, 'collaboration_draft'
  from public.proposal_collaboration_orgs participating
  cross join lateral public.organization_approver_ids(participating.org_id) approver_id
  where participating.draft_id = p_draft_id and approver_id <> caller;
  insert into public.audit_events (actor_id, actor_name, entity_type, entity_id, action, after_data, org_id)
  values (caller, profile_row.full_name, 'collaboration_message', message_row.id::text,
    'collaboration.message_sent',
    jsonb_build_object('draftId', p_draft_id, 'revisionId', draft_row.current_revision_id,
      'targetType', p_target_type, 'targetKey', p_target_key), draft_row.owner_org_id);
  return message_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_collaboration_change_request(p_draft_id uuid, p_target_type text, p_target_key text, p_reason text, p_proposed_change jsonb DEFAULT '{}'::jsonb, p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS proposal_collaboration_change_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  profile_row public.profiles;
  draft_row public.proposal_collaboration_drafts;
  request_row public.proposal_collaboration_change_requests;
  acting_org uuid;
begin
  if not public.is_collaboration_participant(p_draft_id, caller) or public.auth_role(caller) = 'admin' then
    raise exception 'Not allowed to request changes' using errcode = '42501';
  end if;
  if nullif(btrim(p_reason), '') is null or nullif(btrim(p_target_key), '') is null then raise exception 'Change target and reason are required' using errcode = '22023'; end if;
  select * into profile_row from public.profiles where id = caller and is_active;
  acting_org := p_organization_id;
  if acting_org is null and exists (
    select 1 from public.proposal_collaboration_orgs participating
    where participating.draft_id = p_draft_id and participating.org_id = profile_row.org_id
      and public.is_organization_approver(participating.org_id, caller)
  ) then acting_org := profile_row.org_id; end if;
  if acting_org is null then
    select participating.org_id into acting_org
    from public.proposal_collaboration_orgs participating
    join public.organization_memberships membership
      on membership.organization_id = participating.org_id and membership.user_id = caller
    where participating.draft_id = p_draft_id
      and membership.membership_role in ('primary_approver', 'backup_approver')
    order by case when participating.participation_role = 'governance' then 0 else 1 end
    limit 1;
  end if;
  if acting_org is null or not public.is_organization_approver(acting_org, caller)
     or not exists (select 1 from public.proposal_collaboration_orgs where draft_id = p_draft_id and org_id = acting_org) then
    raise exception 'Only an organization approver may request a formal change' using errcode = '42501';
  end if;
  select * into draft_row from public.proposal_collaboration_drafts where id = p_draft_id;
  insert into public.proposal_collaboration_change_requests (
    draft_id, revision_id, requested_by, requesting_org_id,
    target_type, target_key, reason, proposed_change
  ) values (
    p_draft_id, draft_row.current_revision_id, caller,
    acting_org,
    p_target_type, btrim(p_target_key), btrim(p_reason), coalesce(p_proposed_change, '{}'::jsonb)
  ) returning * into request_row;
  update public.proposal_collaboration_drafts set status = 'changes_requested' where id = p_draft_id;
  perform public.refresh_collaboration_readiness(p_draft_id);
  insert into public.notifications (user_id, type, title, message, actor_id, actor_name, proposal_id, org_id, entity_type)
  values (draft_row.owner_user_id, 'collaboration_change', 'Proposal changes requested',
    profile_row.full_name || ' requested a change to "' || draft_row.title || '".', caller, profile_row.full_name,
    p_draft_id::text, draft_row.owner_org_id, 'collaboration_draft');
  insert into public.audit_events (actor_id, actor_name, entity_type, entity_id, action, reason, after_data, org_id)
  values (caller, profile_row.full_name, 'collaboration_change_request', request_row.id::text,
    'collaboration.change_requested', request_row.reason, request_row.proposed_change, draft_row.owner_org_id);
  return request_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_collaboration_staffing_revision(p_draft_id uuid, p_organization_id uuid, p_snapshot jsonb, p_change_summary text DEFAULT 'Participating organization staffing updated'::text)
 RETURNS proposal_collaboration_revisions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  draft_row public.proposal_collaboration_drafts;
  current_row public.proposal_collaboration_revisions;
  revision_row public.proposal_collaboration_revisions;
  old_task jsonb;
  new_task jsonb;
  old_external uuid[];
  new_external uuid[];
  new_member uuid;
  next_number int;
  caller_name text := '';
begin
  if not public.is_organization_approver(p_organization_id, caller)
     or not exists (
       select 1 from public.proposal_collaboration_orgs participating
       where participating.draft_id = p_draft_id
         and participating.org_id = p_organization_id
         and participating.staffing_enabled
     ) then raise exception 'Only an approver for a staffing-enabled participant may revise this staffing' using errcode = '42501'; end if;
  select * into draft_row from public.proposal_collaboration_drafts where id = p_draft_id and deleted_at is null for update;
  if not found or draft_row.status = 'committed' then raise exception 'Draft is not editable' using errcode = '22023'; end if;
  select * into current_row from public.proposal_collaboration_revisions where id = draft_row.current_revision_id;
  if jsonb_typeof(p_snapshot -> 'tasks') <> 'array'
     or jsonb_array_length(p_snapshot -> 'tasks') <> jsonb_array_length(current_row.snapshot -> 'tasks') then
    raise exception 'Participating organizations cannot change proposal structure' using errcode = '42501';
  end if;

  for new_task in select value from jsonb_array_elements(p_snapshot -> 'tasks') loop
    select value into old_task from jsonb_array_elements(current_row.snapshot -> 'tasks') where value ->> 'key' = new_task ->> 'key';
    if old_task is null
       or (old_task - 'assignedMemberIds' - 'leadMemberId' - 'reasoning')
          <> (new_task - 'assignedMemberIds' - 'leadMemberId' - 'reasoning') then
      raise exception 'Participating organizations may change only their own staffing' using errcode = '42501';
    end if;
    old_external := array(
      select member_id from jsonb_array_elements_text(coalesce(old_task -> 'assignedMemberIds', '[]'::jsonb)) raw(member_text)
      cross join lateral (select raw.member_text::uuid member_id) member
      join public.profiles profile on profile.id = member.member_id
      where profile.org_id <> p_organization_id
      order by member_id
    );
    new_external := array(
      select member_id from jsonb_array_elements_text(coalesce(new_task -> 'assignedMemberIds', '[]'::jsonb)) raw(member_text)
      cross join lateral (select raw.member_text::uuid member_id) member
      join public.profiles profile on profile.id = member.member_id
      where profile.org_id <> p_organization_id
      order by member_id
    );
    if old_external is distinct from new_external then
      raise exception 'You cannot change another organization''s proposed employees' using errcode = '42501';
    end if;
    for new_member in select value::uuid from jsonb_array_elements_text(coalesce(new_task -> 'assignedMemberIds', '[]'::jsonb)) loop
      if not exists (select 1 from public.profiles where id = new_member and is_active) then raise exception 'Proposed employees must be active' using errcode = '22023'; end if;
    end loop;
    if nullif(new_task ->> 'leadMemberId', '') is not null
       and not (array(select value::uuid from jsonb_array_elements_text(coalesce(new_task -> 'assignedMemberIds', '[]'::jsonb))) @> array[(new_task ->> 'leadMemberId')::uuid]) then
      raise exception 'Task Leader must remain in the proposed team' using errcode = '22023';
    end if;
    if old_task ->> 'leadMemberId' is distinct from new_task ->> 'leadMemberId'
       and not exists (select 1 from public.profiles where id = (new_task ->> 'leadMemberId')::uuid and org_id = p_organization_id and is_active) then
      raise exception 'You may choose a new Task Leader only from your organization' using errcode = '42501';
    end if;
  end loop;
  if current_row.snapshot = p_snapshot then return current_row; end if;
  select coalesce(max(revision_number), 0) + 1 into next_number from public.proposal_collaboration_revisions where draft_id = p_draft_id;
  insert into public.proposal_collaboration_revisions (draft_id, revision_number, snapshot, created_by, change_summary)
  values (p_draft_id, next_number, p_snapshot, caller, coalesce(nullif(btrim(p_change_summary), ''), 'Staffing updated'))
  returning * into revision_row;
  update public.proposal_collaboration_drafts
  set working_snapshot = p_snapshot, current_revision_id = revision_row.id,
      status = case when status in ('in_review', 'ready_to_commit') then 'changes_requested' else status end
  where id = p_draft_id;
  select coalesce(full_name, 'Approver') into caller_name from public.profiles where id = caller;
  insert into public.audit_events (actor_id, actor_name, entity_type, entity_id, action, reason, after_data, org_id)
  values (caller, caller_name, 'collaboration_revision', revision_row.id::text, 'collaboration.staff_replaced', revision_row.change_summary,
    jsonb_build_object('draftId', p_draft_id, 'revision', next_number, 'organizationId', p_organization_id), draft_row.owner_org_id);
  insert into public.audit_events (actor_id, actor_name, entity_type, entity_id, action, reason, after_data, org_id)
  values (caller, caller_name, 'collaboration_revision', revision_row.id::text, 'collaboration.ai_assignment_changed', revision_row.change_summary,
    jsonb_build_object('draftId', p_draft_id, 'revision', next_number, 'organizationId', p_organization_id), draft_row.owner_org_id);
  insert into public.notifications (user_id, type, title, message, actor_id, actor_name, proposal_id, org_id, entity_type)
  values (draft_row.owner_user_id, 'collaboration_revision', 'Collaboration staffing updated',
    caller_name || ' updated proposed staffing for "' || draft_row.title || '". Approvals must be renewed.',
    caller, caller_name, p_draft_id::text, draft_row.owner_org_id, 'collaboration_draft');
  return revision_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_collaboration_change_request(p_request_id uuid, p_status text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  request_row public.proposal_collaboration_change_requests;
  draft_row public.proposal_collaboration_drafts;
  caller_name text := '';
begin
  select * into request_row from public.proposal_collaboration_change_requests where id = p_request_id for update;
  if not found then raise exception 'Change request not found' using errcode = 'P0002'; end if;
  select * into draft_row from public.proposal_collaboration_drafts where id = request_row.draft_id;
  if p_status not in ('accepted', 'rejected', 'withdrawn') then raise exception 'Invalid resolution' using errcode = '22023'; end if;
  if p_status = 'withdrawn' then
    if request_row.requested_by <> caller then raise exception 'Only the requester may withdraw this change' using errcode = '42501'; end if;
  elsif not public.can_manage_collaboration_draft(request_row.draft_id, caller) then
    raise exception 'Only the owning organization may resolve this change' using errcode = '42501';
  end if;
  update public.proposal_collaboration_change_requests
  set status = p_status, resolved_by = caller, resolved_at = now()
  where id = p_request_id and status = 'open';
  select coalesce(full_name, 'User') into caller_name from public.profiles where id = caller;
  insert into public.audit_events (actor_id, actor_name, entity_type, entity_id, action, reason, org_id)
  values (caller, caller_name, 'collaboration_change_request', p_request_id::text,
    'collaboration.change_' || p_status, nullif(btrim(p_reason), ''), draft_row.owner_org_id);
  perform public.refresh_collaboration_readiness(request_row.draft_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.decide_collaboration_review(p_draft_id uuid, p_organization_id uuid, p_decision text, p_reason text DEFAULT NULL::text)
 RETURNS proposal_collaboration_approvals
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  draft_row public.proposal_collaboration_drafts;
  approval_row public.proposal_collaboration_approvals;
  caller_name text := '';
begin
  if p_decision not in ('approved', 'changes_requested', 'declined') then raise exception 'Invalid review decision' using errcode = '22023'; end if;
  if p_decision <> 'approved' and nullif(btrim(p_reason), '') is null then raise exception 'A reason is required' using errcode = '22023'; end if;
  if not public.is_organization_approver(p_organization_id, caller) then raise exception 'Only an authorized organization approver may decide' using errcode = '42501'; end if;
  if not exists (select 1 from public.proposal_collaboration_orgs where draft_id = p_draft_id and org_id = p_organization_id) then raise exception 'Organization is not part of this proposal' using errcode = '42501'; end if;
  select * into draft_row from public.proposal_collaboration_drafts where id = p_draft_id for update;
  if draft_row.status not in ('in_review', 'changes_requested', 'ready_to_commit') then raise exception 'Draft is not in review' using errcode = '22023'; end if;

  insert into public.proposal_collaboration_approvals (
    draft_id, revision_id, organization_id, decision, approved_by, reason
  ) values (
    p_draft_id, draft_row.current_revision_id, p_organization_id, p_decision, caller, nullif(btrim(p_reason), '')
  ) returning * into approval_row;
  select coalesce(full_name, 'Approver') into caller_name from public.profiles where id = caller;

  if p_decision <> 'approved' then
    update public.proposal_collaboration_drafts set status = 'changes_requested' where id = p_draft_id;
  end if;
  insert into public.notifications (user_id, type, title, message, actor_id, actor_name, proposal_id, org_id, entity_type)
  values (draft_row.owner_user_id,
    case when p_decision = 'approved' then 'collaboration_approved' when p_decision = 'declined' then 'collaboration_declined' else 'collaboration_change' end,
    case when p_decision = 'approved' then 'Organization approved proposal' when p_decision = 'declined' then 'Organization declined proposal' else 'Organization requested changes' end,
    caller_name || ' marked "' || draft_row.title || '" as ' || replace(p_decision, '_', ' ') || '.',
    caller, caller_name, p_draft_id::text, draft_row.owner_org_id, 'collaboration_draft');
  insert into public.audit_events (actor_id, actor_name, entity_type, entity_id, action, reason, after_data, org_id)
  values (caller, caller_name, 'collaboration_approval', approval_row.id::text,
    case when p_decision = 'declined' then 'collaboration.declined' else 'collaboration.' || p_decision end,
    approval_row.reason, jsonb_build_object('draftId', p_draft_id, 'revisionId', draft_row.current_revision_id, 'organizationId', p_organization_id), draft_row.owner_org_id);
  perform public.refresh_collaboration_readiness(p_draft_id);
  return approval_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_collaboration_task_staffing()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  candidate uuid;
  candidate_org uuid;
  caller uuid := auth.uid();
  caller_org uuid;
  changed_candidate uuid;
begin
  if new.source_collaboration_draft_id is null then return new; end if;
  if new.assigned_to is null then raise exception 'Collaboration tasks require a Task Leader' using errcode = '22023'; end if;
  if not (coalesce(new.team_member_ids, '{}'::uuid[]) @> array[new.assigned_to]) then
    raise exception 'Task Leader must belong to the selected team' using errcode = '22023';
  end if;
  foreach candidate in array coalesce(new.team_member_ids, '{}'::uuid[]) loop
    select org_id into candidate_org from public.profiles where id = candidate and is_active;
    if candidate_org is null or not exists (
      select 1 from public.proposal_collaboration_orgs eligible
      where eligible.draft_id = new.source_collaboration_draft_id
        and eligible.org_id = candidate_org and eligible.staffing_enabled
    ) then
      raise exception 'Every collaboration team member must be active and belong to a staffing-enabled participating organization'
      using errcode = '22023';
    end if;
  end loop;
  if tg_op = 'UPDATE' and (
    new.assigned_to is distinct from old.assigned_to
    or coalesce(new.team_member_ids, '{}'::uuid[]) is distinct from coalesce(old.team_member_ids, '{}'::uuid[])
  ) then
    select org_id into caller_org from public.profiles where id = caller and is_active;
    if new.assigned_to is distinct from old.assigned_to
       and not exists (select 1 from public.profiles where id = new.assigned_to and org_id = caller_org and is_active) then
      raise exception 'Changing a cross-organization Task Leader requires approval from that employee''s organization'
        using errcode = '42501';
    end if;
    foreach changed_candidate in array (
      select coalesce(array_agg(member_id), '{}'::uuid[])
      from (
        (select unnest(coalesce(new.team_member_ids, '{}'::uuid[])) member_id
         except select unnest(coalesce(old.team_member_ids, '{}'::uuid[])))
        union
        (select unnest(coalesce(old.team_member_ids, '{}'::uuid[])) member_id
         except select unnest(coalesce(new.team_member_ids, '{}'::uuid[])))
      ) changes
    ) loop
      if not exists (select 1 from public.profiles where id = changed_candidate and org_id = caller_org) then
        raise exception 'Cross-organization staffing changes require approval from the employee''s organization'
          using errcode = '42501';
      end if;
    end loop;
  end if;
  if new.review_route_mode = 'governance' then
    if new.reviewer_id is null then raise exception 'Governed tasks require an active Board reviewer' using errcode = '22023'; end if;
    if new.reviewer_id = new.assigned_to or new.backup_reviewer_id = new.assigned_to then
      raise exception 'Task Leader cannot review their own Task' using errcode = '22023';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.commit_collaboration_draft(p_draft_id uuid, p_revision_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_name text := '';
  draft_row public.proposal_collaboration_drafts;
  revision_row public.proposal_collaboration_revisions;
  readiness jsonb;
  snapshot jsonb;
  task_item jsonb;
  project_item record;
  activity_item record;
  project_row public.projects;
  milestone_row public.milestones;
  task_row public.tasks;
  owner_org public.proposal_collaboration_orgs;
  governance_org public.proposal_collaboration_orgs;
  primary_reviewer uuid;
  backup_reviewer uuid;
  task_lead uuid;
  primary_org uuid;
  activity_primary_org uuid;
  member_ids uuid[];
  member_names text[];
  supporting_value text;
  selected_reviewer uuid;
  selected_backup uuid;
  route_mode text;
  project_ids uuid[] := '{}'::uuid[];
  project_target date;
  project_start date;
  milestone_due date;
  import_batch text;
begin
  if caller is null then raise exception 'Not authenticated' using errcode = '42501'; end if;
  if not public.can_manage_collaboration_draft(p_draft_id, caller) then
    raise exception 'Only the owning organization may commit this proposal' using errcode = '42501';
  end if;
  select * into draft_row from public.proposal_collaboration_drafts where id = p_draft_id for update;
  if not found then raise exception 'Collaboration draft not found' using errcode = 'P0002'; end if;
  if draft_row.status = 'committed' or draft_row.committed_at is not null then raise exception 'This proposal has already been committed' using errcode = '22023'; end if;
  if draft_row.current_revision_id is distinct from p_revision_id then raise exception 'Only the current revision can be committed' using errcode = '22023'; end if;
  select * into revision_row from public.proposal_collaboration_revisions where id = p_revision_id and draft_id = p_draft_id;
  if not found then raise exception 'Revision does not belong to this draft' using errcode = '22023'; end if;
  readiness := public.collaboration_readiness(p_draft_id);
  if not coalesce((readiness ->> 'ready')::boolean, false) then
    raise exception 'Approval requirements not complete: %', coalesce(readiness -> 'blockers', '[]'::jsonb)::text using errcode = '22023';
  end if;

  snapshot := revision_row.snapshot;
  if jsonb_typeof(snapshot -> 'tasks') <> 'array' or jsonb_array_length(snapshot -> 'tasks') = 0 then
    raise exception 'The approved revision contains no tasks' using errcode = '22023';
  end if;
  select * into owner_org from public.proposal_collaboration_orgs
  where draft_id = p_draft_id and participation_role = 'owner';
  if not found or owner_org.org_id <> draft_row.owner_org_id then raise exception 'Owner organization configuration is invalid' using errcode = '22023'; end if;

  select * into governance_org from public.proposal_collaboration_orgs
  where draft_id = p_draft_id and participation_role = 'governance'
  order by created_at limit 1;
  if found then
    select coalesce(
      (select membership.user_id from public.organization_memberships membership join public.profiles profile on profile.id = membership.user_id and profile.is_active where membership.organization_id = governance_org.org_id and membership.membership_role = 'primary_approver'),
      (select organization.head_user_id from public.organizations organization join public.profiles profile on profile.id = organization.head_user_id and profile.is_active where organization.id = governance_org.org_id)
    ) into primary_reviewer;
    select coalesce(
      (select membership.user_id from public.organization_memberships membership join public.profiles profile on profile.id = membership.user_id and profile.is_active where membership.organization_id = governance_org.org_id and membership.membership_role = 'backup_approver'),
      (select organization.assistant_head_user_id from public.organizations organization join public.profiles profile on profile.id = organization.assistant_head_user_id and profile.is_active where organization.id = governance_org.org_id)
    ) into backup_reviewer;
    if primary_reviewer is null and backup_reviewer is null then raise exception 'Governance organization requires an active Board Head or Board Assistant Head' using errcode = '22023'; end if;
  end if;

  import_batch := 'collaboration-' || p_draft_id::text || '-r' || revision_row.revision_number::text;

  -- Validate every staffing and responsibility record before the first insert.
  for task_item in
    select value from jsonb_array_elements(snapshot -> 'tasks')
    where coalesce((value ->> 'enabled')::boolean, true)
  loop
    task_lead := nullif(task_item ->> 'leadMemberId', '')::uuid;
    primary_org := coalesce(nullif(task_item ->> 'primaryOrgId', '')::uuid, draft_row.owner_org_id);
    member_ids := array(select value::uuid from jsonb_array_elements_text(coalesce(task_item -> 'assignedMemberIds', '[]'::jsonb)));
    if nullif(btrim(task_item ->> 'title'), '') is null then raise exception 'Every selected task needs a title' using errcode = '22023'; end if;
    if task_lead is null or not member_ids @> array[task_lead] then raise exception 'Every Task Leader must belong to their proposed team' using errcode = '22023'; end if;
    if not exists (select 1 from public.proposal_collaboration_orgs eligible where eligible.draft_id = p_draft_id and eligible.org_id = primary_org and eligible.staffing_enabled) then
      raise exception 'Task primary organization is not staffing-enabled for this proposal' using errcode = '22023';
    end if;
    if not exists (select 1 from public.profiles profile where profile.id = task_lead and profile.is_active) then raise exception 'Every Task Leader must be active' using errcode = '22023'; end if;
    if exists (
      select 1 from unnest(member_ids) member_id
      left join public.profiles profile on profile.id = member_id and profile.is_active
      where profile.id is null or not exists (
        select 1 from public.proposal_collaboration_orgs eligible
        where eligible.draft_id = p_draft_id and eligible.org_id = profile.org_id and eligible.staffing_enabled
      )
    ) then raise exception 'Every proposed employee must be active and belong to a staffing-enabled participating organization' using errcode = '22023'; end if;
    for supporting_value in select value from jsonb_array_elements_text(coalesce(task_item -> 'supportingOrgIds', '[]'::jsonb)) loop
      if supporting_value::uuid = primary_org or not exists (select 1 from public.proposal_collaboration_orgs where draft_id = p_draft_id and org_id = supporting_value::uuid) then
        raise exception 'Task supporting organization configuration is invalid' using errcode = '22023';
      end if;
    end loop;
    if governance_org.org_id is not null and task_lead = primary_reviewer and backup_reviewer is null then
      raise exception 'Approval requirements not complete: Board Head is Task Leader and no Board Assistant Head is configured' using errcode = '22023';
    end if;
    if governance_org.org_id is not null and task_lead = backup_reviewer and primary_reviewer is null then
      raise exception 'Approval requirements not complete: Board Assistant Head is Task Leader and no Board Head is configured' using errcode = '22023';
    end if;
  end loop;

  for project_item in
    select task ->> 'projectId' as project_key,
      max(task ->> 'projectTitle') as project_title,
      max(task ->> 'programId') as program_id,
      max(task ->> 'programTitle') as program_title,
      min(case when task ->> 'deadline' ~ '^\d{4}-\d{2}-\d{2}' then left(task ->> 'deadline', 10)::date end) as start_date,
      max(case when task ->> 'deadline' ~ '^\d{4}-\d{2}-\d{2}' then left(task ->> 'deadline', 10)::date end) as target_date
    from jsonb_array_elements(snapshot -> 'tasks') task
    where coalesce((task ->> 'enabled')::boolean, true)
    group by task ->> 'projectId'
  loop
    if nullif(btrim(project_item.project_key), '') is null or nullif(btrim(project_item.project_title), '') is null then raise exception 'Every task must belong to a valid project' using errcode = '22023'; end if;
    project_start := project_item.start_date;
    project_target := project_item.target_date;
    insert into public.projects (
      org_id, title, description, owner_id, status, priority, start_date, target_date,
      created_by, proposal_id, proposal_title, program_id, program_title,
      source_type, source_file_name, source_collaboration_draft_id, source_collaboration_revision_id
    ) values (
      draft_row.owner_org_id, project_item.project_title,
      case when draft_row.source_type = 'ai_pdf' then 'Imported through approved collaboration: ' else 'Approved collaborative plan: ' end || draft_row.title,
      draft_row.owner_user_id, 'active', 'medium', project_start, project_target,
      caller, coalesce(snapshot ->> 'proposalId', p_draft_id::text), draft_row.title,
      project_item.program_id, project_item.program_title, draft_row.source_type,
      draft_row.source_file_name, p_draft_id, p_revision_id
    ) returning * into project_row;
    project_ids := array_append(project_ids, project_row.id);
    insert into public.proposal_collaboration_commit_projects (draft_id, revision_id, project_key, project_id)
    values (p_draft_id, p_revision_id, project_item.project_key, project_row.id);

    insert into public.project_organizations (
      project_id, organization_id, participation_role, staffing_enabled, source_draft_id, source_revision_id
    ) select project_row.id, participating.org_id, participating.participation_role,
      participating.staffing_enabled, p_draft_id, p_revision_id
    from public.proposal_collaboration_orgs participating where participating.draft_id = p_draft_id;

    insert into public.project_members (project_id, user_id, role)
    values (project_row.id, draft_row.owner_user_id, 'owner')
    on conflict (project_id, user_id) do update set role = excluded.role;
    insert into public.project_members (project_id, user_id, role)
    select distinct project_row.id, member_id, 'member'
    from jsonb_array_elements(snapshot -> 'tasks') task
    cross join lateral jsonb_array_elements_text(coalesce(task -> 'assignedMemberIds', '[]'::jsonb)) member_text(value)
    cross join lateral (select member_text.value::uuid as member_id) member
    where task ->> 'projectId' = project_item.project_key
      and coalesce((task ->> 'enabled')::boolean, true)
    on conflict (project_id, user_id) do nothing;

    for activity_item in
      select task ->> 'activityId' as activity_key,
        max(task ->> 'activityTitle') as activity_title,
        max(task ->> 'activitySchedule') as activity_schedule,
        max(task ->> 'activityPrimaryOrgId') as primary_org_id,
        (jsonb_agg(coalesce(task -> 'activitySupportingOrgIds', '[]'::jsonb)) -> 0) as supporting_org_ids,
        max(case when task ->> 'deadline' ~ '^\d{4}-\d{2}-\d{2}' then left(task ->> 'deadline', 10)::date end) as due_date
      from jsonb_array_elements(snapshot -> 'tasks') task
      where task ->> 'projectId' = project_item.project_key and coalesce((task ->> 'enabled')::boolean, true)
      group by task ->> 'activityId'
    loop
      milestone_due := activity_item.due_date;
      insert into public.milestones (project_id, title, description, due_date, sort_order)
      values (project_row.id, activity_item.activity_title,
        case when nullif(activity_item.activity_schedule, '') is null then '' else 'Original schedule: ' || activity_item.activity_schedule end,
        milestone_due, (select count(*) from public.milestones where project_id = project_row.id))
      returning * into milestone_row;
      activity_primary_org := coalesce(nullif(activity_item.primary_org_id, '')::uuid, draft_row.owner_org_id);
      if not exists (
        select 1 from public.proposal_collaboration_orgs
        where draft_id = p_draft_id and org_id = activity_primary_org and staffing_enabled
      ) then raise exception 'Activity primary organization must be a staffing-enabled participant' using errcode = '22023'; end if;
      insert into public.milestone_organizations (milestone_id, organization_id, responsibility_role)
      values (milestone_row.id, activity_primary_org, 'primary');
      for supporting_value in select value from jsonb_array_elements_text(coalesce(activity_item.supporting_org_ids, '[]'::jsonb)) loop
        if supporting_value::uuid <> activity_primary_org then
          if not exists (
            select 1 from public.proposal_collaboration_orgs
            where draft_id = p_draft_id and org_id = supporting_value::uuid
          ) then raise exception 'Activity supporting organization is not participating' using errcode = '22023'; end if;
          insert into public.milestone_organizations (milestone_id, organization_id, responsibility_role)
          values (milestone_row.id, supporting_value::uuid, 'supporting') on conflict do nothing;
        end if;
      end loop;

      for task_item in
        select value from jsonb_array_elements(snapshot -> 'tasks')
        where value ->> 'projectId' = project_item.project_key
          and value ->> 'activityId' = activity_item.activity_key
          and coalesce((value ->> 'enabled')::boolean, true)
      loop
        task_lead := nullif(task_item ->> 'leadMemberId', '')::uuid;
        primary_org := coalesce(nullif(task_item ->> 'primaryOrgId', '')::uuid, activity_primary_org);
        member_ids := array(select value::uuid from jsonb_array_elements_text(coalesce(task_item -> 'assignedMemberIds', '[]'::jsonb)));
        select array_agg(profile.full_name order by member_position.ordinality)
        into member_names
        from unnest(member_ids) with ordinality member_position(member_id, ordinality)
        join public.profiles profile on profile.id = member_position.member_id;

        if governance_org.org_id is not null then
          route_mode := 'governance';
          selected_reviewer := case when task_lead = primary_reviewer then backup_reviewer else primary_reviewer end;
          selected_backup := case
            when task_lead = backup_reviewer or backup_reviewer = selected_reviewer then null
            else backup_reviewer
          end;
          if selected_reviewer is null or selected_reviewer = task_lead then raise exception 'No valid governance reviewer exists for task "%"', task_item ->> 'title' using errcode = '22023'; end if;
        else
          route_mode := 'organization_default';
          selected_reviewer := null;
          selected_backup := null;
        end if;

        insert into public.tasks (
          title, description, status, priority, assigned_to, assignee_name,
          department, org_id, team_id, team_name, team_member_ids, team_member_names,
          deadline, due_date, tags, recommended_employee_ids,
          recommendation_reasoning, recommendation_source, recommendation_lead_id,
          reviewer_id, backup_reviewer_id, proposal_id, proposal_title,
          program_id, program_title, project_id, project_title,
          activity_id, activity_title, activity_schedule, hierarchy_path,
          import_batch_id, linked_project_id, milestone_id, percent_complete, estimated_hours,
          review_route_mode, source_collaboration_draft_id,
          source_collaboration_revision_id, created_by
        ) values (
          btrim(task_item ->> 'title'), nullif(task_item ->> 'description', ''), 'todo',
          coalesce(nullif(task_item ->> 'priority', ''), 'medium'), task_lead,
          (select full_name from public.profiles where id = task_lead),
          primary_org::text, primary_org, primary_org::text,
          (select name from public.organizations where id = primary_org),
          member_ids, coalesce(member_names, '{}'::text[]),
          coalesce(task_item ->> 'deadline', ''), coalesce(task_item ->> 'deadline', ''),
          array(select value from jsonb_array_elements_text(coalesce(task_item -> 'requiredSkills', '[]'::jsonb))),
          member_ids, nullif(task_item ->> 'reasoning', ''),
          case when draft_row.source_type = 'ai_pdf' then 'import' else null end,
          task_lead, selected_reviewer, selected_backup,
          coalesce(snapshot ->> 'proposalId', p_draft_id::text), draft_row.title,
          project_item.program_id, project_item.program_title,
          project_item.project_key, project_item.project_title,
          activity_item.activity_key, activity_item.activity_title,
          activity_item.activity_schedule,
          concat_ws(' > ', draft_row.title, project_item.program_title, project_item.project_title, activity_item.activity_title),
          import_batch, project_row.id, milestone_row.id, 0,
          greatest(coalesce((task_item ->> 'estimatedHours')::numeric, 0), 0),
          route_mode, p_draft_id, p_revision_id, caller
        ) returning * into task_row;
        insert into public.task_organizations (task_id, organization_id, responsibility_role)
        values (task_row.id, primary_org, 'primary');
        for supporting_value in select value from jsonb_array_elements_text(coalesce(task_item -> 'supportingOrgIds', '[]'::jsonb)) loop
          if supporting_value::uuid <> primary_org then
            insert into public.task_organizations (task_id, organization_id, responsibility_role)
            values (task_row.id, supporting_value::uuid, 'supporting') on conflict do nothing;
          end if;
        end loop;
      end loop;
    end loop;
  end loop;

  update public.proposal_collaboration_drafts
  set status = 'committed', committed_at = now(), working_snapshot = revision_row.snapshot
  where id = p_draft_id;
  select coalesce(full_name, 'Owner') into caller_name from public.profiles where id = caller;
  insert into public.audit_events (
    actor_id, actor_name, entity_type, entity_id, action, after_data, org_id
  ) values (
    caller, caller_name, 'collaboration_draft', p_draft_id::text,
    'collaboration.committed',
    jsonb_build_object('revisionId', p_revision_id, 'revision', revision_row.revision_number, 'projectIds', to_jsonb(project_ids)),
    draft_row.owner_org_id
  );
  insert into public.notifications (user_id, type, title, message, actor_id, actor_name, proposal_id, org_id, entity_type)
  select distinct approver_id, 'collaboration_approved', 'Work plan published',
    '"' || draft_row.title || '" is now operational in eFlow.', caller, caller_name,
    p_draft_id::text, participating.org_id, 'collaboration_draft'
  from public.proposal_collaboration_orgs participating
  cross join lateral public.organization_approver_ids(participating.org_id) approver_id
  where participating.draft_id = p_draft_id and approver_id <> caller;
  return jsonb_build_object(
    'draftId', p_draft_id,
    'revisionId', p_revision_id,
    'revisionNumber', revision_row.revision_number,
    'projectIds', to_jsonb(project_ids),
    'projectCount', cardinality(project_ids)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.save_department_fiscal_budget(p_org_id uuid, p_fiscal_year integer, p_petty_cash_limit numeric, p_request_limit numeric, p_underutilization_threshold numeric, p_notes text, p_lines jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  budget_id uuid;
  line jsonb;
  total numeric := 0;
begin
  if not public.is_department_budget_head(p_org_id, caller) then
    raise exception 'Only the assigned Department Head can create the annual budget' using errcode = '42501';
  end if;
  if p_fiscal_year < 2000 or p_fiscal_year > 2200 then raise exception 'Invalid fiscal year' using errcode = '22023'; end if;
  if p_petty_cash_limit < 0 or p_request_limit <= 0 or p_request_limit > p_petty_cash_limit then
    raise exception 'Petty-cash limits are invalid' using errcode = '22023';
  end if;
  if p_underutilization_threshold < 0 or p_underutilization_threshold > 100 then
    raise exception 'Utilization threshold must be from 0 to 100' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_lines, '[]'::jsonb)) = 0 then
    raise exception 'Add at least one annual budget line' using errcode = '22023';
  end if;
  for line in select value from jsonb_array_elements(p_lines) loop
    if nullif(btrim(line ->> 'expenseClass'), '') is null or nullif(btrim(line ->> 'category'), '') is null or nullif(btrim(line ->> 'particular'), '') is null
       or nullif(btrim(line ->> 'fundSource'), '') is null then
      raise exception 'Every budget line needs an expense class, category, particular, and fund source' using errcode = '22023';
    end if;
    if coalesce((line ->> 'amount')::numeric, -1) < 0 then raise exception 'Budget amounts cannot be negative' using errcode = '22023'; end if;
    total := total + (line ->> 'amount')::numeric;
  end loop;
  select id into budget_id from public.department_fiscal_budgets
  where org_id = p_org_id and fiscal_year = p_fiscal_year for update;
  if budget_id is not null and exists (select 1 from public.department_fiscal_budgets where id = budget_id and status <> 'draft') then
    raise exception 'The annual budget is locked and cannot be edited' using errcode = '22023';
  end if;
  if budget_id is null then
    insert into public.department_fiscal_budgets (
      org_id, fiscal_year, approved_amount, petty_cash_limit,
      petty_cash_request_limit, underutilization_threshold, notes, created_by
    ) values (
      p_org_id, p_fiscal_year, total, p_petty_cash_limit,
      p_request_limit, p_underutilization_threshold, nullif(btrim(p_notes), ''), caller
    ) returning id into budget_id;
  else
    update public.department_fiscal_budgets set
      approved_amount = total,
      petty_cash_limit = p_petty_cash_limit,
      petty_cash_request_limit = p_request_limit,
      underutilization_threshold = p_underutilization_threshold,
      notes = nullif(btrim(p_notes), ''),
      updated_at = now()
    where id = budget_id;
    delete from public.department_budget_lines where fiscal_budget_id = budget_id;
  end if;
  for line in select value from jsonb_array_elements(p_lines) loop
    insert into public.department_budget_lines (
      fiscal_budget_id, expense_class, category, particular, approved_amount, fund_source, position, created_by
    ) values (
      budget_id, btrim(line ->> 'expenseClass'), btrim(line ->> 'category'), btrim(line ->> 'particular'),
      (line ->> 'amount')::numeric, btrim(line ->> 'fundSource'),
      coalesce((line ->> 'position')::int, 0), caller
    );
  end loop;
  insert into public.audit_events(actor_id, actor_name, entity_type, entity_id, action, after_data, org_id)
  select caller, coalesce(full_name, 'Department Head'), 'department_budget', budget_id::text,
    'department_budget.saved', jsonb_build_object('fiscalYear', p_fiscal_year, 'amount', total), p_org_id
  from public.profiles where id = caller;
  return budget_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.auto_accept_collaboration_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  should_audit boolean := false;
begin
  if new.current_revision_id is not null
     and new.status in ('in_review', 'changes_requested', 'ready_to_commit') then
    select not exists (
      select 1 from public.proposal_collaboration_approvals approval
      where approval.revision_id = new.current_revision_id
        and approval.organization_id = new.owner_org_id
        and approval.decision = 'approved'
    ) into should_audit;

    insert into public.proposal_collaboration_approvals (
      draft_id, revision_id, organization_id, decision, approved_by, reason
    ) values (
      new.id, new.current_revision_id, new.owner_org_id, 'approved', new.owner_user_id,
      'Owner organization accepted automatically when collaboration review was requested.'
    )
    on conflict (revision_id, organization_id) do update
      set decision = 'approved', approved_by = excluded.approved_by,
          reason = excluded.reason, created_at = now();

    if should_audit then
      insert into public.audit_events (actor_id, actor_name, entity_type, entity_id, action, reason, after_data, org_id)
      values (
        new.owner_user_id, coalesce((select full_name from public.profiles where id = new.owner_user_id), 'Owner'),
        'collaboration_approval', new.current_revision_id::text, 'collaboration.owner_auto_accepted',
        'Owner organization accepted automatically when collaboration review was requested.',
        jsonb_build_object('draftId', new.id, 'revisionId', new.current_revision_id, 'organizationId', new.owner_org_id),
        new.owner_org_id
      );
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_collaboration_source_document(p_draft_id uuid, p_source_file_name text, p_source_file_path text, p_source_file_hash text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  draft_row public.proposal_collaboration_drafts;
  caller_name text := '';
begin
  if not public.can_manage_collaboration_draft(p_draft_id, caller) then
    raise exception 'Only the owning organization may attach the source document' using errcode = '42501';
  end if;
  select * into draft_row from public.proposal_collaboration_drafts where id = p_draft_id for update;
  update public.proposal_collaboration_drafts
  set source_file_name = nullif(btrim(p_source_file_name), ''),
      source_file_path = nullif(btrim(p_source_file_path), ''),
      source_file_hash = nullif(btrim(p_source_file_hash), '')
  where id = p_draft_id;
  select coalesce(full_name, 'Owner') into caller_name from public.profiles where id = caller;
  insert into public.audit_events (actor_id, actor_name, entity_type, entity_id, action, after_data, org_id)
  values (
    caller, caller_name, 'collaboration_draft', p_draft_id::text, 'collaboration.source_document_attached',
    jsonb_build_object('fileName', nullif(btrim(p_source_file_name), ''), 'sha256', nullif(btrim(p_source_file_hash), '')),
    draft_row.owner_org_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_active_subtask_team_member_removal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  removed_ids uuid[];
  blocked_member_name text;
  blocked_subtask_title text;
begin
  if new.team_member_ids is not distinct from old.team_member_ids then
    return new;
  end if;

  select coalesce(array_agg(member_id), '{}'::uuid[])
  into removed_ids
  from unnest(coalesce(old.team_member_ids, '{}'::uuid[])) member_id
  where not (member_id = any(coalesce(new.team_member_ids, '{}'::uuid[])));

  if cardinality(removed_ids) = 0 then
    return new;
  end if;

  select coalesce(profile.full_name, 'A task member'), subtask.title
  into blocked_member_name, blocked_subtask_title
  from public.subtasks subtask
  cross join lateral unnest(coalesce(subtask.assigned_to_ids, '{}'::uuid[])) assignee_id
  left join public.profiles profile on profile.id = assignee_id
  where subtask.task_id = old.id
    and coalesce(subtask.status, 'todo') <> 'completed'
    and not coalesce(subtask.is_completed, false)
    and assignee_id = any(removed_ids)
  order by subtask.position, subtask.created_at
  limit 1;

  if blocked_subtask_title is not null then
    raise exception '% cannot be removed while assigned to unfinished subtask "%"',
      blocked_member_name,
      blocked_subtask_title
      using errcode = '22023';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_organization_leadership_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  selected_name text;
begin
  if new.head_user_id is not null then
    select full_name into selected_name
    from public.profiles
    where id = new.head_user_id
      and is_active
      and org_id = new.id;

    if selected_name is null then
      raise exception 'Head must already be an active member of this organization before being assigned'
        using errcode = '22023';
    end if;
  end if;

  if new.assistant_head_user_id is not null then
    select full_name into selected_name
    from public.profiles
    where id = new.assistant_head_user_id
      and is_active
      and org_id = new.id;

    if selected_name is null then
      raise exception 'Assistant Head must already be an active member of this organization before being assigned'
        using errcode = '22023';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.route_organization_leadership_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  org_head uuid;
  org_assistant uuid;
  expected_reviewer uuid;
  expected_backup uuid;
  expected_label text;
  reviewer_active boolean;
  backup_active boolean;
begin
  -- Explicit people and governance organizations remain authoritative.
  if coalesce(new.review_route_mode, 'organization_default') in ('explicit', 'governance') then
    return new;
  end if;
  if new.org_id is null or new.assigned_to is null then return new; end if;

  select head_user_id, assistant_head_user_id
    into org_head, org_assistant
  from public.organizations
  where id = new.org_id;

  if new.assigned_to = org_head then
    expected_reviewer := org_assistant;
    expected_label := 'Assistant Head';
  elsif new.assigned_to = org_assistant then
    expected_reviewer := org_head;
    expected_label := 'Head';
  elsif new.source_collaboration_draft_id is not null then
    -- For an inter-department proposal, ordinary employee/Team Leader work is
    -- reviewed by the Head of the task's primary organization, never by the
    -- user who happened to publish the overall proposal.
    expected_reviewer := org_head;
    expected_backup := org_assistant;
    expected_label := 'Head';
  else
    return new;
  end if;

  if expected_reviewer is not null then
    select is_active into reviewer_active from public.profiles where id = expected_reviewer;
  end if;
  if expected_backup is not null then
    select is_active into backup_active from public.profiles where id = expected_backup;
  end if;

  if expected_reviewer is null or expected_reviewer = new.assigned_to
     or not coalesce(reviewer_active, false) then
    new.reviewer_id := null;
    new.backup_reviewer_id := null;
    if new.status = 'for_review' then
      raise exception 'Assign an active % for the task''s responsible organization before submitting', expected_label
        using errcode = '22023';
    end if;
    return new;
  end if;

  new.reviewer_id := expected_reviewer;
  new.backup_reviewer_id := case
    when coalesce(backup_active, false)
      and expected_backup <> new.assigned_to
      and expected_backup <> expected_reviewer
    then expected_backup
    else null
  end;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.normalize_collaboration_activity_responsibility(input_snapshot jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when input_snapshot is null or jsonb_typeof(input_snapshot -> 'tasks') <> 'array' then input_snapshot
    else jsonb_set(
      input_snapshot,
      '{tasks}',
      coalesce((
        select jsonb_agg(
          task.value || jsonb_build_object(
            'activityPrimaryOrgId', coalesce(nullif(task.value ->> 'activityPrimaryOrgId', ''), task.value ->> 'primaryOrgId'),
            'activitySupportingOrgIds', case
              when task.value ? 'activitySupportingOrgIds' then coalesce(task.value -> 'activitySupportingOrgIds', '[]'::jsonb)
              else coalesce(task.value -> 'supportingOrgIds', '[]'::jsonb)
            end,
            'primaryOrgId', coalesce(nullif(task.value ->> 'activityPrimaryOrgId', ''), task.value ->> 'primaryOrgId'),
            'supportingOrgIds', case
              when task.value ? 'activitySupportingOrgIds' then coalesce(task.value -> 'activitySupportingOrgIds', '[]'::jsonb)
              else coalesce(task.value -> 'supportingOrgIds', '[]'::jsonb)
            end
          ) order by task.ordinality
        )
        from jsonb_array_elements(input_snapshot -> 'tasks') with ordinality task(value, ordinality)
      ), '[]'::jsonb),
      true
    )
  end;
$function$

CREATE OR REPLACE FUNCTION public.inherit_collaboration_activity_responsibility()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_table_name = 'proposal_collaboration_drafts' then
    new.working_snapshot := public.normalize_collaboration_activity_responsibility(new.working_snapshot);
  else
    new.snapshot := public.normalize_collaboration_activity_responsibility(new.snapshot);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.commit_single_department_proposal_budget()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  snapshot jsonb;
  budget_json jsonb;
  task_budget jsonb;
  task_json jsonb;
  line jsonb;
  task_total numeric;
  proposal_total numeric := 0;
  declared_total numeric := 0;
  quantity_value numeric;
  unit_cost_value numeric;
  amount_value numeric;
  year int;
  fiscal public.department_fiscal_budgets;
  already_committed numeric := 0;
  commitment_id uuid;
  allocation_id uuid;
  operational_task public.tasks;
  actor uuid;
begin
  if new.status <> 'committed' or old.status = 'committed' then return new; end if;
  actor := coalesce(auth.uid(), new.created_by);

  select revision.snapshot into snapshot
  from public.proposal_collaboration_revisions revision
  where revision.id = new.current_revision_id and revision.draft_id = new.id;
  budget_json := snapshot -> 'budget';
  if budget_json is null or jsonb_typeof(budget_json) <> 'object' then
    raise exception 'Complete the task funding schedule before publishing this proposal' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(budget_json -> 'taskBudgets', '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(budget_json -> 'taskBudgets', '[]'::jsonb)) = 0 then
    raise exception 'Every selected task must be marked funded or no cost before publishing' using errcode = '22023';
  end if;

  for task_json in
    select value from jsonb_array_elements(snapshot -> 'tasks')
    where coalesce((value ->> 'enabled')::boolean, true)
  loop
    select value into task_budget
    from jsonb_array_elements(budget_json -> 'taskBudgets')
    where value ->> 'taskKey' = task_json ->> 'key';
    if task_budget is null then
      raise exception 'Task "%" has no funding decision', task_json ->> 'title' using errcode = '22023';
    end if;
    if task_budget ->> 'decision' not in ('funded', 'no_cost') then
      raise exception 'Task "%" must be marked funded or no cost', task_json ->> 'title' using errcode = '22023';
    end if;
    if task_budget ->> 'decision' = 'no_cost' then
      continue;
    end if;
    if jsonb_typeof(coalesce(task_budget -> 'lines', '[]'::jsonb)) <> 'array'
       or jsonb_array_length(coalesce(task_budget -> 'lines', '[]'::jsonb)) = 0 then
      raise exception 'Task "%" needs at least one funded particular', task_json ->> 'title' using errcode = '22023';
    end if;
    task_total := 0;
    for line in select value from jsonb_array_elements(task_budget -> 'lines') loop
      if nullif(btrim(line ->> 'expenseClass'), '') is null or nullif(btrim(line ->> 'category'), '') is null
         or nullif(btrim(line ->> 'particular'), '') is null then
        raise exception 'Every task budget line needs an expense class, category, and particular' using errcode = '22023';
      end if;
      quantity_value := greatest(coalesce((line ->> 'quantity')::numeric, 1), 0);
      unit_cost_value := greatest(coalesce((line ->> 'unitCost')::numeric, (line ->> 'amount')::numeric, 0), 0);
      amount_value := case when quantity_value > 0 and unit_cost_value > 0 then quantity_value * unit_cost_value else greatest(coalesce((line ->> 'amount')::numeric, 0), 0) end;
      if amount_value <= 0 then raise exception 'Every funded particular must have an amount greater than zero' using errcode = '22023'; end if;
      task_total := task_total + amount_value;
    end loop;
    proposal_total := proposal_total + task_total;
  end loop;

  declared_total := coalesce((budget_json ->> 'totalAmount')::numeric, 0);
  if abs(declared_total - proposal_total) > 0.009 then
    raise exception 'Proposal funding total does not match its task budgets' using errcode = '22023';
  end if;

  -- Administrative plans whose enabled tasks are all explicitly no-cost do not
  -- reserve an appropriation and do not require a locked fiscal budget.
  if proposal_total = 0 then
    return new;
  end if;
  year := coalesce((budget_json ->> 'fiscalYear')::int, extract(year from now())::int);
  select * into fiscal from public.department_fiscal_budgets
  where org_id = new.owner_org_id and fiscal_year = year and status = 'locked' for update;
  if not found then raise exception 'No locked % owner-department budget exists', year using errcode = '22023'; end if;
  select coalesce(sum(amount), 0) into already_committed
  from public.budget_commitments where fiscal_budget_id = fiscal.id and status = 'active';
  if already_committed + proposal_total > fiscal.approved_amount then
    raise exception 'Insufficient department budget. Shortfall: %',
      to_char((already_committed + proposal_total) - fiscal.approved_amount, 'FM999G999G999G990D00') using errcode = '22023';
  end if;

  insert into public.budget_commitments(
    fiscal_budget_id, proposal_draft_id, proposal_revision_id, title, amount, created_by
  ) values (fiscal.id, new.id, new.current_revision_id, new.title, proposal_total, actor)
  on conflict (proposal_draft_id) do update set
    proposal_revision_id = excluded.proposal_revision_id,
    title = excluded.title,
    amount = excluded.amount,
    updated_at = now()
  returning id into commitment_id;

  if proposal_total > 0 then
    insert into public.budget_ledger_entries(
      fiscal_budget_id, org_id, commitment_id, entry_type, amount, description, actor_id, metadata
    ) values (
      fiscal.id, fiscal.org_id, commitment_id, 'proposal_committed', proposal_total,
      'Budget reserved for published proposal: ' || new.title, actor,
      jsonb_build_object('proposalDraftId', new.id, 'revisionId', new.current_revision_id)
    );
  end if;

  for task_budget in
    select value from jsonb_array_elements(budget_json -> 'taskBudgets')
    where value ->> 'decision' = 'funded'
  loop
    select value into task_json from jsonb_array_elements(snapshot -> 'tasks')
    where value ->> 'key' = task_budget ->> 'taskKey'
      and coalesce((value ->> 'enabled')::boolean, true)
    limit 1;
    select * into operational_task
    from public.tasks task
    where task.source_collaboration_draft_id = new.id
      and task.source_collaboration_revision_id = new.current_revision_id
      -- Operational tasks are normalized with btrim() at publication time,
      -- while draft snapshots intentionally preserve what the author typed.
      -- Match normalized titles so a harmless trailing space cannot orphan a
      -- funded task budget during the same publication transaction.
      and btrim(task.title) = btrim(task_json ->> 'title')
      and coalesce(task.project_id, '') = coalesce(task_json ->> 'projectId', '')
      and coalesce(task.activity_id, '') = coalesce(task_json ->> 'activityId', '')
      and task.recommendation_lead_id = nullif(task_json ->> 'leadMemberId', '')::uuid
    order by task.created_at desc
    limit 1;
    if not found then
      raise exception 'Could not connect task budget for "%" to its operational task', coalesce(task_budget ->> 'taskTitle', task_json ->> 'title') using errcode = '22023';
    end if;
    select coalesce(sum(
      case
        when greatest(coalesce((value ->> 'quantity')::numeric, 1), 0) > 0
         and greatest(coalesce((value ->> 'unitCost')::numeric, (value ->> 'amount')::numeric, 0), 0) > 0
        then greatest(coalesce((value ->> 'quantity')::numeric, 1), 0) * greatest(coalesce((value ->> 'unitCost')::numeric, (value ->> 'amount')::numeric, 0), 0)
        else greatest(coalesce((value ->> 'amount')::numeric, 0), 0)
      end
    ), 0) into task_total from jsonb_array_elements(task_budget -> 'lines');
    insert into public.work_budget_allocations(
      commitment_id, task_id, amount, status, reason, requested_by, decided_by, decision_reason, requested_at, decided_at
    ) values (
      commitment_id, operational_task.id, task_total, 'approved',
      'Automatically allocated from the approved proposal task budget', actor, actor,
      'Approved with proposal publication', now(), now()
    ) returning id into allocation_id;
    for line in select value from jsonb_array_elements(task_budget -> 'lines') loop
      quantity_value := greatest(coalesce((line ->> 'quantity')::numeric, 1), 0);
      unit_cost_value := greatest(coalesce((line ->> 'unitCost')::numeric, (line ->> 'amount')::numeric, 0), 0);
      amount_value := case when quantity_value > 0 and unit_cost_value > 0 then quantity_value * unit_cost_value else greatest(coalesce((line ->> 'amount')::numeric, 0), 0) end;
      insert into public.work_budget_allocation_lines(
        allocation_id, draft_task_key, expense_class, category, particular, quantity, unit, unit_cost,
        amount, fund_source, position
      ) values (
        allocation_id, task_budget ->> 'taskKey', btrim(line ->> 'expenseClass'), btrim(line ->> 'category'),
        btrim(line ->> 'particular'), quantity_value, coalesce(nullif(btrim(line ->> 'unit'), ''), 'item'), unit_cost_value,
        amount_value, coalesce(nullif(btrim(line ->> 'fundSource'), ''), 'Department Budget'), coalesce((line ->> 'position')::int, 0)
      );
    end loop;
    insert into public.budget_ledger_entries(
      fiscal_budget_id, org_id, commitment_id, allocation_id, entry_type, amount, description, actor_id, metadata
    ) values (
      fiscal.id, operational_task.org_id, commitment_id, allocation_id, 'allocation_approved', task_total,
      'Task allocation created from published proposal funding', actor,
      jsonb_build_object('taskId', operational_task.id, 'draftTaskKey', task_budget ->> 'taskKey')
    );
  end loop;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.lock_department_fiscal_budget(p_budget_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare caller uuid := auth.uid(); budget public.department_fiscal_budgets;
begin
  select * into budget from public.department_fiscal_budgets where id = p_budget_id for update;
  if not found then raise exception 'Annual budget not found' using errcode = 'P0002'; end if;
  if not public.is_department_budget_head(budget.org_id, caller) then raise exception 'Only the Department Head can lock this budget' using errcode = '42501'; end if;
  if budget.status <> 'draft' then raise exception 'This annual budget is already locked' using errcode = '22023'; end if;
  if budget.approved_amount <= 0 then raise exception 'The annual budget total must be greater than zero' using errcode = '22023'; end if;
  update public.department_fiscal_budgets set status = 'locked', locked_by = caller, locked_at = now(), updated_at = now() where id = p_budget_id;
  insert into public.budget_ledger_entries(fiscal_budget_id, org_id, entry_type, amount, description, actor_id)
  values (budget.id, budget.org_id, 'budget_locked', budget.approved_amount, 'Annual department budget locked', caller);
  insert into public.audit_events(actor_id, actor_name, entity_type, entity_id, action, after_data, org_id)
  select caller, coalesce(full_name, 'Department Head'), 'department_budget', budget.id::text,
    'department_budget.locked', jsonb_build_object('fiscalYear', budget.fiscal_year, 'amount', budget.approved_amount), budget.org_id
  from public.profiles where id = caller;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_work_budget_allocation(p_task_id uuid, p_subtask_id uuid, p_amount numeric, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  task public.tasks;
  commitment public.budget_commitments;
  allocation_id uuid;
  parent_amount numeric := 0;
  allocated numeric := 0;
  initial_status text;
begin
  if p_amount <= 0 or nullif(btrim(p_reason), '') is null then raise exception 'Enter a positive amount and reason' using errcode = '22023'; end if;
  select * into task from public.tasks where id = p_task_id;
  if not found then raise exception 'Task not found' using errcode = 'P0002'; end if;
  select c.* into commitment from public.budget_commitments c
  join public.department_fiscal_budgets b on b.id = c.fiscal_budget_id
  where c.proposal_draft_id = task.source_collaboration_draft_id and c.status = 'active' and b.org_id = task.org_id
  for update of c;
  if not found then raise exception 'This task has no active department proposal budget' using errcode = '22023'; end if;
  if p_subtask_id is not null and not exists (select 1 from public.subtasks s where s.id = p_subtask_id and s.task_id = p_task_id) then
    raise exception 'Subtask does not belong to this task' using errcode = '22023';
  end if;
  if p_subtask_id is null then
    if not public.is_department_budget_approver(task.org_id, caller) then raise exception 'Only the Head or Assistant Head can allocate a task budget' using errcode = '42501'; end if;
    select coalesce(sum(amount), 0) into allocated from public.work_budget_allocations
      where commitment_id = commitment.id and subtask_id is null and status = 'approved';
    if allocated + p_amount > commitment.amount then raise exception 'The proposal does not have enough unallocated budget' using errcode = '22023'; end if;
    initial_status := 'approved';
  else
    if not public.is_department_budget_approver(task.org_id, caller)
       and caller is distinct from coalesce(task.recommendation_lead_id, task.assigned_to) then
      raise exception 'Only the Task Leader can propose a subtask budget' using errcode = '42501';
    end if;
    select amount into parent_amount from public.work_budget_allocations
      where commitment_id = commitment.id and task_id = p_task_id and subtask_id is null and status = 'approved';
    if parent_amount is null then raise exception 'Allocate the parent task budget first' using errcode = '22023'; end if;
    select coalesce(sum(amount), 0) into allocated from public.work_budget_allocations
      where commitment_id = commitment.id and task_id = p_task_id and subtask_id is not null and status = 'approved';
    if allocated + p_amount > parent_amount then raise exception 'The task does not have enough unallocated budget' using errcode = '22023'; end if;
    initial_status := case when public.is_department_budget_approver(task.org_id, caller) then 'approved' else 'pending' end;
  end if;
  insert into public.work_budget_allocations(
    commitment_id, task_id, subtask_id, amount, status, reason, requested_by,
    decided_by, decided_at
  ) values (
    commitment.id, p_task_id, p_subtask_id, p_amount, initial_status, btrim(p_reason), caller,
    case when initial_status = 'approved' then caller end,
    case when initial_status = 'approved' then now() end
  ) returning id into allocation_id;
  if initial_status = 'approved' then
    insert into public.budget_ledger_entries(fiscal_budget_id, org_id, commitment_id, allocation_id, entry_type, amount, description, actor_id)
    values (commitment.fiscal_budget_id, task.org_id, commitment.id, allocation_id, 'allocation_approved', p_amount,
      case when p_subtask_id is null then 'Task budget allocated' else 'Subtask budget allocated' end, caller);
  else
    insert into public.notifications(user_id, type, title, message, task_id, task_title, actor_id, actor_name)
    select approver_id, 'budget_approval', 'Subtask budget approval needed',
      coalesce(p.full_name, 'A Task Leader') || ' requested ' || to_char(p_amount, 'FM999G999G999G990D00') || ' for a subtask.',
      task.id, task.title, caller, coalesce(p.full_name, '')
    from public.organization_approver_ids(task.org_id) approver_id
    left join public.profiles p on p.id = caller
    where approver_id <> caller;
  end if;
  return allocation_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.decide_work_budget_allocation(p_allocation_id uuid, p_approve boolean, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare caller uuid := auth.uid(); allocation public.work_budget_allocations; task public.tasks; parent_amount numeric; allocated numeric;
begin
  select * into allocation from public.work_budget_allocations where id = p_allocation_id for update;
  if not found then raise exception 'Allocation request not found' using errcode = 'P0002'; end if;
  select * into task from public.tasks where id = allocation.task_id;
  if not public.is_department_budget_approver(task.org_id, caller) then raise exception 'Only the Head or Assistant Head can decide this allocation' using errcode = '42501'; end if;
  if allocation.status <> 'pending' then raise exception 'This allocation has already been decided' using errcode = '22023'; end if;
  if caller = allocation.requested_by then raise exception 'You cannot approve your own allocation request' using errcode = '42501'; end if;
  if p_approve then
    select amount into parent_amount from public.work_budget_allocations
      where commitment_id = allocation.commitment_id and task_id = allocation.task_id and subtask_id is null and status = 'approved'
      for update;
    select coalesce(sum(amount), 0) into allocated from public.work_budget_allocations
      where commitment_id = allocation.commitment_id and task_id = allocation.task_id
        and subtask_id is not null and status = 'approved';
    if parent_amount is null or allocated + allocation.amount > parent_amount then raise exception 'The task budget is no longer sufficient' using errcode = '22023'; end if;
  end if;
  update public.work_budget_allocations set status = case when p_approve then 'approved' else 'rejected' end,
    decided_by = caller, decision_reason = nullif(btrim(p_reason), ''), decided_at = now(), updated_at = now()
  where id = allocation.id;
  if p_approve then
    insert into public.budget_ledger_entries(fiscal_budget_id, org_id, commitment_id, allocation_id, entry_type, amount, description, actor_id)
    select c.fiscal_budget_id, task.org_id, c.id, allocation.id, 'allocation_approved', allocation.amount, 'Subtask budget allocation approved', caller
    from public.budget_commitments c where c.id = allocation.commitment_id;
  end if;
  insert into public.notifications(user_id, type, title, message, task_id, task_title, actor_id, actor_name, reason)
  select allocation.requested_by, 'budget_decision', case when p_approve then 'Subtask budget approved' else 'Subtask budget declined' end,
    'Your ' || to_char(allocation.amount, 'FM999G999G999G990D00') || ' subtask budget request was ' || case when p_approve then 'approved.' else 'declined.' end,
    task.id, task.title, caller, coalesce(full_name, ''), coalesce(p_reason, '') from public.profiles where id = caller;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_petty_cash_request(p_allocation_id uuid, p_amount numeric, p_purpose text, p_needed_by date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare allocation public.work_budget_allocations; source_line_id uuid; line_count int;
begin
  select * into allocation from public.work_budget_allocations where id = p_allocation_id and status = 'approved';
  if not found then raise exception 'Choose an approved task or subtask budget' using errcode = '22023'; end if;
  if allocation.subtask_id is not null then
    source_line_id := allocation.parent_allocation_line_id;
  else
    select count(*), (array_agg(id order by position, id))[1] into line_count, source_line_id
    from public.work_budget_allocation_lines where allocation_id = allocation.id;
    if line_count <> 1 then raise exception 'Select the proposal budget line and fund source from the task funding card' using errcode = '22023'; end if;
  end if;
  return public.create_contextual_cash_request(
    allocation.task_id, allocation.subtask_id, source_line_id, p_amount,
    p_purpose, p_needed_by, gen_random_uuid()
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.set_proposal_governance_configuration(p_draft_id uuid, p_organizations jsonb, p_assignments jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  draft_row public.proposal_collaboration_drafts;
  item jsonb;
  target_org uuid;
  target_user uuid;
  target_role text;
begin
  if not public.can_manage_collaboration_draft(p_draft_id, caller) then
    raise exception 'Only the owning organization may configure proposal governance' using errcode = '42501';
  end if;
  select * into draft_row from public.proposal_collaboration_drafts where id = p_draft_id for update;
  if draft_row.status in ('committed', 'archived', 'deleted') then
    raise exception 'Governance configuration is locked after publication' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_organizations, '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_assignments, '[]'::jsonb)) <> 'array' then
    raise exception 'Governance configuration must be arrays' using errcode = '22023';
  end if;

  for item in select value from jsonb_array_elements(p_organizations) loop
    target_org := nullif(item ->> 'orgId', '')::uuid;
    if target_org is null or not exists (
      select 1 from public.proposal_collaboration_orgs participant
      where participant.draft_id = p_draft_id and participant.org_id = target_org
    ) then raise exception 'Governance organization is not part of this proposal' using errcode = '22023'; end if;
    update public.proposal_collaboration_orgs set
      approval_policy = case when item ->> 'approvalPolicy' in ('one_of', 'all', 'quorum') then item ->> 'approvalPolicy' else 'one_of' end,
      quorum_count = greatest(1, coalesce(nullif(item ->> 'quorumCount', '')::int, 1)),
      approval_sequence = greatest(1, coalesce(nullif(item ->> 'sequence', '')::int, 1)),
      review_deadline_days = greatest(1, least(90, coalesce(nullif(item ->> 'reviewDeadlineDays', '')::int, 5)))
    where draft_id = p_draft_id and org_id = target_org;
  end loop;

  delete from public.proposal_governance_assignments where draft_id = p_draft_id;
  for item in select value from jsonb_array_elements(p_assignments) loop
    target_org := nullif(item ->> 'organizationId', '')::uuid;
    target_user := nullif(item ->> 'userId', '')::uuid;
    target_role := item ->> 'role';
    if target_role not in ('primary_approver', 'backup_approver', 'liaison', 'technical_reviewer', 'observer') then
      raise exception 'Invalid governance assignment role' using errcode = '22023';
    end if;
    if not exists (
      select 1 from public.proposal_collaboration_orgs participant
      where participant.draft_id = p_draft_id and participant.org_id = target_org
    ) or not exists (
      select 1 from public.profiles profile
      where profile.id = target_user and profile.is_active
        and (profile.org_id = target_org or public.is_organization_member(target_org, profile.id))
    ) then raise exception 'Governance assignee must be an active member of the selected organization' using errcode = '22023'; end if;
    insert into public.proposal_governance_assignments (
      draft_id, organization_id, user_id, assignment_role, assigned_by
    ) values (p_draft_id, target_org, target_user, target_role, caller);
  end loop;

  insert into public.audit_events (actor_id, actor_name, entity_type, entity_id, action, after_data, org_id)
  values (caller, coalesce((select full_name from public.profiles where id = caller), 'Owner'),
    'collaboration_draft', p_draft_id::text, 'governance.configuration_updated',
    jsonb_build_object('organizationCount', jsonb_array_length(p_organizations), 'assignmentCount', jsonb_array_length(p_assignments)),
    draft_row.owner_org_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_proposal_delivery(p_draft_id uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  draft_row public.proposal_collaboration_drafts;
  changed_projects int;
begin
  if not public.can_manage_proposal_delivery(p_draft_id, caller) then
    raise exception 'Only the owning organization may complete proposal delivery' using errcode = '42501';
  end if;
  select * into draft_row from public.proposal_collaboration_drafts where id = p_draft_id for update;
  if draft_row.status <> 'committed' then raise exception 'Proposal is not in active delivery' using errcode = '22023'; end if;
  if exists (
    select 1 from public.tasks task where task.source_collaboration_draft_id = p_draft_id
      and task.deleted_at is null and task.archived_at is null and task.status not in ('completed', 'cancelled')
  ) then raise exception 'Every task must be approved or cancelled before completing the proposal' using errcode = '22023'; end if;
  if exists (select 1 from public.proposal_collaboration_orgs where draft_id = p_draft_id and participation_role = 'governance')
     and not exists (select 1 from public.proposal_delivery_closeouts where draft_id = p_draft_id and status = 'approved') then
    raise exception 'Final governance closeout approval is required' using errcode = '22023';
  end if;
  update public.projects set status = 'completed', updated_at = now()
  where source_collaboration_draft_id = p_draft_id and status <> 'archived';
  get diagnostics changed_projects = row_count;
  insert into public.proposal_delivery_closeouts (draft_id, status, completed_by, completed_at)
  values (p_draft_id, 'completed', caller, now())
  on conflict (draft_id) do update set status = 'completed', completed_by = caller, completed_at = now();
  insert into public.audit_events (actor_id, actor_name, entity_type, entity_id, action, reason, after_data, org_id)
  values (caller, coalesce((select full_name from public.profiles where id = caller), 'Owner'),
    'collaboration_draft', p_draft_id::text, 'proposal.delivery_completed', nullif(btrim(p_note), ''),
    jsonb_build_object('projectCount', changed_projects), draft_row.owner_org_id);
  return jsonb_build_object('draftId', p_draft_id, 'projectCount', changed_projects, 'status', 'completed');
end;
$function$

CREATE OR REPLACE FUNCTION public.recuse_and_delegate_collaboration_review(p_draft_id uuid, p_organization_id uuid, p_reason text, p_delegate_to uuid DEFAULT NULL::uuid, p_valid_until timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  draft_row public.proposal_collaboration_drafts;
begin
  if nullif(btrim(p_reason), '') is null then raise exception 'A recusal reason is required' using errcode = '22023'; end if;
  if not public.is_proposal_governance_decider(p_draft_id, p_organization_id, caller) then
    raise exception 'Only the current decision maker may recuse' using errcode = '42501';
  end if;
  select * into draft_row from public.proposal_collaboration_drafts where id = p_draft_id for update;
  if draft_row.status not in ('in_review', 'changes_requested', 'ready_to_commit') then
    raise exception 'Proposal is not in review' using errcode = '22023';
  end if;
  if p_delegate_to = caller then raise exception 'You cannot delegate to yourself' using errcode = '22023'; end if;
  if p_delegate_to is not null and not exists (
    select 1 from public.profiles profile where profile.id = p_delegate_to and profile.is_active
      and (profile.org_id = p_organization_id or public.is_organization_member(p_organization_id, profile.id))
  ) then raise exception 'Delegate must be an active member of the organization' using errcode = '22023'; end if;

  insert into public.proposal_governance_signoffs (
    draft_id, revision_id, organization_id, user_id, decision, reason, delegated_to
  ) values (p_draft_id, draft_row.current_revision_id, p_organization_id, caller, 'recused', btrim(p_reason), p_delegate_to)
  on conflict (revision_id, organization_id, user_id) do update
    set decision = 'recused', reason = excluded.reason, delegated_to = excluded.delegated_to, created_at = now();
  if p_delegate_to is not null then
    insert into public.proposal_governance_assignments (
      draft_id, organization_id, user_id, assignment_role, assigned_by, delegated_by, valid_until
    ) values (p_draft_id, p_organization_id, p_delegate_to, 'delegate', caller, caller, p_valid_until)
    on conflict (draft_id, organization_id, user_id, assignment_role) do update
      set delegated_by = caller, valid_until = excluded.valid_until, assigned_by = caller, created_at = now();
    insert into public.notifications (user_id, type, title, message, actor_id, actor_name, proposal_id, org_id, entity_type)
    values (p_delegate_to, 'collaboration_request', 'Governance review delegated',
      coalesce((select full_name from public.profiles where id = caller), 'An approver') || ' delegated review of "' || draft_row.title || '" to you.',
      caller, coalesce((select full_name from public.profiles where id = caller), 'Approver'), p_draft_id::text, p_organization_id, 'collaboration_draft');
  end if;
  insert into public.audit_events (actor_id, actor_name, entity_type, entity_id, action, reason, after_data, org_id)
  values (caller, coalesce((select full_name from public.profiles where id = caller), 'Approver'),
    'collaboration_approval', draft_row.current_revision_id::text, 'governance.approver_recused', btrim(p_reason),
    jsonb_build_object('draftId', p_draft_id, 'organizationId', p_organization_id, 'delegatedTo', p_delegate_to), p_organization_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.assign_task_with_details(p_task_id uuid, p_assignee uuid, p_assignee_name text DEFAULT NULL::text, p_team_id text DEFAULT NULL::text, p_team_name text DEFAULT NULL::text, p_team_member_ids jsonb DEFAULT NULL::jsonb, p_team_member_names jsonb DEFAULT NULL::jsonb, p_reviewer uuid DEFAULT NULL::uuid, p_backup_reviewer uuid DEFAULT NULL::uuid, p_set_reviewers boolean DEFAULT false)
 RETURNS tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_name text;
  before_task public.tasks;
  assigned_task public.tasks;
  resolved_reviewer uuid;
  resolved_backup uuid;
begin
  if caller is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if p_team_member_ids is not null
     and jsonb_typeof(p_team_member_ids) <> 'array' then
    raise exception 'Team member ids must be an array' using errcode = '22023';
  end if;
  if p_team_member_names is not null
     and jsonb_typeof(p_team_member_names) <> 'array' then
    raise exception 'Team member names must be an array' using errcode = '22023';
  end if;

  select full_name into caller_name from public.profiles where id = caller;
  select * into before_task
  from public.tasks
  where id = p_task_id and deleted_at is null
  for update;
  if not found then raise exception 'Task not found'; end if;
  if not public.can_manage_task(p_task_id, caller) then
    raise exception 'Not allowed to assign this task' using errcode = '42501';
  end if;

  resolved_reviewer := case
    when p_set_reviewers then p_reviewer
    else before_task.reviewer_id
  end;
  if resolved_reviewer = p_assignee then
    resolved_reviewer := case
      when before_task.created_by is distinct from p_assignee then before_task.created_by
      else null
    end;
  end if;
  if resolved_reviewer is null then
    select o.head_user_id into resolved_reviewer
    from public.organizations o
    where o.id = before_task.org_id
      and o.head_user_id is distinct from p_assignee;
  end if;

  resolved_backup := case
    when p_set_reviewers then p_backup_reviewer
    else before_task.backup_reviewer_id
  end;
  if resolved_backup = p_assignee or resolved_backup = resolved_reviewer then
    resolved_backup := null;
  end if;

  update public.tasks
  set
    team_id = coalesce(p_team_id, team_id),
    team_name = coalesce(p_team_name, team_name),
    team_member_ids = case
      when p_team_member_ids is null then team_member_ids
      else array(
        select nullif(trim(member.value), '')::uuid
        from jsonb_array_elements_text(p_team_member_ids) as member(value)
        where nullif(trim(member.value), '') is not null
      )
    end,
    team_member_names = case
      when p_team_member_names is null then team_member_names
      else array(
        select member.value
        from jsonb_array_elements_text(p_team_member_names) as member(value)
      )
    end,
    reviewer_id = resolved_reviewer,
    backup_reviewer_id = resolved_backup
  where id = p_task_id;

  if before_task.assigned_to is distinct from p_assignee
     or (before_task.status = 'pending_assignment' and p_assignee is not null) then
    select * into assigned_task from public.assign_task(
      p_task_id,
      p_assignee,
      p_assignee_name
    );
  else
    select * into assigned_task from public.tasks where id = p_task_id;
  end if;

  if before_task.assigned_to is not null
     and before_task.assigned_to is distinct from p_assignee
     and before_task.assigned_to <> caller then
    insert into public.notifications (
      user_id, type, title, message, task_id, task_title,
      actor_id, actor_name, status_from, status_to, reason
    ) values (
      before_task.assigned_to,
      'reassignment',
      'Task reassigned',
      '"' || before_task.title || '" was reassigned to another owner.',
      p_task_id,
      before_task.title,
      caller,
      coalesce(caller_name, 'Manager'),
      before_task.status,
      assigned_task.status,
      ''
    );
  end if;

  return assigned_task;
end;
$function$

CREATE OR REPLACE FUNCTION public.decide_proposal_closeout(p_draft_id uuid, p_organization_id uuid, p_decision text, p_reason text DEFAULT NULL::text, p_resolution_number text DEFAULT NULL::text, p_meeting_date date DEFAULT NULL::date)
 RETURNS proposal_delivery_closeout_decisions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  draft_row public.proposal_collaboration_drafts;
  result public.proposal_delivery_closeout_decisions;
begin
  if p_decision not in ('approved', 'changes_requested', 'declined') then raise exception 'Invalid closeout decision' using errcode = '22023'; end if;
  if p_decision <> 'approved' and nullif(btrim(p_reason), '') is null then raise exception 'A reason is required' using errcode = '22023'; end if;
  if not exists (select 1 from public.proposal_collaboration_orgs where draft_id = p_draft_id and org_id = p_organization_id and participation_role = 'governance') then
    raise exception 'This organization is not a governance reviewer for the proposal' using errcode = '42501';
  end if;
  if not public.is_proposal_governance_decider(p_draft_id, p_organization_id, caller) then
    raise exception 'Only an assigned governance decision maker may decide closeout' using errcode = '42501';
  end if;
  select * into draft_row from public.proposal_collaboration_drafts where id = p_draft_id;
  if not exists (select 1 from public.proposal_delivery_closeouts where draft_id = p_draft_id and status in ('pending', 'changes_requested')) then
    raise exception 'Closeout is not awaiting a decision' using errcode = '22023';
  end if;
  insert into public.proposal_delivery_closeout_decisions (
    draft_id, organization_id, decision, decided_by, reason, resolution_number, meeting_date
  ) values (
    p_draft_id, p_organization_id, p_decision, caller, nullif(btrim(p_reason), ''),
    nullif(btrim(p_resolution_number), ''), p_meeting_date
  ) on conflict (draft_id, organization_id) do update set
    decision = excluded.decision, decided_by = caller, reason = excluded.reason,
    resolution_number = excluded.resolution_number, meeting_date = excluded.meeting_date, created_at = now()
  returning * into result;
  if p_decision <> 'approved' then
    update public.proposal_delivery_closeouts set status = 'changes_requested', approved_at = null where draft_id = p_draft_id;
  elsif not exists (
    select 1 from public.proposal_collaboration_orgs participant
    where participant.draft_id = p_draft_id and participant.participation_role = 'governance'
      and not exists (
        select 1 from public.proposal_delivery_closeout_decisions decision
        where decision.draft_id = p_draft_id and decision.organization_id = participant.org_id and decision.decision = 'approved'
      )
  ) then
    update public.proposal_delivery_closeouts set status = 'approved', approved_at = now() where draft_id = p_draft_id;
  end if;
  insert into public.notifications (user_id, type, title, message, actor_id, actor_name, proposal_id, org_id, entity_type)
  values (draft_row.owner_user_id, case when p_decision = 'approved' then 'collaboration_approved' else 'collaboration_change' end,
    case when p_decision = 'approved' then 'Governance approved proposal closeout' else 'Governance returned proposal closeout' end,
    coalesce((select full_name from public.profiles where id = caller), 'Governance reviewer') || ' marked closeout of "' || draft_row.title || '" as ' || replace(p_decision, '_', ' ') || '.',
    caller, coalesce((select full_name from public.profiles where id = caller), 'Reviewer'), p_draft_id::text, draft_row.owner_org_id, 'proposal_closeout');
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_proposal_delivery(p_draft_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  draft_row public.proposal_collaboration_drafts;
  changed_projects int;
  changed_tasks int;
begin
  if nullif(btrim(p_reason), '') is null then raise exception 'An archive reason is required' using errcode = '22023'; end if;
  if not public.can_manage_proposal_delivery(p_draft_id, caller) then
    raise exception 'Only the owning organization may archive proposal delivery' using errcode = '42501';
  end if;
  select * into draft_row from public.proposal_collaboration_drafts where id = p_draft_id for update;
  if draft_row.status = 'archived' then
    return jsonb_build_object('draftId', p_draft_id, 'projectCount', 0, 'taskCount', 0, 'status', 'archived');
  end if;
  if not exists (select 1 from public.proposal_delivery_closeouts where draft_id = p_draft_id and status = 'completed')
     and exists (select 1 from public.projects where source_collaboration_draft_id = p_draft_id and status <> 'completed') then
    raise exception 'Complete proposal delivery before archiving it' using errcode = '22023';
  end if;
  update public.tasks set archived_at = now(), last_activity_at = now()
  where source_collaboration_draft_id = p_draft_id and deleted_at is null and archived_at is null;
  get diagnostics changed_tasks = row_count;
  update public.projects set status = 'archived', archived_at = now(), updated_at = now()
  where source_collaboration_draft_id = p_draft_id and status <> 'archived';
  get diagnostics changed_projects = row_count;
  update public.proposal_collaboration_drafts set status = 'archived', archived_at = now()
  where id = p_draft_id;
  insert into public.proposal_delivery_closeouts (draft_id, status, archived_by, archived_at)
  values (p_draft_id, 'archived', caller, now())
  on conflict (draft_id) do update set status = 'archived', archived_by = caller, archived_at = now();
  insert into public.audit_events (actor_id, actor_name, entity_type, entity_id, action, reason, after_data, org_id)
  values (caller, coalesce((select full_name from public.profiles where id = caller), 'Owner'),
    'collaboration_draft', p_draft_id::text, 'proposal.delivery_archived', btrim(p_reason),
    jsonb_build_object('projectCount', changed_projects, 'taskCount', changed_tasks), draft_row.owner_org_id);
  return jsonb_build_object('draftId', p_draft_id, 'projectCount', changed_projects, 'taskCount', changed_tasks, 'status', 'archived');
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_financial_work_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status = 'completed' and old.status is distinct from 'completed' and exists (
    select 1 from public.petty_cash_requests request
    where request.task_id = new.task_id
      and request.subtask_id = new.id
      and request.status not in ('settled', 'rejected', 'cancelled')
  ) then raise exception 'Settle all released or reserved cash before approving this funded subtask' using errcode = '22023'; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_proposal_closeout(p_draft_id uuid, p_note text DEFAULT NULL::text)
 RETURNS proposal_delivery_closeouts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  draft_row public.proposal_collaboration_drafts;
  result public.proposal_delivery_closeouts;
  governance_count int;
begin
  if not public.can_manage_proposal_delivery(p_draft_id, caller) then
    raise exception 'Only the owning organization may request proposal closeout' using errcode = '42501';
  end if;
  select * into draft_row from public.proposal_collaboration_drafts where id = p_draft_id for update;
  if draft_row.status <> 'committed' then raise exception 'Only a published proposal can enter closeout' using errcode = '22023'; end if;
  if exists (
    select 1 from public.tasks task
    where task.source_collaboration_draft_id = p_draft_id
      and task.deleted_at is null and task.archived_at is null
      and task.status not in ('completed', 'cancelled')
  ) then raise exception 'Every active task must be approved or cancelled before closeout' using errcode = '22023'; end if;
  select count(*) into governance_count from public.proposal_collaboration_orgs
  where draft_id = p_draft_id and participation_role = 'governance';
  delete from public.proposal_delivery_closeout_decisions where draft_id = p_draft_id;
  insert into public.proposal_delivery_closeouts (
    draft_id, status, request_note, requested_by, requested_at, approved_at
  ) values (
    p_draft_id, case when governance_count = 0 then 'approved' else 'pending' end,
    nullif(btrim(p_note), ''), caller, now(), case when governance_count = 0 then now() end
  ) on conflict (draft_id) do update set
    status = excluded.status, request_note = excluded.request_note,
    requested_by = caller, requested_at = now(), approved_at = excluded.approved_at,
    completed_by = null, completed_at = null, archived_by = null, archived_at = null
  returning * into result;
  insert into public.notifications (user_id, type, title, message, actor_id, actor_name, proposal_id, org_id, entity_type)
  select distinct reviewer.approver_id, 'collaboration_request', 'Proposal closeout requires review',
    'Final delivery for "' || draft_row.title || '" is ready for governance closeout.',
    caller, coalesce((select full_name from public.profiles where id = caller), 'Owner'), p_draft_id::text, participant.org_id, 'proposal_closeout'
  from public.proposal_collaboration_orgs participant
  cross join lateral (
    select assignment.user_id as approver_id
    from public.proposal_governance_assignments assignment
    where assignment.draft_id = p_draft_id and assignment.organization_id = participant.org_id
      and assignment.assignment_role in ('primary_approver', 'backup_approver', 'delegate')
      and (assignment.valid_until is null or assignment.valid_until > now())
      and not exists (
        select 1 from public.proposal_governance_signoffs signoff
        where signoff.revision_id = draft_row.current_revision_id
          and signoff.organization_id = participant.org_id
          and signoff.user_id = assignment.user_id
          and signoff.decision = 'recused'
      )
    union
    select fallback_id
    from public.organization_approver_ids(participant.org_id) fallback_id
    where not exists (
      select 1 from public.proposal_governance_assignments assignment
      where assignment.draft_id = p_draft_id and assignment.organization_id = participant.org_id
        and assignment.assignment_role in ('primary_approver', 'backup_approver', 'delegate')
        and (assignment.valid_until is null or assignment.valid_until > now())
    )
      and not exists (
        select 1 from public.proposal_governance_signoffs signoff
        where signoff.revision_id = draft_row.current_revision_id
          and signoff.organization_id = participant.org_id
          and signoff.user_id = fallback_id
          and signoff.decision = 'recused'
      )
  ) reviewer
  where participant.draft_id = p_draft_id and participant.participation_role = 'governance'
    and reviewer.approver_id <> caller;
  insert into public.audit_events (actor_id, actor_name, entity_type, entity_id, action, reason, after_data, org_id)
  values (caller, coalesce((select full_name from public.profiles where id = caller), 'Owner'),
    'proposal_closeout', p_draft_id::text, 'proposal.closeout_requested', nullif(btrim(p_note), ''),
    jsonb_build_object('governanceOrganizations', governance_count), draft_row.owner_org_id);
  return result;
end;
$function$

