CREATE OR REPLACE FUNCTION public.publish_department_proposal(p_draft_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  draft_row public.proposal_collaboration_drafts;
  current_revision public.proposal_collaboration_revisions;
  publication_revision public.proposal_collaboration_revisions;
begin
  if caller is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if not public.can_manage_collaboration_draft(p_draft_id, caller) then
    raise exception 'Only the owning organization may publish this proposal' using errcode = '42501';
  end if;

  select * into draft_row
  from public.proposal_collaboration_drafts
  where id = p_draft_id
  for update;

  if not found then
    raise exception 'Department proposal not found' using errcode = 'P0002';
  end if;
  if draft_row.status in ('committed', 'archived', 'deleted') then
    raise exception 'This department proposal can no longer be published' using errcode = '22023';
  end if;
  if exists (
    select 1
    from public.proposal_collaboration_orgs participant
    where participant.draft_id = p_draft_id
      and participant.participation_role <> 'owner'
  ) then
    raise exception 'Inter-organization proposals must complete collaboration review before publication' using errcode = '22023';
  end if;

  select * into current_revision
  from public.proposal_collaboration_revisions
  where id = draft_row.current_revision_id
    and draft_id = p_draft_id;

  if not found or current_revision.snapshot is distinct from draft_row.working_snapshot then
    select * into publication_revision
    from public.save_collaboration_revision(
      p_draft_id,
      draft_row.working_snapshot,
      'Department proposal finalized for publication'
    );
  else
    publication_revision := current_revision;
  end if;

  return public.commit_collaboration_draft(p_draft_id, publication_revision.id);
end;
$function$

CREATE OR REPLACE FUNCTION public.schedule_petty_cash_releases(p_request_id uuid, p_actor uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  request public.petty_cash_requests;
  budget public.department_fiscal_budgets;
  schedule_day date;
  remaining numeric;
  used_on_day numeric;
  tranche numeric;
  scheduled_total numeric := 0;
begin
  select * into request from public.petty_cash_requests where id = p_request_id for update;
  if not found then raise exception 'Petty-cash request not found' using errcode = 'P0002'; end if;
  select * into budget from public.department_fiscal_budgets where id = request.fiscal_budget_id and status = 'locked' for update;
  if not found then raise exception 'The annual department budget is no longer open' using errcode = '22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('eflow:cash-release:' || request.org_id::text, 0));
  delete from public.petty_cash_releases where request_id = request.id and status = 'scheduled';
  schedule_day := greatest(current_date, coalesce(request.needed_by, current_date));
  remaining := coalesce(request.approved_amount, request.requested_amount);
  while remaining > 0 loop
    select coalesce(sum(amount), 0) into used_on_day
    from public.petty_cash_releases
    where org_id = request.org_id and (
      (status = 'scheduled' and scheduled_date = schedule_day)
      or (status = 'released' and coalesce(released_at::date, scheduled_date) = schedule_day)
    );
    tranche := least(remaining, greatest(0, budget.daily_petty_cash_release_limit - used_on_day));
    if tranche > 0 then
      insert into public.petty_cash_releases(request_id, org_id, scheduled_date, amount, recipient_id, created_by)
      values (request.id, request.org_id, schedule_day, tranche, coalesce(request.cash_recipient_id, request.requester_id), p_actor);
      scheduled_total := scheduled_total + tranche;
      remaining := remaining - tranche;
    end if;
    if remaining > 0 then schedule_day := schedule_day + 1; end if;
  end loop;
  update public.petty_cash_requests set scheduled_amount = scheduled_total,
    status = 'scheduled_for_release', updated_at = now() where id = request.id;
  return scheduled_total;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_department_fiscal_budget_v2(p_org_id uuid, p_fiscal_year integer, p_daily_release_limit numeric, p_per_receipt_limit numeric, p_liquidation_due_days integer, p_allow_receipt_limit_override boolean, p_underutilization_threshold numeric, p_notes text, p_lines jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  budget_id uuid;
  line jsonb;
  total numeric := 0;
  quantity_value numeric;
  unit_cost_value numeric;
  amount_value numeric;
begin
  if not public.is_department_budget_head(p_org_id, caller) then
    raise exception 'Only the assigned Department Head can create the annual budget' using errcode = '42501';
  end if;
  if p_fiscal_year < 2000 or p_fiscal_year > 2200 then raise exception 'Invalid fiscal year' using errcode = '22023'; end if;
  if p_daily_release_limit <= 0 then raise exception 'Daily release limit must be greater than zero' using errcode = '22023'; end if;
  if p_per_receipt_limit <= 0 then raise exception 'Per-receipt threshold must be greater than zero' using errcode = '22023'; end if;
  if p_liquidation_due_days < 1 or p_liquidation_due_days > 90 then raise exception 'Liquidation due days must be between 1 and 90' using errcode = '22023'; end if;
  if p_underutilization_threshold < 0 or p_underutilization_threshold > 100 then raise exception 'Utilization threshold must be from 0 to 100' using errcode = '22023'; end if;
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_lines, '[]'::jsonb)) = 0 then
    raise exception 'Add at least one annual budget line' using errcode = '22023';
  end if;

  for line in select value from jsonb_array_elements(p_lines) loop
    if nullif(btrim(line ->> 'expenseClass'), '') is null or nullif(btrim(line ->> 'category'), '') is null
       or nullif(btrim(line ->> 'particular'), '') is null or nullif(btrim(line ->> 'fundSource'), '') is null then
      raise exception 'Every budget line needs an expense class, category, particular, and fund source' using errcode = '22023';
    end if;
    quantity_value := greatest(coalesce((line ->> 'quantity')::numeric, 1), 0);
    unit_cost_value := greatest(coalesce((line ->> 'unitCost')::numeric, (line ->> 'amount')::numeric, 0), 0);
    amount_value := case when quantity_value > 0 and unit_cost_value > 0 then quantity_value * unit_cost_value else greatest(coalesce((line ->> 'amount')::numeric, 0), 0) end;
    total := total + amount_value;
  end loop;

  select id into budget_id from public.department_fiscal_budgets
  where org_id = p_org_id and fiscal_year = p_fiscal_year for update;
  if budget_id is not null and exists (select 1 from public.department_fiscal_budgets where id = budget_id and status <> 'draft') then
    raise exception 'The annual budget is locked and cannot be edited' using errcode = '22023';
  end if;
  if budget_id is null then
    insert into public.department_fiscal_budgets (
      org_id, fiscal_year, approved_amount, petty_cash_limit, petty_cash_request_limit,
      daily_petty_cash_release_limit, per_receipt_limit, liquidation_due_days,
      allow_receipt_limit_override, underutilization_threshold, notes, created_by
    ) values (
      p_org_id, p_fiscal_year, total, p_daily_release_limit, p_per_receipt_limit,
      p_daily_release_limit, p_per_receipt_limit, p_liquidation_due_days,
      p_allow_receipt_limit_override, p_underutilization_threshold, nullif(btrim(p_notes), ''), caller
    ) returning id into budget_id;
  else
    update public.department_fiscal_budgets set
      approved_amount = total, petty_cash_limit = p_daily_release_limit, petty_cash_request_limit = p_per_receipt_limit,
      daily_petty_cash_release_limit = p_daily_release_limit, per_receipt_limit = p_per_receipt_limit,
      liquidation_due_days = p_liquidation_due_days, allow_receipt_limit_override = p_allow_receipt_limit_override,
      underutilization_threshold = p_underutilization_threshold, notes = nullif(btrim(p_notes), ''), updated_at = now()
    where id = budget_id;
    delete from public.department_budget_lines where fiscal_budget_id = budget_id;
  end if;

  for line in select value from jsonb_array_elements(p_lines) loop
    quantity_value := greatest(coalesce((line ->> 'quantity')::numeric, 1), 0);
    unit_cost_value := greatest(coalesce((line ->> 'unitCost')::numeric, (line ->> 'amount')::numeric, 0), 0);
    amount_value := case when quantity_value > 0 and unit_cost_value > 0 then quantity_value * unit_cost_value else greatest(coalesce((line ->> 'amount')::numeric, 0), 0) end;
    insert into public.department_budget_lines (
      fiscal_budget_id, expense_class, category, particular, quantity, unit, unit_cost,
      approved_amount, fund_source, position, created_by
    ) values (
      budget_id, btrim(line ->> 'expenseClass'), btrim(line ->> 'category'), btrim(line ->> 'particular'),
      quantity_value, coalesce(nullif(btrim(line ->> 'unit'), ''), 'item'), unit_cost_value,
      amount_value, btrim(line ->> 'fundSource'), coalesce((line ->> 'position')::int, 0), caller
    );
  end loop;
  insert into public.audit_events(actor_id, actor_name, entity_type, entity_id, action, after_data, org_id)
  select caller, coalesce(full_name, 'Department Head'), 'department_budget', budget_id::text,
    'department_budget.saved', jsonb_build_object('fiscalYear', p_fiscal_year, 'amount', total, 'dailyReleaseLimit', p_daily_release_limit, 'perReceiptLimit', p_per_receipt_limit), p_org_id
  from public.profiles where id = caller;
  return budget_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_collaboration_revision(p_draft_id uuid, p_snapshot jsonb, p_change_summary text DEFAULT 'Draft updated'::text)
 RETURNS proposal_collaboration_revisions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  draft_row public.proposal_collaboration_drafts;
  current_row public.proposal_collaboration_revisions;
  revision_row public.proposal_collaboration_revisions;
  normalized_snapshot jsonb := public.normalize_collaboration_snapshot_roles(p_snapshot);
  material_change boolean := true;
  next_number int;
  caller_name text := '';
  carried_count int := 0;
begin
  if not public.can_manage_collaboration_draft(p_draft_id, caller) then
    raise exception 'Only the owning organization may revise this draft' using errcode = '42501';
  end if;
  if jsonb_typeof(coalesce(normalized_snapshot, '{}'::jsonb)) <> 'object' then
    raise exception 'Draft snapshot must be an object' using errcode = '22023';
  end if;
  select * into draft_row from public.proposal_collaboration_drafts where id = p_draft_id for update;
  if draft_row.status in ('committed','archived','deleted') or draft_row.deleted_at is not null then
    raise exception 'This work plan is no longer editable' using errcode = '22023';
  end if;
  select * into current_row from public.proposal_collaboration_revisions where id = draft_row.current_revision_id;
  if found and current_row.snapshot = normalized_snapshot then return current_row; end if;
  if found then material_change := public.collaboration_revision_is_material(current_row.snapshot, normalized_snapshot); end if;

  select coalesce(max(revision_number), 0) + 1 into next_number
  from public.proposal_collaboration_revisions where draft_id = p_draft_id;
  insert into public.proposal_collaboration_revisions (
    draft_id, revision_number, snapshot, created_by, change_summary
  ) values (
    p_draft_id, next_number, normalized_snapshot, caller,
    coalesce(nullif(btrim(p_change_summary), ''), 'Draft updated')
  ) returning * into revision_row;

  if current_row.id is not null and not material_change then
    insert into public.proposal_collaboration_approvals (
      draft_id, revision_id, organization_id, decision, approved_by, reason, created_at
    )
    select approval.draft_id, revision_row.id, approval.organization_id, approval.decision,
      approval.approved_by, approval.reason, approval.created_at
    from public.proposal_collaboration_approvals approval
    join public.proposal_collaboration_orgs participant
      on participant.draft_id = approval.draft_id and participant.org_id = approval.organization_id
    where approval.revision_id = current_row.id
      and approval.decision = 'approved'
      and participant.participation_role in ('participant', 'governance')
    on conflict (revision_id, organization_id) do nothing;
    get diagnostics carried_count = row_count;
  end if;

  update public.proposal_collaboration_drafts
  set working_snapshot = normalized_snapshot,
      current_revision_id = revision_row.id,
      status = case
        when material_change and status in ('in_review', 'ready_to_commit') then 'changes_requested'
        else status
      end
  where id = p_draft_id;

  select coalesce(full_name, 'User') into caller_name from public.profiles where id = caller;
  insert into public.audit_events (
    actor_id, actor_name, entity_type, entity_id, action, reason, after_data, org_id
  ) values (
    caller, caller_name, 'collaboration_revision', revision_row.id::text,
    'collaboration.revision_created', revision_row.change_summary,
    jsonb_build_object(
      'draftId', p_draft_id,
      'revision', next_number,
      'materialChange', material_change,
      'approvalsCarriedForward', carried_count
    ), draft_row.owner_org_id
  );
  perform public.refresh_collaboration_readiness(p_draft_id);
  return revision_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.decide_petty_cash_leader_review(p_request_id uuid, p_approve boolean, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare caller uuid := auth.uid(); request public.petty_cash_requests; task public.tasks;
begin
  select * into request from public.petty_cash_requests where id = p_request_id for update;
  if not found then raise exception 'Petty-cash request not found' using errcode = 'P0002'; end if;
  if request.status <> 'pending_leader_review' then raise exception 'This request is not awaiting Team Leader review' using errcode = '22023'; end if;
  if request.task_leader_id <> caller then raise exception 'Only the assigned Team Leader can endorse this request' using errcode = '42501'; end if;
  if request.requester_id = caller then raise exception 'You cannot review your own request' using errcode = '42501'; end if;
  if not p_approve and nullif(btrim(p_reason), '') is null then raise exception 'Explain what the employee must change' using errcode = '22023'; end if;
  update public.petty_cash_requests set
    status = case when p_approve then 'pending_department_approval' else 'leader_changes_requested' end,
    leader_decided_by = caller, leader_decision_reason = nullif(btrim(p_reason), ''), leader_decided_at = now(), updated_at = now()
  where id = request.id;
  select * into task from public.tasks where id = request.task_id;
  if p_approve then
    insert into public.notifications(user_id, type, title, message, task_id, task_title, actor_id, actor_name, financial_record_id, financial_record_type)
    select approver_id, 'petty_cash_department_approval', 'Endorsed petty cash needs approval',
      'The Team Leader endorsed ' || to_char(request.requested_amount, 'FM999G999G999G990D00') || ' for "' || task.title || '".',
      task.id, task.title, caller, coalesce(profile.full_name, ''), request.id, 'petty_cash_request'
    from public.organization_approver_ids(request.org_id) approver_id
    left join public.profiles profile on profile.id = caller
    where approver_id <> caller;
  else
    insert into public.notifications(user_id, type, title, message, task_id, task_title, actor_id, actor_name, reason, financial_record_id, financial_record_type)
    select request.requester_id, 'petty_cash_changes', 'Petty-cash request needs changes',
      'Your Team Leader returned the petty-cash request for correction.', task.id, task.title,
      caller, coalesce(full_name, ''), p_reason, request.id, 'petty_cash_request' from public.profiles where id = caller;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.decide_petty_cash_request(p_request_id uuid, p_approve boolean, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  request public.petty_cash_requests;
  budget public.department_fiscal_budgets;
  allocation public.work_budget_allocations;
  allocation_used numeric;
begin
  select * into request from public.petty_cash_requests where id = p_request_id for update;
  if not found then raise exception 'Petty-cash request not found' using errcode = 'P0002'; end if;
  if request.status <> 'pending_department_approval' then raise exception 'This request is not awaiting department approval' using errcode = '22023'; end if;
  if not public.is_department_budget_approver(request.org_id, caller) then raise exception 'Only the Head or Assistant Head can decide this request' using errcode = '42501'; end if;
  if caller = request.requester_id then raise exception 'You cannot approve your own request' using errcode = '42501'; end if;
  if caller = request.leader_decided_by then raise exception 'The Team Leader endorsement and department approval must be made by different people' using errcode = '42501'; end if;
  if not p_approve and nullif(btrim(p_reason), '') is null then raise exception 'A reason is required when declining' using errcode = '22023'; end if;
  if p_approve then
    select * into budget from public.department_fiscal_budgets where id = request.fiscal_budget_id and status = 'locked' for update;
    if not found then raise exception 'The annual department budget is no longer open' using errcode = '22023'; end if;
    select * into allocation from public.work_budget_allocations where id = request.allocation_id and status = 'approved' for update;
    if not found then raise exception 'The work allocation is no longer available' using errcode = '22023'; end if;
    select coalesce(sum(case when status = 'settled' then actual_spent else approved_amount end), 0) into allocation_used
    from public.petty_cash_requests where allocation_id = allocation.id and id <> request.id
      and status in ('approved','scheduled_for_release','partially_released','released','liquidation_submitted','pending_leader_liquidation_review','pending_department_settlement','changes_requested','overdue_liquidation','settled');
    if allocation_used + request.requested_amount > allocation.amount then raise exception 'The work allocation is no longer sufficient' using errcode = '22023'; end if;
  end if;
  update public.petty_cash_requests set
    status = case when p_approve then 'approved' else 'rejected' end,
    approved_amount = case when p_approve then requested_amount end,
    approved_by = caller, approval_reason = nullif(btrim(p_reason), ''),
    department_decision_reason = nullif(btrim(p_reason), ''), decided_at = now(), updated_at = now()
  where id = request.id;
  if p_approve then
    perform public.schedule_petty_cash_releases(request.id, caller);
    insert into public.budget_ledger_entries(fiscal_budget_id, org_id, commitment_id, allocation_id, petty_cash_request_id, entry_type, amount, description, actor_id)
    values (request.fiscal_budget_id, request.org_id, request.commitment_id, request.allocation_id, request.id,
      'petty_cash_reserved', request.requested_amount, 'Petty cash approved and scheduled under the daily release cap', caller);
  end if;
  insert into public.notifications(user_id, type, title, message, task_id, actor_id, actor_name, reason, financial_record_id, financial_record_type)
  select request.requester_id, 'petty_cash_decision', case when p_approve then 'Petty cash approved and scheduled' else 'Petty cash declined' end,
    case when p_approve then 'Your request was approved. Cash releases were scheduled under the department daily cap.' else 'Your petty-cash request was declined.' end,
    request.task_id, caller, coalesce(full_name, ''), coalesce(p_reason, ''), request.id, 'petty_cash_request' from public.profiles where id = caller;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_petty_cash_liquidation(p_request_id uuid, p_declared_spent numeric, p_note text, p_receipts jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  request public.petty_cash_requests;
  budget public.department_fiscal_budgets;
  item jsonb;
  receipt_total numeric := 0;
  liquidation_id uuid;
  next_version int;
  liquidation_status text;
begin
  select * into request from public.petty_cash_requests where id = p_request_id for update;
  if not found then raise exception 'Petty-cash request not found' using errcode = 'P0002'; end if;
  if request.requester_id <> caller and request.cash_recipient_id <> caller then raise exception 'Only the cash recipient can submit this liquidation' using errcode = '42501'; end if;
  if request.status not in ('released', 'changes_requested', 'overdue_liquidation') then raise exception 'All scheduled cash must be released before liquidation' using errcode = '22023'; end if;
  if p_declared_spent < 0 or p_declared_spent > request.released_amount then raise exception 'Actual spending cannot exceed the amount released' using errcode = '22023'; end if;
  if nullif(btrim(p_note), '') is null then raise exception 'Add a liquidation note' using errcode = '22023'; end if;
  if jsonb_typeof(coalesce(p_receipts, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_receipts, '[]'::jsonb)) = 0 then raise exception 'Attach at least one receipt' using errcode = '22023'; end if;
  select * into budget from public.department_fiscal_budgets where id = request.fiscal_budget_id;
  for item in select value from jsonb_array_elements(p_receipts) loop
    if nullif(btrim(item ->> 'vendor'), '') is null or nullif(btrim(item ->> 'description'), '') is null
       or nullif(btrim(item ->> 'filePath'), '') is null or nullif(item ->> 'receiptDate', '') is null then
      raise exception 'Every receipt needs vendor, date, description, amount, and attachment' using errcode = '22023';
    end if;
    if coalesce((item ->> 'amount')::numeric, 0) > budget.per_receipt_limit then
      if not budget.allow_receipt_limit_override then
        raise exception 'Receipt exceeds the configured per-receipt threshold of %', to_char(budget.per_receipt_limit, 'FM999G999G999G990D00') using errcode = '22023';
      end if;
      if nullif(btrim(item ->> 'overrideReason'), '') is null then
        raise exception 'Explain every receipt above the configured threshold' using errcode = '22023';
      end if;
    end if;
    receipt_total := receipt_total + coalesce((item ->> 'amount')::numeric, 0);
  end loop;
  if abs(receipt_total - p_declared_spent) > 0.009 then raise exception 'Receipt amounts must equal the declared amount spent' using errcode = '22023'; end if;
  select coalesce(max(version), 0) + 1 into next_version from public.petty_cash_liquidations where request_id = request.id;
  liquidation_status := case when request.task_leader_id = caller then 'pending_department_settlement' else 'pending_leader_review' end;
  insert into public.petty_cash_liquidations(request_id, version, declared_spent, returned_amount, note, status, submitted_by)
  values (request.id, next_version, p_declared_spent, request.released_amount - p_declared_spent, btrim(p_note), liquidation_status, caller)
  returning id into liquidation_id;
  for item in select value from jsonb_array_elements(p_receipts) loop
    insert into public.petty_cash_receipts(
      liquidation_id, vendor, receipt_number, receipt_date, description, amount,
      file_name, file_path, mime_type, file_size, override_reason, created_by
    ) values (
      liquidation_id, btrim(item ->> 'vendor'), nullif(btrim(item ->> 'receiptNumber'), ''),
      (item ->> 'receiptDate')::date, btrim(item ->> 'description'), (item ->> 'amount')::numeric,
      item ->> 'fileName', item ->> 'filePath', coalesce(nullif(item ->> 'mimeType', ''), 'application/octet-stream'),
      coalesce((item ->> 'fileSize')::bigint, 0), nullif(btrim(item ->> 'overrideReason'), ''), caller
    );
  end loop;
  update public.petty_cash_requests set status = case when liquidation_status = 'pending_leader_review' then 'pending_leader_liquidation_review' else 'pending_department_settlement' end, updated_at = now() where id = request.id;
  if liquidation_status = 'pending_leader_review' then
    insert into public.notifications(user_id, type, title, message, task_id, actor_id, actor_name, financial_record_id, financial_record_type)
    select request.task_leader_id, 'petty_cash_liquidation_leader_review', 'Expense liquidation needs your review',
      coalesce(profile.full_name, 'A team member') || ' submitted receipts totaling ' || to_char(p_declared_spent, 'FM999G999G999G990D00') || '.',
      request.task_id, caller, coalesce(profile.full_name, ''), liquidation_id, 'petty_cash_liquidation' from public.profiles profile where profile.id = caller;
  else
    insert into public.notifications(user_id, type, title, message, task_id, actor_id, actor_name, financial_record_id, financial_record_type)
    select approver_id, 'petty_cash_liquidation_department_review', 'Expense liquidation ready for settlement',
      coalesce(profile.full_name, 'A Task Leader') || ' submitted receipts totaling ' || to_char(p_declared_spent, 'FM999G999G999G990D00') || '.',
      request.task_id, caller, coalesce(profile.full_name, ''), liquidation_id, 'petty_cash_liquidation'
    from public.organization_approver_ids(request.org_id) approver_id left join public.profiles profile on profile.id = caller
    where approver_id <> caller;
  end if;
  return liquidation_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.audit_cash_release_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare request public.petty_cash_requests; actor uuid := auth.uid(); actor_role_value text;
begin
  select * into request from public.petty_cash_requests where id = new.request_id;
  select role::text into actor_role_value from public.profiles where id = actor;
  if new.status is distinct from old.status then
    insert into public.budget_ledger_entries(
      fiscal_budget_id, org_id, commitment_id, allocation_id, petty_cash_request_id,
      task_id, subtask_id, allocation_line_id, entry_type, amount, description,
      actor_id, actor_role, previous_state, new_state, metadata
    ) values (
      request.fiscal_budget_id, request.org_id, request.commitment_id, request.allocation_id, request.id,
      request.task_id, request.subtask_id, request.allocation_line_id, 'cash_release_state_changed',
      new.amount, 'Cash release state changed', actor, actor_role_value, old.status, new.status,
      jsonb_build_object('releaseId', new.id, 'scheduledDate', new.scheduled_date, 'recipientId', new.recipient_id)
    );
  end if;
  if new.acknowledged_at is not null and old.acknowledged_at is null then
    insert into public.budget_ledger_entries(
      fiscal_budget_id, org_id, commitment_id, allocation_id, petty_cash_request_id,
      task_id, subtask_id, allocation_line_id, entry_type, amount, description,
      actor_id, actor_role, previous_state, new_state, metadata
    ) values (
      request.fiscal_budget_id, request.org_id, request.commitment_id, request.allocation_id, request.id,
      request.task_id, request.subtask_id, request.allocation_line_id, 'cash_release_acknowledged',
      new.amount, 'Cash recipient acknowledged release', actor, actor_role_value,
      'released', 'acknowledged', jsonb_build_object('releaseId', new.id)
    );
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.decide_petty_cash_liquidation_leader_review(p_liquidation_id uuid, p_approve boolean, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare caller uuid := auth.uid(); liquidation public.petty_cash_liquidations; request public.petty_cash_requests;
begin
  select * into liquidation from public.petty_cash_liquidations where id = p_liquidation_id for update;
  if not found then raise exception 'Liquidation not found' using errcode = 'P0002'; end if;
  select * into request from public.petty_cash_requests where id = liquidation.request_id for update;
  if liquidation.status <> 'pending_leader_review' or request.status <> 'pending_leader_liquidation_review' then raise exception 'This liquidation is not awaiting Team Leader review' using errcode = '22023'; end if;
  if request.task_leader_id <> caller then raise exception 'Only the assigned Team Leader can review this liquidation' using errcode = '42501'; end if;
  if request.cash_recipient_id = caller then raise exception 'You cannot review your own liquidation' using errcode = '42501'; end if;
  if not p_approve and nullif(btrim(p_reason), '') is null then raise exception 'Explain what must be corrected' using errcode = '22023'; end if;
  update public.petty_cash_liquidations set status = case when p_approve then 'pending_department_settlement' else 'changes_requested' end,
    leader_decided_by = caller, leader_decision_reason = nullif(btrim(p_reason), ''), leader_decided_at = now()
  where id = liquidation.id;
  update public.petty_cash_requests set status = case when p_approve then 'pending_department_settlement' else 'changes_requested' end, updated_at = now() where id = request.id;
  if p_approve then
    insert into public.notifications(user_id, type, title, message, task_id, actor_id, actor_name, financial_record_id, financial_record_type)
    select approver_id, 'petty_cash_liquidation_department_review', 'Endorsed liquidation ready for settlement',
      'The Team Leader endorsed receipts totaling ' || to_char(liquidation.declared_spent, 'FM999G999G999G990D00') || '.',
      request.task_id, caller, coalesce(profile.full_name, ''), liquidation.id, 'petty_cash_liquidation'
    from public.organization_approver_ids(request.org_id) approver_id left join public.profiles profile on profile.id = caller
    where approver_id <> caller;
  else
    insert into public.notifications(user_id, type, title, message, task_id, actor_id, actor_name, reason, financial_record_id, financial_record_type)
    select request.cash_recipient_id, 'petty_cash_liquidation_changes', 'Expense liquidation needs changes',
      'Your Team Leader returned the liquidation for correction.', request.task_id, caller, coalesce(full_name, ''), p_reason, liquidation.id, 'petty_cash_liquidation'
    from public.profiles where id = caller;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.decide_petty_cash_liquidation(p_liquidation_id uuid, p_approve boolean, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare caller uuid := auth.uid(); liquidation public.petty_cash_liquidations; request public.petty_cash_requests;
begin
  select * into liquidation from public.petty_cash_liquidations where id = p_liquidation_id for update;
  if not found then raise exception 'Liquidation not found' using errcode = 'P0002'; end if;
  select * into request from public.petty_cash_requests where id = liquidation.request_id for update;
  if not public.is_department_budget_approver(request.org_id, caller) then raise exception 'Only the Head or Assistant Head can settle this liquidation' using errcode = '42501'; end if;
  if caller in (request.cash_recipient_id, request.requester_id) then raise exception 'You cannot settle your own liquidation' using errcode = '42501'; end if;
  if caller = liquidation.leader_decided_by then raise exception 'Leader review and department settlement must be performed by different people' using errcode = '42501'; end if;
  if liquidation.status <> 'pending_department_settlement' or request.status <> 'pending_department_settlement' then raise exception 'This liquidation is not awaiting department settlement' using errcode = '22023'; end if;
  if not p_approve and nullif(btrim(p_reason), '') is null then raise exception 'Explain what must be corrected' using errcode = '22023'; end if;
  update public.petty_cash_liquidations set status = case when p_approve then 'approved' else 'changes_requested' end,
    decided_by = caller, decision_reason = nullif(btrim(p_reason), ''), decided_at = now(),
    department_decided_by = caller, department_decision_reason = nullif(btrim(p_reason), ''), department_decided_at = now()
  where id = liquidation.id;
  if p_approve then
    update public.petty_cash_requests set status = 'settled', actual_spent = liquidation.declared_spent,
      returned_amount = liquidation.returned_amount, settled_by = caller, settled_at = now(), updated_at = now()
    where id = request.id;
    insert into public.budget_ledger_entries(fiscal_budget_id, org_id, commitment_id, allocation_id, petty_cash_request_id, entry_type, amount, description, actor_id)
    values (request.fiscal_budget_id, request.org_id, request.commitment_id, request.allocation_id, request.id,
      'expense_posted', liquidation.declared_spent, 'Verified receipts posted as actual task spending', caller);
    if liquidation.returned_amount > 0 then
      insert into public.budget_ledger_entries(fiscal_budget_id, org_id, commitment_id, allocation_id, petty_cash_request_id, entry_type, amount, description, actor_id)
      values (request.fiscal_budget_id, request.org_id, request.commitment_id, request.allocation_id, request.id,
        'cash_returned', liquidation.returned_amount, 'Unused released cash returned to the task allocation', caller);
    end if;
  else
    update public.petty_cash_requests set status = 'changes_requested', updated_at = now() where id = request.id;
  end if;
  insert into public.notifications(user_id, type, title, message, task_id, actor_id, actor_name, reason, financial_record_id, financial_record_type)
  select request.cash_recipient_id, 'petty_cash_liquidation_decision', case when p_approve then 'Expense liquidation settled' else 'Liquidation changes requested' end,
    case when p_approve then 'Your receipts were verified and actual spending was posted to the task budget.' else 'Your liquidation needs corrections before settlement.' end,
    request.task_id, caller, coalesce(full_name, ''), coalesce(p_reason, ''), liquidation.id, 'petty_cash_liquidation' from public.profiles where id = caller;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_petty_cash_request_organizations()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  resolved_funding_org uuid;
  resolved_requester_org uuid;
begin
  select fiscal.org_id into resolved_funding_org
  from public.department_fiscal_budgets fiscal
  where fiscal.id = new.fiscal_budget_id;

  select profile.org_id into resolved_requester_org
  from public.profiles profile
  where profile.id = new.requester_id;

  new.funding_org_id := coalesce(resolved_funding_org, new.funding_org_id, new.org_id);
  new.requester_org_id := coalesce(resolved_requester_org, new.requester_org_id, new.org_id);
  if new.funding_org_id is null or new.requester_org_id is null then
    raise exception 'Cash requests require funding and requester departments' using errcode = '23502';
  end if;
  -- org_id remains the compatibility key used by accounting policies and ledgers.
  new.org_id := new.funding_org_id;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_work_budget_allocation_caps()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  parent_allocation public.work_budget_allocations;
  parent_line public.work_budget_allocation_lines;
  allocated numeric := 0;
  parent_cash_committed numeric := 0;
begin
  if new.subtask_id is null or new.status not in ('pending', 'approved') then
    return new;
  end if;

  select * into parent_allocation
  from public.work_budget_allocations
  where commitment_id = new.commitment_id
    and task_id = new.task_id
    and subtask_id is null
    and status = 'approved'
  for update;
  if not found then
    raise exception 'The task has no approved proposal allocation' using errcode = '22023';
  end if;

  select coalesce(sum(amount), 0) into allocated
  from public.work_budget_allocations
  where commitment_id = new.commitment_id
    and task_id = new.task_id
    and subtask_id is not null
    and status in ('pending', 'approved')
    and id <> new.id;

  -- Cash requested directly against a parent task uses the same envelope and
  -- cannot later be delegated to a subtask.
  select coalesce(sum(
    case when status = 'settled' then coalesce(actual_spent, 0)
      else coalesce(approved_amount, requested_amount, 0)
    end
  ), 0) into parent_cash_committed
  from public.petty_cash_requests
  where allocation_id = parent_allocation.id
    and status not in ('draft', 'rejected', 'cancelled', 'leader_changes_requested', 'department_changes_requested');

  if allocated + parent_cash_committed + new.amount > parent_allocation.amount then
    raise exception 'The task budget has already been committed to subtask funding or task-level petty cash' using errcode = '22023';
  end if;

  if new.parent_allocation_line_id is not null then
    select * into parent_line
    from public.work_budget_allocation_lines
    where id = new.parent_allocation_line_id
      and allocation_id = parent_allocation.id;
    if not found then
      raise exception 'Choose a budget particular from this task allocation' using errcode = '22023';
    end if;

    select coalesce(sum(amount), 0) into allocated
    from public.work_budget_allocations
    where parent_allocation_line_id = parent_line.id
      and status in ('pending', 'approved')
      and id <> new.id;
    if allocated + new.amount > parent_line.amount then
      raise exception 'This budget particular does not have enough unallocated funding' using errcode = '22023';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_administrative_role_management()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_role text;
begin
  if caller is null then
    return new;
  end if;

  caller_role := public.auth_role(caller);
  if caller_role = 'admin' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.role in ('admin', 'admin') then
      raise exception 'Only the Admin can create an administrative account'
        using errcode = '42501';
    end if;
    return new;
  end if;

  if caller = old.id then
    return new;
  end if;

  if old.role in ('admin', 'admin')
     or new.role in ('admin', 'admin') then
    raise exception 'Only the Admin can manage administrative accounts'
      using errcode = '42501';
  end if;

  if old.role in ('dept_head', 'department_head', 'assistant_head')
     or new.role in ('dept_head', 'department_head', 'assistant_head') then
    if new.role is distinct from old.role
       or new.org_id is distinct from old.org_id
       or new.is_active is distinct from old.is_active then
      raise exception 'Only the Admin can change leadership assignment or account status'
        using errcode = '42501';
    end if;
  elsif old.role not in ('employee', 'accounting_staff')
        or new.role not in ('employee', 'accounting_staff') then
    raise exception 'Only the Admin can change this account role'
      using errcode = '42501';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_administrative_leadership_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.head_user_id is not null and exists (
    select 1 from public.profiles
    where id = new.head_user_id and role in ('admin', 'admin')
  ) then
    raise exception 'Administrative accounts cannot be assigned as organization Head'
      using errcode = '22023';
  end if;

  if new.assistant_head_user_id is not null and exists (
    select 1 from public.profiles
    where id = new.assistant_head_user_id and role in ('admin', 'admin')
  ) then
    raise exception 'Administrative accounts cannot be assigned as Assistant Head'
      using errcode = '22023';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_liquidation_release_acknowledgement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if exists (
    select 1 from public.petty_cash_releases release
    where release.request_id = new.request_id
      and release.status = 'released'
      and release.acknowledged_at is null
  ) then
    raise exception 'Acknowledge every released cash tranche before submitting receipts' using errcode = '22023';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.adjust_department_fiscal_budget(p_budget_id uuid, p_adjusted_amount numeric, p_reason text, p_support_file_path text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare caller uuid := auth.uid(); budget public.department_fiscal_budgets; committed numeric := 0; adjustment_id uuid;
begin
  select * into budget from public.department_fiscal_budgets where id = p_budget_id for update;
  if not found then raise exception 'Annual budget not found' using errcode = 'P0002'; end if;
  if not public.is_department_budget_head(budget.org_id, caller) then raise exception 'Only the assigned Department Head can adjust the annual budget' using errcode = '42501'; end if;
  if budget.status <> 'locked' then raise exception 'Only a locked annual budget can be adjusted' using errcode = '22023'; end if;
  if p_adjusted_amount < 0 or nullif(btrim(p_reason), '') is null then raise exception 'Enter a valid adjusted amount and reason' using errcode = '22023'; end if;
  select coalesce(sum(amount), 0) into committed from public.budget_commitments where fiscal_budget_id = budget.id and status = 'active';
  if p_adjusted_amount < committed then raise exception 'Adjusted funding cannot be lower than active proposal commitments' using errcode = '22023'; end if;
  insert into public.department_budget_adjustments(fiscal_budget_id, previous_amount, adjusted_amount, reason, support_file_path, created_by)
  values (budget.id, budget.approved_amount, p_adjusted_amount, btrim(p_reason), nullif(btrim(p_support_file_path), ''), caller)
  returning id into adjustment_id;
  update public.department_fiscal_budgets set approved_amount = p_adjusted_amount, updated_at = now() where id = budget.id;
  insert into public.budget_ledger_entries(fiscal_budget_id, org_id, entry_type, amount, description, actor_id, metadata)
  values (budget.id, budget.org_id, 'budget_adjusted', abs(p_adjusted_amount - budget.approved_amount),
    'Annual appropriation adjusted: ' || btrim(p_reason), caller,
    jsonb_build_object('before', budget.approved_amount, 'after', p_adjusted_amount, 'adjustmentId', adjustment_id));
  insert into public.audit_events(actor_id, actor_name, entity_type, entity_id, action, before_data, after_data, reason, org_id)
  select caller, coalesce(full_name, 'Department Head'), 'department_budget', budget.id::text, 'department_budget.adjusted',
    jsonb_build_object('approvedAmount', budget.approved_amount), jsonb_build_object('approvedAmount', p_adjusted_amount),
    btrim(p_reason), budget.org_id from public.profiles where id = caller;
  return adjustment_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.close_department_fiscal_budget(p_budget_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare caller uuid := auth.uid(); budget public.department_fiscal_budgets;
begin
  select * into budget from public.department_fiscal_budgets where id = p_budget_id for update;
  if not found then raise exception 'Annual budget not found' using errcode = 'P0002'; end if;
  if not public.is_department_budget_head(budget.org_id, caller) then raise exception 'Only the assigned Department Head can close the fiscal year' using errcode = '42501'; end if;
  if budget.status <> 'locked' then raise exception 'Only a locked annual budget can be closed' using errcode = '22023'; end if;
  if nullif(btrim(p_reason), '') is null then raise exception 'A fiscal close reason is required' using errcode = '22023'; end if;
  if exists (select 1 from public.petty_cash_requests where fiscal_budget_id = budget.id and status not in ('settled', 'rejected', 'cancelled')) then
    raise exception 'Settle or cancel every petty-cash request before closing this fiscal year' using errcode = '22023';
  end if;
  update public.department_fiscal_budgets set status = 'closed', closed_by = caller, closed_at = now(), updated_at = now() where id = budget.id;
  insert into public.budget_ledger_entries(fiscal_budget_id, org_id, entry_type, amount, description, actor_id)
  values (budget.id, budget.org_id, 'budget_closed', 0, 'Fiscal year closed: ' || btrim(p_reason), caller);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_collaboration_draft(p_title text, p_owner_org_id uuid, p_source_type text, p_source_file_name text, p_source_file_path text, p_source_file_hash text, p_snapshot jsonb)
 RETURNS proposal_collaboration_drafts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_name text := '';
  draft_row public.proposal_collaboration_drafts;
  revision_row public.proposal_collaboration_revisions;
  organization_item jsonb;
  additional_org_id uuid;
  additional_role text;
begin
  if caller is null then raise exception 'Not authenticated' using errcode = '42501'; end if;
  if nullif(btrim(p_title), '') is null then raise exception 'Draft title is required' using errcode = '22023'; end if;
  if p_source_type not in ('ai_pdf', 'manual') then raise exception 'Invalid draft source' using errcode = '22023'; end if;
  if jsonb_typeof(coalesce(p_snapshot, '{}'::jsonb)) <> 'object' then
    raise exception 'Draft snapshot must be an object' using errcode = '22023';
  end if;
  if not public.is_organization_approver(p_owner_org_id, caller) then
    raise exception 'Only the Head or Assistant Head may create a proposal for this organization'
      using errcode = '42501';
  end if;

  insert into public.proposal_collaboration_drafts (
    title, owner_org_id, owner_user_id, source_type,
    source_file_name, source_file_path, source_file_hash,
    working_snapshot, created_by
  ) values (
    btrim(p_title), p_owner_org_id, caller, p_source_type,
    nullif(btrim(p_source_file_name), ''), nullif(btrim(p_source_file_path), ''),
    nullif(btrim(p_source_file_hash), ''), p_snapshot, caller
  ) returning * into draft_row;

  insert into public.proposal_collaboration_revisions (
    draft_id, revision_number, snapshot, created_by, change_summary
  ) values (
    draft_row.id, 1, draft_row.working_snapshot, caller, 'Initial draft'
  ) returning * into revision_row;

  update public.proposal_collaboration_drafts
  set current_revision_id = revision_row.id
  where id = draft_row.id
  returning * into draft_row;

  insert into public.proposal_collaboration_orgs (
    draft_id, org_id, participation_role, staffing_enabled, requested_by
  ) values (draft_row.id, p_owner_org_id, 'owner', true, caller);

  select coalesce(full_name, 'User') into caller_name
  from public.profiles
  where id = caller;

  for organization_item in
    select value
    from jsonb_array_elements(coalesce(p_snapshot -> 'organizations', '[]'::jsonb))
  loop
    additional_org_id := nullif(organization_item ->> 'orgId', '')::uuid;
    additional_role := coalesce(nullif(organization_item ->> 'participationRole', ''), 'participant');
    if additional_org_id is null or additional_org_id = p_owner_org_id then continue; end if;
    if additional_role not in ('participant', 'governance', 'observer') then
      raise exception 'Additional organizations must be participants, governance, or observers'
        using errcode = '22023';
    end if;
    if not exists (
      select 1 from public.organizations
      where id = additional_org_id and is_active
    ) then
      raise exception 'A selected collaboration organization is not configured or active'
        using errcode = '22023';
    end if;

    insert into public.proposal_collaboration_orgs (
      draft_id, org_id, participation_role, staffing_enabled, requested_by,
      approval_policy, quorum_count, approval_sequence, review_deadline_days
    ) values (
      draft_row.id,
      additional_org_id,
      additional_role,
      case
        when additional_role in ('governance', 'observer') then false
        else coalesce((organization_item ->> 'staffingEnabled')::boolean, true)
      end,
      caller,
      case
        when organization_item ->> 'approvalPolicy' in ('one_of', 'all', 'quorum')
          then organization_item ->> 'approvalPolicy'
        else 'one_of'
      end,
      greatest(1, coalesce(nullif(organization_item ->> 'quorumCount', '')::int, 1)),
      greatest(1, coalesce(nullif(organization_item ->> 'sequence', '')::int, 1)),
      greatest(1, least(90, coalesce(nullif(organization_item ->> 'reviewDeadlineDays', '')::int, 5)))
    )
    on conflict (draft_id, org_id) do update
      set participation_role = excluded.participation_role,
          staffing_enabled = excluded.staffing_enabled,
          requested_by = excluded.requested_by,
          approval_policy = excluded.approval_policy,
          quorum_count = excluded.quorum_count,
          approval_sequence = excluded.approval_sequence,
          review_deadline_days = excluded.review_deadline_days;

    insert into public.audit_events (
      actor_id, actor_name, entity_type, entity_id, action, after_data, org_id
    ) values (
      caller, caller_name, 'collaboration_draft', draft_row.id::text,
      'collaboration.organization_added',
      jsonb_build_object(
        'organizationId', additional_org_id,
        'participationRole', additional_role
      ),
      p_owner_org_id
    );
  end loop;

  insert into public.audit_events (
    actor_id, actor_name, entity_type, entity_id, action, after_data, org_id
  ) values (
    caller, caller_name, 'collaboration_draft', draft_row.id::text,
    'collaboration.draft_created',
    jsonb_build_object('title', draft_row.title, 'sourceType', draft_row.source_type, 'revision', 1),
    draft_row.owner_org_id
  );

  return draft_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_petty_cash_allocation_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  allocation public.work_budget_allocations;
  parent_allocation public.work_budget_allocations;
  child_allocated numeric := 0;
  parent_cash_committed numeric := 0;
  own_cash_committed numeric := 0;
  new_amount numeric := 0;
begin
  select * into allocation
  from public.work_budget_allocations
  where id = new.allocation_id;
  if not found then return new; end if;

  if new.status in ('draft', 'rejected', 'cancelled', 'leader_changes_requested', 'department_changes_requested') then
    return new;
  end if;

  new_amount := case
    when new.status = 'settled' then coalesce(new.actual_spent, 0)
    else coalesce(new.approved_amount, new.requested_amount, 0)
  end;

  select coalesce(sum(case when status = 'settled' then coalesce(actual_spent, 0)
    else coalesce(approved_amount, requested_amount, 0) end), 0)
  into own_cash_committed
  from public.petty_cash_requests
  where allocation_id = allocation.id
    and id <> new.id
    and status not in ('draft', 'rejected', 'cancelled', 'leader_changes_requested', 'department_changes_requested');
  if own_cash_committed + new_amount > allocation.amount then
    raise exception 'This work allocation does not have enough remaining funds' using errcode = '22023';
  end if;

  if allocation.subtask_id is not null then
    select * into parent_allocation
    from public.work_budget_allocations
    where commitment_id = allocation.commitment_id
      and task_id = allocation.task_id
      and subtask_id is null
      and status = 'approved';
  else
    parent_allocation := allocation;
  end if;
  if parent_allocation.id is null then return new; end if;

  select coalesce(sum(amount), 0) into child_allocated
  from public.work_budget_allocations
  where commitment_id = parent_allocation.commitment_id
    and task_id = parent_allocation.task_id
    and subtask_id is not null
    and status in ('pending', 'approved')
    and id <> allocation.id;

  if allocation.subtask_id is not null then
    child_allocated := child_allocated + allocation.amount;
  end if;

  select coalesce(sum(case when status = 'settled' then coalesce(actual_spent, 0)
    else coalesce(approved_amount, requested_amount, 0) end), 0)
  into parent_cash_committed
  from public.petty_cash_requests
  where allocation_id = parent_allocation.id
    and id <> new.id
    and status not in ('draft', 'rejected', 'cancelled', 'leader_changes_requested', 'department_changes_requested');

  if new.allocation_id = parent_allocation.id then
    parent_cash_committed := parent_cash_committed + new_amount;
  end if;

  if child_allocated + parent_cash_committed > parent_allocation.amount then
    raise exception 'The task budget has already been distributed to subtasks or committed to task-level petty cash' using errcode = '22023';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_subtask_budget_allocation(p_task_id uuid, p_subtask_id uuid, p_parent_allocation_line_id uuid, p_amount numeric, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  task public.tasks;
  subtask public.subtasks;
  parent_allocation public.work_budget_allocations;
  created_allocation_id uuid;
  target_fiscal_budget_id uuid;
begin
  if caller is null then raise exception 'Not authenticated' using errcode = '42501'; end if;
  if p_amount <= 0 or nullif(btrim(p_reason), '') is null then
    raise exception 'Enter a positive amount and purpose' using errcode = '22023';
  end if;

  select * into task from public.tasks where id = p_task_id;
  if not found then raise exception 'Task not found' using errcode = 'P0002'; end if;
  select * into subtask from public.subtasks where id = p_subtask_id and task_id = task.id;
  if not found then raise exception 'Subtask does not belong to this task' using errcode = '22023'; end if;
  if caller is distinct from coalesce(task.recommendation_lead_id, task.assigned_to) then
    raise exception 'Only the Task Leader can distribute task funding to a subtask' using errcode = '42501';
  end if;

  select * into parent_allocation
  from public.work_budget_allocations
  where task_id = task.id and subtask_id is null and status = 'approved'
  for update;
  if not found then raise exception 'The task has no approved proposal allocation' using errcode = '22023'; end if;

  insert into public.work_budget_allocations(
    commitment_id, task_id, subtask_id, parent_allocation_line_id, amount,
    status, reason, requested_by, decided_by, decision_reason, requested_at, decided_at
  ) values (
    parent_allocation.commitment_id, task.id, p_subtask_id, p_parent_allocation_line_id, p_amount,
    'approved', btrim(p_reason), caller, caller,
    'Distributed by the Task Leader from the approved task budget', now(), now()
  ) returning id into created_allocation_id;

  if p_parent_allocation_line_id is not null then
    insert into public.work_budget_allocation_lines(
      allocation_id, draft_task_key, expense_class, category, particular,
      quantity, unit, unit_cost, amount, fund_source, position
    )
    select created_allocation_id, draft_task_key, expense_class, category, particular,
      1, 'allocation', p_amount, p_amount, fund_source, 0
    from public.work_budget_allocation_lines
    where id = p_parent_allocation_line_id;
  end if;

  select commitment.fiscal_budget_id into target_fiscal_budget_id
  from public.budget_commitments commitment
  where commitment.id = parent_allocation.commitment_id;
  insert into public.budget_ledger_entries(
    fiscal_budget_id, org_id, commitment_id, allocation_id, entry_type, amount, description, actor_id, metadata
  ) values (
    target_fiscal_budget_id, task.org_id, parent_allocation.commitment_id, created_allocation_id,
    'allocation_approved', p_amount, 'Task Leader distributed approved task funding to a subtask', caller,
    jsonb_build_object('taskId', task.id, 'subtaskId', subtask.id)
  );

  insert into public.notifications(
    user_id, type, title, message, task_id, task_title, actor_id, actor_name, financial_record_id, financial_record_type
  )
  select distinct contributor_id, 'subtask_budget_assigned', 'Subtask budget assigned',
    to_char(p_amount, 'FM999G999G999G990D00') || ' was assigned to your subtask "' || subtask.title || '".',
    task.id, task.title, caller, coalesce(profile.full_name, ''), created_allocation_id, 'work_budget_allocation'
  from unnest(coalesce(subtask.assigned_to_ids, '{}'::uuid[])) contributor_id
  left join public.profiles profile on profile.id = caller
  where contributor_id <> caller;

  return created_allocation_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_subtask_budget_allocation(p_allocation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  alloc public.work_budget_allocations;
  task public.tasks;
  subtask public.subtasks;
  task_leader uuid;
  active_requests_count int;
  target_fiscal_budget_id uuid;
begin
  if caller is null then raise exception 'Not authenticated' using errcode = '42501'; end if;

  select * into alloc from public.work_budget_allocations where id = p_allocation_id;
  if not found then raise exception 'Allocation not found' using errcode = 'P0002'; end if;
  if alloc.subtask_id is null then
    raise exception 'Cannot delete a parent task budget allocation' using errcode = '22023';
  end if;

  select * into task from public.tasks where id = alloc.task_id;
  if not found then raise exception 'Task not found' using errcode = 'P0002'; end if;

  task_leader := coalesce(task.recommendation_lead_id, task.assigned_to);
  if caller is distinct from task_leader then
    raise exception 'Only the Task Leader can remove a subtask budget cap' using errcode = '42501';
  end if;

  -- Check if any cash requests exist for this allocation
  select count(*) into active_requests_count
  from public.petty_cash_requests
  where allocation_id = alloc.id
    and status not in ('rejected', 'cancelled');
  if active_requests_count > 0 then
    raise exception 'Cannot remove subtask cap because active petty-cash requests exist against it' using errcode = '22023';
  end if;

  select * into subtask from public.subtasks where id = alloc.subtask_id;

  select commitment.fiscal_budget_id into target_fiscal_budget_id
  from public.budget_commitments commitment
  where commitment.id = alloc.commitment_id;

  -- Delete child allocation lines
  delete from public.work_budget_allocation_lines where allocation_id = alloc.id;

  -- Delete allocation record
  delete from public.work_budget_allocations where id = alloc.id;

  -- Record ledger entry for reversal
  if target_fiscal_budget_id is not null then
    insert into public.budget_ledger_entries(
      fiscal_budget_id, org_id, commitment_id, allocation_id, entry_type, amount, description, actor_id, metadata
    ) values (
      target_fiscal_budget_id, task.org_id, alloc.commitment_id, null,
      'allocation_adjusted', alloc.amount, 'Task Leader removed subtask budget cap (reverted to shared pool)', caller,
      jsonb_build_object('taskId', task.id, 'subtaskId', alloc.subtask_id, 'revertedAmount', alloc.amount)
    );
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_petty_cash_request(p_allocation_id uuid, p_amount numeric, p_purpose text, p_needed_by date, p_subtask_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  allocation public.work_budget_allocations;
  commitment public.budget_commitments;
  budget public.department_fiscal_budgets;
  task public.tasks;
  subtask public.subtasks;
  resolved_subtask_id uuid;
  request_id uuid;
  task_leader uuid;
  request_status text;
  allocation_used numeric := 0;
  child_caps_total numeric := 0;
  task_total_used numeric := 0;
  is_authorized boolean := false;
begin
  if caller is null then raise exception 'Not authenticated' using errcode = '42501'; end if;
  if p_amount <= 0 then raise exception 'Requested amount must be greater than zero' using errcode = '22023'; end if;
  if nullif(btrim(p_purpose), '') is null then raise exception 'Explain what the petty cash will be used for' using errcode = '22023'; end if;

  select * into allocation from public.work_budget_allocations where id = p_allocation_id and status = 'approved';
  if not found then raise exception 'Choose an approved task or subtask budget allocation' using errcode = '22023'; end if;

  select * into commitment from public.budget_commitments where id = allocation.commitment_id and status = 'active';
  if not found then raise exception 'The proposal budget is no longer active' using errcode = '22023'; end if;

  select * into budget from public.department_fiscal_budgets where id = commitment.fiscal_budget_id and status = 'locked';
  if not found then raise exception 'The annual department budget is no longer open' using errcode = '22023'; end if;

  select * into task from public.tasks where id = allocation.task_id;
  if not found then raise exception 'The funded task no longer exists' using errcode = 'P0002'; end if;

  task_leader := coalesce(task.recommendation_lead_id, task.assigned_to);
  if task_leader is null then raise exception 'This task has no Team Leader for petty-cash routing' using errcode = '22023'; end if;

  resolved_subtask_id := coalesce(p_subtask_id, allocation.subtask_id);

  if resolved_subtask_id is not null then
    select * into subtask from public.subtasks where id = resolved_subtask_id and task_id = task.id;
  end if;

  -- Authorization check:
  if caller = task_leader then
    is_authorized := true;
  elsif allocation.subtask_id is not null then
    if subtask.id is not null and coalesce(subtask.assigned_to_ids, '{}'::uuid[]) @> array[caller] then
      is_authorized := true;
    end if;
  elsif resolved_subtask_id is not null then
    if subtask.id is not null and coalesce(subtask.assigned_to_ids, '{}'::uuid[]) @> array[caller] then
      is_authorized := true;
    end if;
  elsif coalesce(task.team_member_ids, '{}'::uuid[]) @> array[caller] or task.assigned_to = caller then
    is_authorized := true;
  end if;

  if not is_authorized then
    raise exception 'Only the Task Leader or an assigned contributor can request against this allocation' using errcode = '42501';
  end if;

  -- Budget availability check:
  if allocation.subtask_id is not null then
    select coalesce(sum(case when status = 'settled' then actual_spent else coalesce(approved_amount, requested_amount) end), 0) into allocation_used
    from public.petty_cash_requests
    where allocation_id = allocation.id
      and status not in ('rejected', 'cancelled', 'leader_changes_requested', 'department_changes_requested');

    if allocation_used + p_amount > allocation.amount then
      raise exception 'This subtask budget cap does not have enough remaining funds (Max: %)',
        to_char(allocation.amount - allocation_used, 'FM999G999G990D00') using errcode = '22023';
    end if;
  else
    select coalesce(sum(case when status = 'settled' then actual_spent else coalesce(approved_amount, requested_amount) end), 0) into task_total_used
    from public.petty_cash_requests
    where allocation_id = allocation.id
      and status not in ('rejected', 'cancelled', 'leader_changes_requested', 'department_changes_requested');

    select coalesce(sum(amount), 0) into child_caps_total
    from public.work_budget_allocations
    where task_id = task.id
      and subtask_id is not null
      and status = 'approved';

    if (task_total_used + child_caps_total + p_amount) > allocation.amount then
      raise exception 'The shared task budget does not have enough remaining funds (Available: %)',
        to_char(greatest(0, allocation.amount - task_total_used - child_caps_total), 'FM999G999G990D00') using errcode = '22023';
    end if;
  end if;

  request_status := case when caller = task_leader then 'pending_department_approval' else 'pending_leader_review' end;

  insert into public.petty_cash_requests(
    fiscal_budget_id, commitment_id, allocation_id, org_id, task_id, subtask_id,
    requester_id, task_leader_id, cash_recipient_id, purpose, requested_amount, needed_by, status
  ) values (
    budget.id, commitment.id, allocation.id, budget.org_id, allocation.task_id, resolved_subtask_id,
    caller, task_leader, caller, btrim(p_purpose), p_amount, p_needed_by, request_status
  ) returning id into request_id;

  if request_status = 'pending_leader_review' then
    insert into public.notifications(user_id, type, title, message, task_id, task_title, actor_id, actor_name, financial_record_id, financial_record_type)
    select task_leader, 'petty_cash_leader_review', 'Petty cash needs your endorsement',
      coalesce(profile.full_name, 'A team member') || ' requested ' || to_char(p_amount, 'FM999G999G990D00') || ' for "' || coalesce(subtask.title, task.title) || '".',
      task.id, task.title, caller, coalesce(profile.full_name, ''), request_id, 'petty_cash_request'
    from public.profiles profile where profile.id = caller and task_leader <> caller;
  else
    insert into public.notifications(user_id, type, title, message, task_id, task_title, actor_id, actor_name, financial_record_id, financial_record_type)
    select approver_id, 'petty_cash_department_approval', 'Petty cash awaiting department approval',
      coalesce(profile.full_name, 'A Task Leader') || ' requested ' || to_char(p_amount, 'FM999G999G990D00') || ' for "' || coalesce(subtask.title, task.title) || '".',
      task.id, task.title, caller, coalesce(profile.full_name, ''), request_id, 'petty_cash_request'
    from public.organization_approver_ids(task.org_id) approver_id
    left join public.profiles profile on profile.id = caller
    where approver_id <> caller;
  end if;

  return request_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_collaboration_organizations(p_draft_id uuid, p_organizations jsonb, p_snapshot jsonb, p_change_summary text DEFAULT 'Collaboration organizations updated'::text)
 RETURNS proposal_collaboration_revisions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  draft_row public.proposal_collaboration_drafts;
  item jsonb;
  target_org uuid;
  target_role text;
begin
  if not public.can_manage_collaboration_draft(p_draft_id, caller) then
    raise exception 'Only the owning organization may change collaboration scope'
      using errcode = '42501';
  end if;
  if jsonb_typeof(coalesce(p_organizations, '[]'::jsonb)) <> 'array' then
    raise exception 'Organizations must be an array' using errcode = '22023';
  end if;

  select * into draft_row
  from public.proposal_collaboration_drafts
  where id = p_draft_id
  for update;

  delete from public.proposal_collaboration_orgs
  where draft_id = p_draft_id and participation_role <> 'owner';

  for item in select value from jsonb_array_elements(p_organizations)
  loop
    target_org := nullif(item ->> 'orgId', '')::uuid;
    target_role := coalesce(nullif(item ->> 'participationRole', ''), 'participant');
    if target_org is null or target_org = draft_row.owner_org_id then continue; end if;
    if target_role not in ('participant', 'governance', 'observer') then
      raise exception 'Invalid collaboration participation level' using errcode = '22023';
    end if;
    if not exists (
      select 1 from public.organizations
      where id = target_org and is_active
    ) then
      raise exception 'A selected organization is not configured or active'
        using errcode = '22023';
    end if;

    insert into public.proposal_collaboration_orgs (
      draft_id, org_id, participation_role, staffing_enabled, requested_by,
      approval_policy, quorum_count, approval_sequence, review_deadline_days
    ) values (
      p_draft_id,
      target_org,
      target_role,
      case
        when target_role in ('governance', 'observer') then false
        else coalesce((item ->> 'staffingEnabled')::boolean, true)
      end,
      caller,
      case
        when item ->> 'approvalPolicy' in ('one_of', 'all', 'quorum')
          then item ->> 'approvalPolicy'
        else 'one_of'
      end,
      greatest(1, coalesce(nullif(item ->> 'quorumCount', '')::int, 1)),
      greatest(1, coalesce(nullif(item ->> 'sequence', '')::int, 1)),
      greatest(1, least(90, coalesce(nullif(item ->> 'reviewDeadlineDays', '')::int, 5)))
    );
  end loop;

  return public.save_collaboration_revision(p_draft_id, p_snapshot, p_change_summary);
end;
$function$

CREATE OR REPLACE FUNCTION public.task_budget_line_available(p_allocation_line_id uuid, p_exclude_request_id uuid DEFAULT NULL::uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  source_line public.work_budget_allocation_lines;
  task_allocation public.work_budget_allocations;
  cap_total numeric := 0;
  direct_obligation numeric := 0;
begin
  select * into source_line from public.work_budget_allocation_lines where id = p_allocation_line_id;
  if not found then return 0; end if;
  select * into task_allocation from public.work_budget_allocations
  where id = source_line.allocation_id and subtask_id is null and status = 'approved';
  if not found then return 0; end if;

  select coalesce(sum(cap.amount), 0) into cap_total
  from public.work_budget_allocations cap
  where cap.task_id = task_allocation.task_id
    and cap.commitment_id = task_allocation.commitment_id
    and cap.subtask_id is not null
    and cap.parent_allocation_line_id = source_line.id
    and cap.status in ('pending', 'approved');

  select coalesce(sum(public.cash_request_obligation(request)), 0) into direct_obligation
  from public.petty_cash_requests request
  join public.work_budget_allocations allocation on allocation.id = request.allocation_id
  where request.task_id = task_allocation.task_id
    and request.allocation_line_id = source_line.id
    and request.id is distinct from p_exclude_request_id
    and (
      allocation.subtask_id is null
      or allocation.status not in ('pending', 'approved')
    );

  return greatest(0, source_line.amount - cap_total - direct_obligation);
end;
$function$

CREATE OR REPLACE FUNCTION public.subtask_cap_available(p_cap_allocation_id uuid, p_exclude_request_id uuid DEFAULT NULL::uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cap public.work_budget_allocations; used numeric := 0;
begin
  select * into cap from public.work_budget_allocations
  where id = p_cap_allocation_id and subtask_id is not null and status in ('pending', 'approved');
  if not found then return 0; end if;
  select coalesce(sum(public.cash_request_obligation(request)), 0) into used
  from public.petty_cash_requests request
  where request.allocation_id = cap.id
    and request.id is distinct from p_exclude_request_id;
  return greatest(0, cap.amount - used);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_task_funding_context(p_task_id uuid, p_subtask_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  task_row public.tasks;
  task_allocation public.work_budget_allocations;
  cap public.work_budget_allocations;
  line_rows jsonb := '[]'::jsonb;
  task_available numeric := 0;
begin
  if not public.can_see_task(p_task_id, caller) then
    raise exception 'You cannot view funding for this task' using errcode = '42501';
  end if;
  select * into task_row from public.tasks where id = p_task_id and deleted_at is null;
  if not found then raise exception 'Task not found' using errcode = 'P0002'; end if;
  if p_subtask_id is not null and not exists (
    select 1 from public.subtasks where id = p_subtask_id and task_id = p_task_id
  ) then raise exception 'Subtask does not belong to this task' using errcode = '22023'; end if;
  select * into task_allocation from public.work_budget_allocations
  where task_id = p_task_id and subtask_id is null and status = 'approved';
  if not found then
    return jsonb_build_object('funded', false, 'taskId', p_task_id, 'subtaskId', p_subtask_id);
  end if;
  if p_subtask_id is not null then
    select * into cap from public.work_budget_allocations
    where task_id = p_task_id and subtask_id = p_subtask_id and status = 'approved';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', line.id,
      'expenseClass', line.expense_class,
      'category', line.category,
      'particular', line.particular,
      'fundSource', line.fund_source,
      'amount', line.amount,
      'available', case
        when cap.id is not null and cap.parent_allocation_line_id = line.id
          then public.subtask_cap_available(cap.id)
        when cap.id is not null then 0
        else public.task_budget_line_available(line.id)
      end
    ) order by line.position), '[]'::jsonb),
    coalesce(sum(case
      when cap.id is not null and cap.parent_allocation_line_id = line.id
        then public.subtask_cap_available(cap.id)
      when cap.id is not null then 0
      else public.task_budget_line_available(line.id)
    end), 0)
  into line_rows, task_available
  from public.work_budget_allocation_lines line
  where line.allocation_id = task_allocation.id;
  return jsonb_build_object(
    'funded', true,
    'taskId', task_row.id,
    'subtaskId', p_subtask_id,
    'taskAllocationId', task_allocation.id,
    'taskBudget', task_allocation.amount,
    'available', task_available,
    'taskLeaderId', coalesce(task_row.assigned_to, task_row.recommendation_lead_id),
    'cap', case when cap.id is null then null else jsonb_build_object(
      'id', cap.id, 'amount', cap.amount, 'available', public.subtask_cap_available(cap.id),
      'allocationLineId', cap.parent_allocation_line_id, 'reason', cap.reason
    ) end,
    'lines', line_rows
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_contextual_cash_request(p_task_id uuid, p_subtask_id uuid, p_allocation_line_id uuid, p_amount numeric, p_purpose text, p_needed_by date, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  existing_id uuid;
  task_row public.tasks;
  task_leader uuid;
  task_allocation public.work_budget_allocations;
  source_line public.work_budget_allocation_lines;
  cap public.work_budget_allocations;
  target_allocation public.work_budget_allocations;
  commitment public.budget_commitments;
  fiscal public.department_fiscal_budgets;
  available numeric := 0;
  next_status text;
  request_id uuid;
begin
  if caller is null then raise exception 'Not authenticated' using errcode = '42501'; end if;
  if p_idempotency_key is null then raise exception 'A request idempotency key is required' using errcode = '22023'; end if;
  select id into existing_id from public.petty_cash_requests
  where requester_id = caller and idempotency_key = p_idempotency_key;
  if existing_id is not null then return existing_id; end if;
  if p_amount <= 0 then raise exception 'Requested amount must be greater than zero' using errcode = '22023'; end if;
  if nullif(btrim(p_purpose), '') is null then raise exception 'Describe what this cash will purchase' using errcode = '22023'; end if;
  if p_allocation_line_id is null then raise exception 'Select a proposal budget line and fund source' using errcode = '22023'; end if;

  select * into task_row from public.tasks where id = p_task_id and deleted_at is null;
  if not found then raise exception 'Funded task not found' using errcode = 'P0002'; end if;
  task_leader := coalesce(task_row.assigned_to, task_row.recommendation_lead_id);
  if task_leader is null then raise exception 'This task has no Task Leader for endorsement routing' using errcode = '22023'; end if;
  if p_subtask_id is null then
    if caller <> task_leader then raise exception 'Only the Task Leader can submit a task-level request' using errcode = '42501'; end if;
  else
    if not exists (select 1 from public.subtasks where id = p_subtask_id and task_id = p_task_id) then
      raise exception 'Subtask does not belong to this task' using errcode = '22023';
    end if;
    if caller <> task_leader and not exists (
      select 1 from public.subtasks subtask where subtask.id = p_subtask_id
        and coalesce(subtask.assigned_to_ids, '{}'::uuid[]) @> array[caller]
    ) then raise exception 'Only the Task Leader or an assigned contributor can request cash for this subtask' using errcode = '42501'; end if;
  end if;

  select * into task_allocation from public.work_budget_allocations
  where task_id = p_task_id and subtask_id is null and status = 'approved' for update;
  if not found then raise exception 'This task has no approved proposal budget' using errcode = '22023'; end if;
  select * into source_line from public.work_budget_allocation_lines
  where id = p_allocation_line_id and allocation_id = task_allocation.id for update;
  if not found then raise exception 'Select a valid proposal budget line for this task' using errcode = '22023'; end if;
  select * into commitment from public.budget_commitments
  where id = task_allocation.commitment_id and status = 'active';
  if not found then raise exception 'The proposal budget is no longer active' using errcode = '22023'; end if;
  select * into fiscal from public.department_fiscal_budgets
  where id = commitment.fiscal_budget_id and status = 'locked' for update;
  if not found then raise exception 'The annual department budget is no longer open' using errcode = '22023'; end if;

  if p_subtask_id is not null then
    select * into cap from public.work_budget_allocations
    where task_id = p_task_id and subtask_id = p_subtask_id and status = 'approved' for update;
  end if;
  if cap.id is not null then
    if cap.parent_allocation_line_id is distinct from source_line.id then
      raise exception 'This subtask cap is reserved for a different proposal budget line' using errcode = '22023';
    end if;
    target_allocation := cap;
    available := public.subtask_cap_available(cap.id);
  else
    target_allocation := task_allocation;
    available := public.task_budget_line_available(source_line.id);
  end if;
  if p_amount > available then
    raise exception 'Only % remains available on % · %',
      to_char(available, 'FM999G999G999G990D00'), source_line.category, source_line.particular using errcode = '22023';
  end if;

  next_status := case when caller = task_leader then 'pending_department_approval' else 'pending_leader_review' end;
  insert into public.petty_cash_requests(
    fiscal_budget_id, commitment_id, allocation_id, allocation_line_id, org_id,
    task_id, subtask_id, requester_id, task_leader_id, cash_recipient_id,
    purpose, requested_amount, needed_by, status, reservation_expires_at, idempotency_key
  ) values (
    fiscal.id, commitment.id, target_allocation.id, source_line.id, fiscal.org_id,
    task_row.id, p_subtask_id, caller, task_leader, caller,
    btrim(p_purpose), p_amount, p_needed_by, next_status, now() + interval '7 days', p_idempotency_key
  ) returning id into request_id;

  if next_status = 'pending_leader_review' then
    insert into public.notifications(user_id, type, title, message, task_id, task_title, actor_id, actor_name, financial_record_id, financial_record_type)
    select task_leader, 'petty_cash_leader_review', 'Cash request needs your endorsement',
      coalesce(profile.full_name, 'A contributor') || ' requested ' || to_char(p_amount, 'FM999G999G999G990D00') ||
      ' for ' || btrim(p_purpose) || ' in "' || task_row.title || '".',
      task_row.id, task_row.title, caller, coalesce(profile.full_name, ''), request_id, 'petty_cash_request'
    from public.profiles profile where profile.id = caller and task_leader <> caller;
  else
    insert into public.notifications(user_id, type, title, message, task_id, task_title, actor_id, actor_name, financial_record_id, financial_record_type)
    select approver_id, 'petty_cash_department_approval', 'Cash request needs fiscal authorization',
      coalesce(profile.full_name, 'A Task Leader') || ' requested ' || to_char(p_amount, 'FM999G999G999G990D00') ||
      ' for ' || btrim(p_purpose) || ' in "' || task_row.title || '".',
      task_row.id, task_row.title, caller, coalesce(profile.full_name, ''), request_id, 'petty_cash_request'
    from public.organization_approver_ids(fiscal.org_id) approver_id
    left join public.profiles profile on profile.id = caller
    where approver_id <> caller;
  end if;
  return request_id;
exception
  when unique_violation then
    select id into existing_id from public.petty_cash_requests
    where requester_id = caller and idempotency_key = p_idempotency_key;
    if existing_id is not null then return existing_id; end if;
    raise;
end;
$function$

CREATE OR REPLACE FUNCTION public.resubmit_contextual_cash_request(p_request_id uuid, p_allocation_line_id uuid, p_amount numeric, p_purpose text, p_needed_by date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  request public.petty_cash_requests;
  allocation public.work_budget_allocations;
  source_line public.work_budget_allocation_lines;
  available numeric := 0;
  next_status text;
begin
  select * into request from public.petty_cash_requests where id = p_request_id for update;
  if not found then raise exception 'Cash request not found' using errcode = 'P0002'; end if;
  if request.requester_id <> caller then raise exception 'Only the requester can correct this request' using errcode = '42501'; end if;
  if request.status not in ('leader_changes_requested', 'department_changes_requested') then
    raise exception 'This request is not awaiting corrections' using errcode = '22023';
  end if;
  if p_amount <= 0 or nullif(btrim(p_purpose), '') is null then
    raise exception 'Enter a positive amount and purchase purpose' using errcode = '22023';
  end if;
  select * into source_line from public.work_budget_allocation_lines where id = p_allocation_line_id for update;
  if not found or source_line.allocation_id <> (
    select id from public.work_budget_allocations
    where task_id = request.task_id and subtask_id is null and status = 'approved'
  ) then raise exception 'Select a valid proposal budget line for this task' using errcode = '22023'; end if;
  select * into allocation from public.work_budget_allocations where id = request.allocation_id for update;
  if allocation.subtask_id is not null and allocation.status = 'approved' then
    if allocation.parent_allocation_line_id is distinct from source_line.id then
      raise exception 'This subtask cap is reserved for a different proposal budget line' using errcode = '22023';
    end if;
    available := public.subtask_cap_available(allocation.id, request.id);
  else
    available := public.task_budget_line_available(source_line.id, request.id);
  end if;
  if p_amount > available then raise exception 'The selected budget line has only % available', to_char(available, 'FM999G999G999G990D00') using errcode = '22023'; end if;
  next_status := case when request.requester_id = request.task_leader_id then 'pending_department_approval' else 'pending_leader_review' end;
  update public.petty_cash_requests set
    allocation_line_id = source_line.id,
    requested_amount = p_amount,
    purpose = btrim(p_purpose),
    needed_by = p_needed_by,
    status = next_status,
    approved_amount = null,
    approved_by = null,
    approval_reason = null,
    decided_at = null,
    leader_decided_by = null,
    leader_decision_reason = null,
    leader_decided_at = null,
    department_decision_reason = null,
    reservation_expires_at = now() + interval '7 days',
    updated_at = now()
  where id = request.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_subtask_budget_cap(p_task_id uuid, p_subtask_id uuid, p_parent_allocation_line_id uuid, p_amount numeric, p_reason text, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  task_row public.tasks;
  parent_allocation public.work_budget_allocations;
  parent_line public.work_budget_allocation_lines;
  cap public.work_budget_allocations;
  cap_id uuid;
  available numeric := 0;
  settled numeric := 0;
  event_type text;
  old_amount numeric;
begin
  if p_amount <= 0 then raise exception 'Cap amount must be greater than zero' using errcode = '22023'; end if;
  if nullif(btrim(p_reason), '') is null then raise exception 'Explain why this subtask needs a protected cap' using errcode = '22023'; end if;
  select * into task_row from public.tasks where id = p_task_id and deleted_at is null;
  if not found then raise exception 'Task not found' using errcode = 'P0002'; end if;
  if caller is distinct from coalesce(task_row.assigned_to, task_row.recommendation_lead_id) then
    raise exception 'Only the Task Leader can set a subtask cap' using errcode = '42501';
  end if;
  if not exists (select 1 from public.subtasks where id = p_subtask_id and task_id = p_task_id) then
    raise exception 'Subtask does not belong to this task' using errcode = '22023';
  end if;
  select * into parent_allocation from public.work_budget_allocations
  where task_id = p_task_id and subtask_id is null and status = 'approved' for update;
  if not found then raise exception 'This task has no approved proposal budget' using errcode = '22023'; end if;
  select * into parent_line from public.work_budget_allocation_lines
  where id = p_parent_allocation_line_id and allocation_id = parent_allocation.id for update;
  if not found then raise exception 'Select a valid proposal budget line for this task' using errcode = '22023'; end if;
  select * into cap from public.work_budget_allocations
  where task_id = p_task_id and subtask_id = p_subtask_id and status in ('pending', 'approved') for update;
  available := public.task_budget_line_available(parent_line.id)
    + case when cap.parent_allocation_line_id = parent_line.id then coalesce(cap.amount, 0) else 0 end;
  if p_amount > available then raise exception 'Only % is available to protect on this budget line', to_char(available, 'FM999G999G999G990D00') using errcode = '22023'; end if;
  if cap.id is not null then
    if exists (
      select 1 from public.petty_cash_requests request
      where request.allocation_id = cap.id
        and request.status not in ('draft', 'rejected', 'cancelled', 'expired', 'settled')
    ) then raise exception 'This cap has an active cash request and cannot be edited' using errcode = '22023'; end if;
    select coalesce(sum(actual_spent), 0) into settled from public.petty_cash_requests
    where allocation_id = cap.id and status = 'settled';
    if p_amount < settled then raise exception 'The cap cannot be lower than its settled spending of %', to_char(settled, 'FM999G999G999G990D00') using errcode = '22023'; end if;
    old_amount := cap.amount;
    update public.work_budget_allocations set
      parent_allocation_line_id = parent_line.id,
      amount = p_amount,
      status = 'approved',
      reason = btrim(p_reason),
      decided_by = caller,
      decision_reason = 'Protected by Task Leader',
      decided_at = now(),
      updated_at = now()
    where id = cap.id returning id into cap_id;
    update public.work_budget_allocation_lines set
      expense_class = parent_line.expense_class,
      category = parent_line.category,
      particular = parent_line.particular,
      quantity = 1,
      unit = 'cap',
      unit_cost = p_amount,
      amount = p_amount,
      fund_source = parent_line.fund_source
    where allocation_id = cap.id;
    event_type := 'subtask_cap_changed';
  else
    insert into public.work_budget_allocations(
      commitment_id, task_id, subtask_id, parent_allocation_line_id, amount,
      status, reason, requested_by, decided_by, decision_reason, requested_at, decided_at
    ) values (
      parent_allocation.commitment_id, p_task_id, p_subtask_id, parent_line.id, p_amount,
      'approved', btrim(p_reason), caller, caller, 'Protected by Task Leader', now(), now()
    ) returning id into cap_id;
    insert into public.work_budget_allocation_lines(
      allocation_id, draft_task_key, expense_class, category, particular,
      quantity, unit, unit_cost, amount, fund_source, position
    ) values (
      cap_id, parent_line.draft_task_key, parent_line.expense_class, parent_line.category,
      parent_line.particular, 1, 'cap', p_amount, p_amount, parent_line.fund_source, 0
    );
    event_type := 'subtask_cap_created';
    old_amount := 0;
  end if;
  insert into public.budget_ledger_entries(
    fiscal_budget_id, org_id, commitment_id, allocation_id, task_id, subtask_id,
    allocation_line_id, entry_type, amount, description, actor_id, actor_role,
    previous_state, new_state, reason, correlation_key, metadata
  ) select commitment.fiscal_budget_id, task_row.org_id, parent_allocation.commitment_id,
      cap_id, p_task_id, p_subtask_id, parent_line.id, event_type,
      abs(p_amount - coalesce(old_amount, 0)), 'Subtask funding cap protected by Task Leader',
      caller, profile.role::text, coalesce(old_amount, 0)::text, p_amount::text,
      btrim(p_reason), p_idempotency_key,
      jsonb_build_object('fundSource', parent_line.fund_source, 'category', parent_line.category, 'particular', parent_line.particular)
    from public.budget_commitments commitment
    left join public.profiles profile on profile.id = caller
    where commitment.id = parent_allocation.commitment_id
  on conflict (actor_id, correlation_key, entry_type) where actor_id is not null and correlation_key is not null do nothing;
  return cap_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_subtask_budget_cap(p_cap_allocation_id uuid, p_reason text, p_idempotency_key uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare caller uuid := auth.uid(); cap public.work_budget_allocations; task_row public.tasks; unused numeric;
begin
  select * into cap from public.work_budget_allocations
  where id = p_cap_allocation_id and subtask_id is not null and status in ('pending', 'approved') for update;
  if not found then raise exception 'Active subtask cap not found' using errcode = 'P0002'; end if;
  select * into task_row from public.tasks where id = cap.task_id;
  if caller is distinct from coalesce(task_row.assigned_to, task_row.recommendation_lead_id) then
    raise exception 'Only the Task Leader can remove a subtask cap' using errcode = '42501';
  end if;
  if nullif(btrim(p_reason), '') is null then raise exception 'Explain why the cap is being removed' using errcode = '22023'; end if;
  if exists (
    select 1 from public.petty_cash_requests request
    where request.allocation_id = cap.id
      and request.status not in ('draft', 'rejected', 'cancelled', 'expired', 'settled')
  ) then raise exception 'This cap has an active cash request and cannot be removed' using errcode = '22023'; end if;
  unused := public.subtask_cap_available(cap.id);
  update public.work_budget_allocations set status = 'cancelled', decision_reason = btrim(p_reason), updated_at = now() where id = cap.id;
  insert into public.budget_ledger_entries(
    fiscal_budget_id, org_id, commitment_id, allocation_id, task_id, subtask_id,
    allocation_line_id, entry_type, amount, description, actor_id, actor_role,
    previous_state, new_state, reason, correlation_key
  ) select commitment.fiscal_budget_id, task_row.org_id, cap.commitment_id, cap.id,
      cap.task_id, cap.subtask_id, cap.parent_allocation_line_id, 'subtask_cap_removed',
      unused, 'Unused subtask cap returned to shared task funding', caller,
      profile.role::text, 'approved', 'cancelled', btrim(p_reason), p_idempotency_key
    from public.budget_commitments commitment
    left join public.profiles profile on profile.id = caller
    where commitment.id = cap.commitment_id
  on conflict (actor_id, correlation_key, entry_type) where actor_id is not null and correlation_key is not null do nothing;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_contextual_cash_request(p_request_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare caller uuid := auth.uid(); request public.petty_cash_requests;
begin
  select * into request from public.petty_cash_requests where id = p_request_id for update;
  if not found then raise exception 'Cash request not found' using errcode = 'P0002'; end if;
  if request.requester_id <> caller and not public.is_department_budget_approver(request.org_id, caller) then
    raise exception 'Only the requester or a fiscal approver can cancel this request' using errcode = '42501';
  end if;
  if request.status in ('partially_released', 'released', 'liquidation_submitted', 'pending_leader_liquidation_review', 'pending_department_settlement', 'changes_requested', 'overdue_liquidation', 'settled') then
    raise exception 'Released cash must be liquidated rather than cancelled' using errcode = '22023';
  end if;
  if request.status in ('rejected', 'cancelled', 'expired') then return; end if;
  if nullif(btrim(p_reason), '') is null then raise exception 'A cancellation reason is required' using errcode = '22023'; end if;
  update public.petty_cash_releases set status = 'cancelled'
  where request_id = request.id and status = 'scheduled';
  update public.petty_cash_requests set status = 'cancelled', approval_reason = btrim(p_reason), updated_at = now()
  where id = request.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.add_cash_request_attachment(p_request_id uuid, p_file_name text, p_file_path text, p_mime_type text, p_file_size bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare caller uuid := auth.uid(); request public.petty_cash_requests; attachment_id uuid; actor_role_value text;
begin
  select * into request from public.petty_cash_requests where id = p_request_id;
  if not found then raise exception 'Cash request not found' using errcode = 'P0002'; end if;
  if request.requester_id <> caller then raise exception 'Only the requester can attach purchase evidence' using errcode = '42501'; end if;
  if nullif(btrim(p_file_name), '') is null or nullif(btrim(p_file_path), '') is null or p_file_size < 0 then
    raise exception 'Attachment metadata is invalid' using errcode = '22023';
  end if;
  insert into public.petty_cash_request_attachments(request_id, file_name, file_path, mime_type, file_size, created_by)
  values (request.id, btrim(p_file_name), btrim(p_file_path), coalesce(nullif(btrim(p_mime_type), ''), 'application/octet-stream'), p_file_size, caller)
  returning id into attachment_id;
  select role::text into actor_role_value from public.profiles where id = caller;
  insert into public.budget_ledger_entries(
    fiscal_budget_id, org_id, commitment_id, allocation_id, petty_cash_request_id,
    task_id, subtask_id, allocation_line_id, entry_type, amount, description,
    actor_id, actor_role, new_state, metadata
  ) values (
    request.fiscal_budget_id, request.org_id, request.commitment_id, request.allocation_id, request.id,
    request.task_id, request.subtask_id, request.allocation_line_id, 'request_evidence_attached',
    0, 'Purchase quote or supporting evidence attached', caller, actor_role_value, 'attached',
    jsonb_build_object('attachmentId', attachment_id, 'fileName', p_file_name, 'filePath', p_file_path)
  );
  return attachment_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_contextual_cash_liquidation(p_request_id uuid, p_declared_spent numeric, p_note text, p_receipts jsonb, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare existing_id uuid; created_id uuid;
begin
  if p_idempotency_key is null then raise exception 'A liquidation idempotency key is required' using errcode = '22023'; end if;
  select id into existing_id from public.petty_cash_liquidations
  where request_id = p_request_id and idempotency_key = p_idempotency_key;
  if existing_id is not null then return existing_id; end if;
  created_id := public.submit_petty_cash_liquidation(p_request_id, p_declared_spent, p_note, p_receipts);
  update public.petty_cash_liquidations set idempotency_key = p_idempotency_key where id = created_id;
  return created_id;
exception
  when unique_violation then
    select id into existing_id from public.petty_cash_liquidations
    where request_id = p_request_id and idempotency_key = p_idempotency_key;
    if existing_id is not null then return existing_id; end if;
    raise;
end;
$function$

CREATE OR REPLACE FUNCTION public.normalize_cash_request_reservation_window()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status in ('pending', 'pending_leader_review', 'pending_department_approval') then
    if tg_op = 'INSERT' or new.reservation_expires_at is null or new.status is distinct from old.status then
      new.reservation_expires_at := now() + interval '7 days';
    end if;
  else
    new.reservation_expires_at := null;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_corrected_cash_request_reviewer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  task_title_value text;
  actor_name_value text;
begin
  if old.status not in ('leader_changes_requested', 'department_changes_requested')
     or new.status not in ('pending_leader_review', 'pending_department_approval') then
    return new;
  end if;

  select task.title into task_title_value from public.tasks task where task.id = new.task_id;
  select profile.full_name into actor_name_value from public.profiles profile where profile.id = new.requester_id;

  if new.status = 'pending_leader_review' then
    insert into public.notifications(
      user_id, type, title, message, task_id, task_title,
      actor_id, actor_name, financial_record_id, financial_record_type
    ) values (
      new.task_leader_id, 'petty_cash_leader_review', 'Corrected cash request needs your endorsement',
      coalesce(actor_name_value, 'A contributor') || ' corrected and resubmitted ' ||
        to_char(new.requested_amount, 'FM999G999G999G990D00') || ' for ' || new.purpose ||
        ' in "' || coalesce(task_title_value, 'Funded task') || '".',
      new.task_id, coalesce(task_title_value, ''), new.requester_id,
      coalesce(actor_name_value, ''), new.id, 'petty_cash_request'
    );
  else
    insert into public.notifications(
      user_id, type, title, message, task_id, task_title,
      actor_id, actor_name, financial_record_id, financial_record_type
    )
    select approver_id, 'petty_cash_department_approval', 'Corrected cash request needs fiscal authorization',
      coalesce(actor_name_value, 'A Task Leader') || ' corrected and resubmitted ' ||
        to_char(new.requested_amount, 'FM999G999G999G990D00') || ' for ' || new.purpose ||
        ' in "' || coalesce(task_title_value, 'Funded task') || '".',
      new.task_id, coalesce(task_title_value, ''), new.requester_id,
      coalesce(actor_name_value, ''), new.id, 'petty_cash_request'
    from public.organization_approver_ids(new.org_id) approver_id
    where approver_id <> new.requester_id;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_collaboration_review(p_draft_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  draft_row public.proposal_collaboration_drafts;
  current_revision public.proposal_collaboration_revisions;
  finalized_revision public.proposal_collaboration_revisions;
  caller_name text := '';
begin
  if not public.can_manage_collaboration_draft(p_draft_id, caller) then
    raise exception 'Only the owning organization may request collaboration review' using errcode = '42501';
  end if;
  select * into draft_row from public.proposal_collaboration_drafts where id = p_draft_id for update;
  if not found then raise exception 'Work plan not found' using errcode = 'P0002'; end if;
  if draft_row.status in ('committed','archived','deleted') or draft_row.deleted_at is not null then
    raise exception 'This work plan can no longer request approval' using errcode = '22023';
  end if;
  if draft_row.current_revision_id is null then raise exception 'Publish a revision before requesting review' using errcode = '22023'; end if;
  select * into current_revision from public.proposal_collaboration_revisions where id = draft_row.current_revision_id;
  if current_revision.snapshot is distinct from draft_row.working_snapshot then
    select * into finalized_revision from public.save_collaboration_revision(
      p_draft_id, draft_row.working_snapshot, 'Work plan updated for department approval'
    );
    draft_row.current_revision_id := finalized_revision.id;
  end if;

  -- Serialize on the draft row and suppress rapid repeat clicks on the same plan.
  -- A deliberate reminder remains possible after ten seconds.
  if draft_row.status = 'in_review' and exists (
    select 1 from public.audit_events event
    where event.entity_id = p_draft_id::text
      and event.action = 'collaboration.review_requested'
      and event.after_data ->> 'revisionId' = draft_row.current_revision_id::text
      and event.created_at > now() - interval '10 seconds'
  ) then return; end if;

  update public.proposal_collaboration_drafts set status = 'in_review' where id = p_draft_id;
  update public.proposal_collaboration_orgs set requested_by = caller, requested_at = now() where draft_id = p_draft_id and participation_role in ('participant','governance');
  select coalesce(full_name, 'Owner') into caller_name from public.profiles where id = caller;

  insert into public.notifications (
    user_id, type, title, message, actor_id, actor_name, proposal_id, org_id, entity_type
  )
  select approver_id, 'collaboration_request', 'Department approval requested',
    caller_name || ' requested review of "' || draft_row.title || '".',
    caller, caller_name, p_draft_id::text, participating.org_id, 'collaboration_draft'
  from public.proposal_collaboration_orgs participating
  cross join lateral public.organization_approver_ids(participating.org_id) approver_id
  where participating.draft_id = p_draft_id
    and participating.participation_role in ('participant','governance')
    and approver_id <> caller;

  insert into public.audit_events (actor_id, actor_name, entity_type, entity_id, action, after_data, org_id)
  values (caller, caller_name, 'collaboration_draft', p_draft_id::text, 'collaboration.review_requested',
    jsonb_build_object('revisionId', draft_row.current_revision_id, 'ownerOrganizationAutoAccepted', true), draft_row.owner_org_id);
  perform public.refresh_collaboration_readiness(p_draft_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_organization_membership(p_organization_id uuid, p_user_id uuid, p_membership_role text, p_reason text DEFAULT NULL::text)
 RETURNS organization_memberships
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_name text := '';
  result_row public.organization_memberships;
begin
  if caller is null then raise exception 'Not authenticated' using errcode = '42501'; end if;
  if p_membership_role not in ('member', 'primary_approver', 'backup_approver') then
    raise exception 'Invalid organization membership role' using errcode = '22023';
  end if;
  if not exists (select 1 from public.organizations where id = p_organization_id and is_active) then
    raise exception 'Organization not found or inactive' using errcode = 'P0002';
  end if;
  if not exists (select 1 from public.profiles where id = p_user_id and is_active) then
    raise exception 'Member must be an active eFlow user' using errcode = '22023';
  end if;
  if not (
    public.auth_role(caller) = 'admin'
    or public.is_organization_approver(p_organization_id, caller)
  ) then
    raise exception 'Only an organization approver or Admin may manage memberships'
      using errcode = '42501';
  end if;

  insert into public.organization_memberships (
    organization_id, user_id, membership_role, created_by
  ) values (
    p_organization_id, p_user_id, p_membership_role, caller
  )
  on conflict (organization_id, user_id) do update
    set membership_role = excluded.membership_role,
        updated_at = now()
  returning * into result_row;

  select coalesce(full_name, 'User') into caller_name from public.profiles where id = caller;
  insert into public.audit_events (
    actor_id, actor_name, entity_type, entity_id, action, reason, after_data, org_id
  ) values (
    caller, caller_name, 'organization_membership',
    p_organization_id::text || ':' || p_user_id::text,
    'organization.membership.updated', nullif(btrim(p_reason), ''),
    jsonb_build_object('organizationId', p_organization_id, 'userId', p_user_id, 'role', p_membership_role),
    p_organization_id
  );

  return result_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_project_permanently(p_project_id uuid, p_expected_title text, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_role text;
  caller_name text;
  project_row public.projects;
  retained_task_count int;
begin
  if caller is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  select role::text, full_name
    into caller_role, caller_name
  from public.profiles
  where id = caller and is_active;

  if caller_role not in ('admin', 'dept_head', 'department_head', 'assistant_head') then
    raise exception 'Only a Head, Assistant Head, or Admin may permanently delete a project'
      using errcode = '42501';
  end if;

  select * into project_row
  from public.projects
  where id = p_project_id
  for update;

  if not found then
    raise exception 'Project not found' using errcode = 'P0002';
  end if;

  if caller_role <> 'admin'
     and not public.org_in_my_subtree(project_row.org_id, caller) then
    raise exception 'This project is outside your organization scope'
      using errcode = '42501';
  end if;

  if coalesce(p_expected_title, '') <> project_row.title then
    raise exception 'Type the exact project title to confirm deletion'
      using errcode = '22023';
  end if;

  if length(btrim(coalesce(p_reason, ''))) < 5 then
    raise exception 'A deletion reason of at least 5 characters is required'
      using errcode = '22023';
  end if;

  select count(*)::int into retained_task_count
  from public.tasks
  where linked_project_id = p_project_id and deleted_at is null;

  update public.tasks
  set linked_project_id = null,
      milestone_id = null
  where linked_project_id = p_project_id;

  insert into public.audit_events (
    actor_id, actor_name, entity_type, entity_id, action, reason,
    before_data, after_data, org_id
  ) values (
    caller, coalesce(caller_name, 'Administrator'), 'project', p_project_id::text,
    'project.deleted', btrim(p_reason),
    jsonb_build_object(
      'title', project_row.title,
      'status', project_row.status,
      'ownerId', project_row.owner_id,
      'retainedTaskCount', retained_task_count
    ),
    jsonb_build_object('deleted', true, 'taskLinksCleared', retained_task_count),
    project_row.org_id
  );

  delete from public.projects where id = p_project_id;
  return p_project_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_last_active_admin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if old.role = 'admin' and old.is_active then
    if tg_op = 'DELETE' or new.role is distinct from 'admin' or new.is_active is distinct from true then
      -- VOLATILE trigger functions take a fresh snapshot for the count after
      -- this shared transaction lock. Concurrent removals cannot both pass.
      perform pg_advisory_xact_lock(hashtextextended('eflow.last_active_admin', 0));
      if not exists (select 1 from public.profiles where id <> old.id and role = 'admin' and is_active) then
        raise exception 'The last active Admin cannot be deleted, deactivated, or reassigned' using errcode = '42501';
      end if;
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_admin_role_permissions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare target_role text;
begin
  if tg_op = 'DELETE' then target_role := old.role; else target_role := new.role; end if;
  if auth.uid() is not null and not public.is_admin(auth.uid()) then
    raise exception 'Only Admin can manage role permissions' using errcode = '42501';
  end if;
  if target_role = 'super_admin' then
    raise exception 'Choose Admin; the legacy administrative role is retired' using errcode = '22023';
  end if;
  if (tg_op in ('UPDATE', 'DELETE') and old.role = 'admin') or target_role = 'admin' then
    if tg_op = 'DELETE' then raise exception 'Admin core access cannot be revoked' using errcode = '42501'; end if;
    if new.role <> 'admin' or not new.allowed then
      raise exception 'Admin core access cannot be revoked' using errcode = '42501';
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_admin_permission_overrides()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare target_user uuid;
begin
  if tg_op = 'DELETE' then target_user := old.user_id; else target_user := new.user_id; end if;
  if auth.uid() is not null and not public.is_admin(auth.uid()) then
    raise exception 'Only Admin can manage individual access' using errcode = '42501';
  end if;
  if exists (select 1 from public.profiles where id = target_user and role = 'admin')
     or (tg_op = 'UPDATE' and exists (select 1 from public.profiles where id = old.user_id and role = 'admin')) then
    raise exception 'Admin core access cannot be overridden' using errcode = '42501';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_task_evidence_cleanup(p_object_name text, p_bucket_id text DEFAULT 'task-attachments'::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare obj storage.objects; seal eflow_evidence.objects; worker boolean := coalesce(auth.role() = 'service_role', false);
begin
  if p_bucket_id is null or p_bucket_id not in ('task-attachments', 'task-files') or nullif(p_object_name, '') is null then
    raise exception 'Invalid evidence cleanup target' using errcode = '22023';
  end if;
  if not worker and not eflow_evidence.active_actor() then raise exception 'Not authorized' using errcode = '42501'; end if;
  perform eflow_evidence.lock_path(p_bucket_id, p_object_name);
  select * into obj from storage.objects where bucket_id = p_bucket_id and name = p_object_name;
  if not found then return false; end if;
  if not worker and obj.owner_id is distinct from auth.uid()::text then raise exception 'Only the uploader may clean up this file' using errcode = '42501'; end if;
  if worker and (obj.created_at is null or obj.created_at > now() - interval '24 hours') then raise exception 'Orphan cleanup requires an upload at least 24 hours old' using errcode = '22023'; end if;
  select * into seal from eflow_evidence.objects where bucket_id = p_bucket_id and object_name = p_object_name;
  if found then
    if seal.state = 'finalized' then raise exception 'Finalized evidence cannot be deleted' using errcode = '42501'; end if;
    if seal.object_id is distinct from obj.id then raise exception 'Cleanup object identity changed; manual inspection required' using errcode = '22023'; end if;
    return true;
  end if;
  if exists (select 1 from public.task_attachments a where a.file_path = p_object_name)
     or exists (select 1 from public.subtask_submission_attachments a where a.file_path = p_object_name)
     or exists (select 1 from public.subtask_progress_updates a where a.attachment_path = p_object_name) then
    raise exception 'Referenced evidence cannot be deleted' using errcode = '42501';
  end if;
  insert into eflow_evidence.objects(bucket_id, object_name, object_id, actor_id, state)
  values (p_bucket_id, p_object_name, obj.id, auth.uid(), 'cleanup');
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_petty_cash_release_internal(p_release_id uuid, p_override_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  release public.petty_cash_releases;
  request public.petty_cash_requests;
  budget public.department_fiscal_budgets;
  request_id_value uuid;
  released_total numeric;
  used_today numeric;
  override_reason text := nullif(btrim(p_override_reason), '');
  actor_role_value text;
begin
  if caller is null then raise exception 'Sign in before recording a cash release' using errcode = '42501'; end if;
  select request_id into request_id_value from public.petty_cash_releases where id = p_release_id;
  if not found then raise exception 'Scheduled release not found' using errcode = 'P0002'; end if;
  -- Match the request -> budget -> release order used by scheduling/cancellation.
  select * into request from public.petty_cash_requests where id = request_id_value for update;
  if not found then raise exception 'Cash request not found' using errcode = 'P0002'; end if;
  if not public.is_department_budget_approver(request.org_id, caller) then
    raise exception 'Only the Head or Assistant Head can record a cash release' using errcode = '42501';
  end if;
  select * into budget from public.department_fiscal_budgets where id = request.fiscal_budget_id and status = 'locked' for update;
  if not found then raise exception 'The annual department budget is no longer open' using errcode = '22023'; end if;
  -- Serializes normal releases and overrides, including across fiscal budgets
  -- for the same department. Scheduling below uses this same lock.
  perform pg_advisory_xact_lock(hashtextextended('eflow:cash-release:' || request.org_id::text, 0));
  select * into release from public.petty_cash_releases where id = p_release_id and request_id = request.id for update;
  if not found then raise exception 'Scheduled release not found' using errcode = 'P0002'; end if;
  if release.status <> 'scheduled' then raise exception 'This cash tranche has already been processed' using errcode = '22023'; end if;
  if request.status not in ('approved', 'scheduled_for_release', 'partially_released') or request.approved_amount is null then
    raise exception 'Cash must be fiscally approved before release; a schedule override cannot approve funding' using errcode = '22023';
  end if;
  if release.scheduled_date > current_date and override_reason is null then
    raise exception 'This tranche is scheduled for %. Use Override schedule and provide a reason to release it early.', release.scheduled_date using errcode = '22023';
  end if;
  if p_override_reason is not null and (override_reason is null or length(override_reason) < 10 or length(override_reason) > 1000) then
    raise exception 'Explain the schedule override in 10 to 1000 characters' using errcode = '22023';
  end if;
  select coalesce(sum(amount), 0) into released_total from public.petty_cash_releases
    where request_id = request.id and status = 'released';
  if released_total + release.amount > request.approved_amount then
    raise exception 'This tranche would exceed the approved cash request amount' using errcode = '22023';
  end if;
  -- Preserve room already promised to today's scheduled tranches. An early or
  -- late release consumes its actual release day, not its original schedule.
  select coalesce(sum(amount), 0) into used_today from public.petty_cash_releases
    where org_id = request.org_id and id <> release.id and (
      (status = 'released' and coalesce(released_at::date, scheduled_date) = current_date)
      or (status = 'scheduled' and scheduled_date = current_date)
    );
  if used_today + release.amount > budget.daily_petty_cash_release_limit then
    raise exception 'Daily release ceiling exceeded. Only % remains on server date % after released cash and today''s scheduled tranches; this tranche needs %. The schedule override cannot bypass this limit.',
      greatest(0, budget.daily_petty_cash_release_limit - used_today), current_date, release.amount using errcode = '22023';
  end if;
  update public.petty_cash_releases set status = 'released', released_by = caller, released_at = now() where id = release.id;
  released_total := released_total + release.amount;
  update public.petty_cash_requests set released_amount = released_total,
    status = case when released_total >= approved_amount then 'released' else 'partially_released' end,
    liquidation_due_at = case when released_total >= approved_amount then now() + budget.liquidation_due_days * interval '1 day' else liquidation_due_at end,
    updated_at = now() where id = request.id;
  insert into public.budget_ledger_entries(fiscal_budget_id, org_id, commitment_id, allocation_id, petty_cash_request_id, entry_type, amount, description, actor_id)
  values (request.fiscal_budget_id, request.org_id, request.commitment_id, request.allocation_id, request.id,
    'petty_cash_released', release.amount, 'Scheduled petty-cash tranche released to recipient', caller);
  if override_reason is not null then
    select role::text into actor_role_value from public.profiles where id = caller;
    insert into public.budget_ledger_entries(
      fiscal_budget_id, org_id, commitment_id, allocation_id, petty_cash_request_id,
      task_id, subtask_id, allocation_line_id, entry_type, amount, description,
      actor_id, actor_role, previous_state, new_state, reason, metadata
    ) values (
      request.fiscal_budget_id, request.org_id, request.commitment_id, request.allocation_id, request.id,
      request.task_id, request.subtask_id, request.allocation_line_id, 'financial_override', 0,
      format('Cash release schedule override: %s -> %s. Reason: %s', release.scheduled_date, current_date, override_reason),
      caller, actor_role_value, 'scheduled', 'released', override_reason,
      jsonb_build_object('overrideType', 'cash_release_schedule', 'releaseId', release.id,
        'originalScheduledDate', release.scheduled_date, 'actualReleaseDate', current_date,
        'releasedAt', now(), 'releaseAmount', release.amount, 'recipientId', release.recipient_id,
        'dailyLimit', budget.daily_petty_cash_release_limit, 'previousDailyUsage', used_today)
    );
  end if;
  insert into public.notifications(user_id, type, title, message, task_id, actor_id, actor_name, financial_record_id, financial_record_type)
  select request.cash_recipient_id, 'petty_cash_released', 'Petty cash released',
    to_char(release.amount, 'FM999G999G999G990D00') || ' was recorded as released for your work request.',
    request.task_id, caller, coalesce(full_name, ''), release.id, 'petty_cash_release' from public.profiles where id = caller;
end;
$function$

CREATE OR REPLACE FUNCTION public.override_petty_cash_release_schedule(p_release_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_reason is null or length(btrim(p_reason)) < 10 or length(btrim(p_reason)) > 1000 then
    raise exception 'Explain the schedule override in 10 to 1000 characters' using errcode = '22023';
  end if;
  perform public.record_petty_cash_release_internal(p_release_id, p_reason);
end;
$function$

CREATE OR REPLACE FUNCTION public.department_budget_summary(p_org_id uuid, p_fiscal_year integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  budget public.department_fiscal_budgets;
  committed numeric := 0;
  spent numeric := 0;
  petty_reserved numeric := 0;
  released_today numeric := 0;
  scheduled_today numeric := 0;
begin
  if auth.uid() is null or not public.can_view_department_budget(p_org_id, auth.uid()) then raise exception 'Budget access denied' using errcode = '42501'; end if;
  select * into budget from public.department_fiscal_budgets where org_id = p_org_id and fiscal_year = p_fiscal_year;
  if not found then return null; end if;
  select coalesce(sum(amount), 0) into committed from public.budget_commitments where fiscal_budget_id = budget.id and status = 'active';
  select coalesce(sum(actual_spent), 0) into spent from public.petty_cash_requests where fiscal_budget_id = budget.id and status = 'settled';
  select coalesce(sum(case when status = 'settled' then 0 else greatest(coalesce(approved_amount, 0) - coalesce(actual_spent, 0) - coalesce(returned_amount, 0), 0) end), 0)
  into petty_reserved from public.petty_cash_requests where fiscal_budget_id = budget.id
    and status in ('approved','scheduled_for_release','partially_released','released','liquidation_submitted','pending_leader_liquidation_review','pending_department_settlement','changes_requested','overdue_liquidation');
  select coalesce(sum(amount), 0) into released_today from public.petty_cash_releases where org_id = p_org_id and coalesce(released_at::date, scheduled_date) = current_date and status = 'released';
  select coalesce(sum(amount), 0) into scheduled_today from public.petty_cash_releases where org_id = p_org_id and scheduled_date = current_date and status = 'scheduled';
  return jsonb_build_object(
    'id', budget.id, 'orgId', budget.org_id, 'fiscalYear', budget.fiscal_year, 'status', budget.status,
    'approvedAmount', budget.approved_amount, 'committedAmount', committed, 'spentAmount', spent,
    'availableAmount', greatest(0, budget.approved_amount - committed), 'commitmentRemaining', greatest(0, committed - spent),
    'dailyPettyCashReleaseLimit', budget.daily_petty_cash_release_limit, 'perReceiptLimit', budget.per_receipt_limit,
    'liquidationDueDays', budget.liquidation_due_days, 'allowReceiptLimitOverride', budget.allow_receipt_limit_override,
    'releasedToday', released_today, 'scheduledToday', scheduled_today,
    'dailyReleaseRemaining', greatest(0, budget.daily_petty_cash_release_limit - released_today - scheduled_today),
    'pettyCashLimit', budget.daily_petty_cash_release_limit, 'pettyCashRequestLimit', budget.per_receipt_limit,
    'pettyCashReserved', petty_reserved, 'pettyCashSpent', spent,
    'pettyCashAvailable', greatest(0, budget.daily_petty_cash_release_limit - released_today - scheduled_today),
    'underutilizationThreshold', budget.underutilization_threshold, 'notes', budget.notes,
    'lockedAt', budget.locked_at, 'updatedAt', budget.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.project_completion_readiness_internal(p_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  project_row public.projects;
  blockers jsonb := '[]'::jsonb;
  delivery_count int;
  closeout_status text;
begin
  select * into project_row from public.projects where id = p_project_id;
  if not found then raise exception 'Project not found' using errcode = 'P0002'; end if;
  select count(*) into delivery_count from public.tasks t
    where t.linked_project_id = p_project_id and t.deleted_at is null;
  if delivery_count = 0 and project_row.status not in ('completed', 'archived') then
    blockers := blockers || jsonb_build_array(jsonb_build_object('kind', 'work', 'id', p_project_id,
      'title', 'No delivery tasks', 'status', 'not_started',
      'detail', 'Add and finish the project work before marking it complete.'));
  end if;
  blockers := blockers || coalesce((select jsonb_agg(jsonb_build_object(
    'kind', 'task', 'id', t.id, 'taskId', t.id, 'title', t.title, 'status', t.status,
    'detail', case when t.status = 'for_review' then 'Awaiting reviewer approval in Reviews → Project Tasks.'
      when t.status = 'changes_requested' then 'Correct the requested changes and resubmit this task.'
      else 'Finish and submit this task for approval, or cancel it if it is no longer required.' end
  ) order by t.title, t.id) from public.tasks t where t.linked_project_id = p_project_id
    and t.deleted_at is null and t.status not in ('completed', 'cancelled')), '[]'::jsonb);
  blockers := blockers || coalesce((select jsonb_agg(jsonb_build_object(
    'kind', 'subtask', 'id', s.id, 'taskId', t.id, 'title', t.title || ' → ' || s.title, 'status', s.status,
    'detail', 'Finish this subtask and obtain its assigned reviewer approval in the task details.'
  ) order by t.title, s.title, s.id) from public.subtasks s join public.tasks t on t.id = s.task_id
    where t.linked_project_id = p_project_id and t.deleted_at is null and t.status <> 'cancelled'
      and s.status <> 'completed'), '[]'::jsonb);
  -- Include cash on deleted/cancelled/archived tasks: hiding work never settles money.
  blockers := blockers || coalesce((select jsonb_agg(jsonb_build_object(
    'kind', 'cash', 'id', r.id, 'taskId', t.id,
    'title', 'FR-' || lpad(r.request_number::text, 5, '0') || ' · ' || t.title || coalesce(' → ' || s.title, ''),
    'status', r.status, 'amount', coalesce(r.approved_amount, r.requested_amount),
    'detail', case
      when r.status = 'pending_leader_review' then 'Task Leader must review this cash request in Reviews → Budget.'
      when r.status in ('pending', 'pending_department_approval') then 'Department Head must review this cash request in Reviews → Budget.'
      when r.status = 'pending_leader_liquidation_review' then 'Task Leader must endorse the receipt package in Reviews → Budget.'
      when r.status in ('liquidation_submitted', 'pending_department_settlement') then 'Department Head must settle the receipts and unused cash in Reviews → Budget.'
      when r.status in ('approved', 'scheduled_for_release', 'partially_released') then 'Check Department Budget → Releases & Settlement; this cash request remains open.'
      when r.status in ('released', 'overdue_liquidation', 'liquidation_draft', 'changes_requested') then 'Cash recipient must submit or correct the receipts and unused cash return in task/subtask Funding activity.'
      else 'Resolve or cancel this open cash request in task/subtask Funding activity before completion.' end
  ) order by r.request_number, r.id) from public.petty_cash_requests r
    join public.tasks t on t.id = r.task_id left join public.subtasks s on s.id = r.subtask_id
    where t.linked_project_id = p_project_id and r.status not in ('settled', 'rejected', 'cancelled')), '[]'::jsonb);
  if project_row.source_collaboration_draft_id is not null and exists (
    select 1 from public.proposal_collaboration_orgs o
      where o.draft_id = project_row.source_collaboration_draft_id and o.participation_role = 'governance'
  ) then
    select c.status into closeout_status from public.proposal_delivery_closeouts c
      where c.draft_id = project_row.source_collaboration_draft_id;
    if coalesce(closeout_status, 'draft') not in ('approved', 'completed', 'archived') then
      blockers := blockers || jsonb_build_array(jsonb_build_object(
        'kind', 'governance', 'id', project_row.source_collaboration_draft_id,
        'title', 'Final proposal governance closeout', 'status', coalesce(closeout_status, 'draft'),
        'detail', 'Open the source proposal’s Governance → Final governance closeout to request verification and resolve the listed organization decisions.'));
    end if;
  end if;
  return jsonb_build_object('projectId', project_row.id, 'title', project_row.title, 'status', project_row.status,
    'canComplete', project_row.status in ('planning', 'active', 'on_hold') and jsonb_array_length(blockers) = 0,
    'blockers', blockers);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_project_completion_readiness(p_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or not coalesce(public.can_manage_project(p_project_id, auth.uid()), false)
     or not exists (select 1 from public.profiles where id = auth.uid() and is_active) then
    raise exception 'Only an authorized project manager can complete or archive this project' using errcode = '42501';
  end if;
  return public.project_completion_readiness_internal(p_project_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_project_completion_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare readiness jsonb;
begin
  if new.status = 'archived' and old.status not in ('completed', 'archived') then
    raise exception 'Complete the project before archiving it' using errcode = '22023';
  end if;
  if new.status <> 'archived' and new.archived_at is not null then
    raise exception 'Only a completed project can be archived; do not hide an active project' using errcode = '22023';
  end if;
  if new.status in ('completed', 'archived') and new.status is distinct from old.status then
    readiness := public.project_completion_readiness_internal(old.id);
    if jsonb_array_length(readiness->'blockers') > 0 then
      raise exception 'Project closeout is blocked: %', readiness->'blockers'->0->>'title'
        using errcode = '22023', detail = (readiness->'blockers')::text,
        hint = 'Open Mark project complete to see the outstanding work, cash, and sign-offs.';
    end if;
  end if;
  if new.status = 'archived' then new.archived_at := coalesce(new.archived_at, now()); end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.can_see_task(target_task uuid, caller_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  task_row public.tasks;
begin
  if caller_id is null then return false; end if;
  if public.auth_role(caller_id) = 'admin' then return true; end if;
  select * into task_row from public.tasks where id = target_task and deleted_at is null;
  if not found then return false; end if;
  return task_row.assigned_to = caller_id
    or task_row.created_by = caller_id
    or task_row.recommendation_lead_id = caller_id
    or task_row.reviewer_id = caller_id
    or task_row.backup_reviewer_id = caller_id
    or coalesce(to_jsonb(task_row.team_member_ids), '[]'::jsonb) ? caller_id::text
    or (task_row.linked_project_id is not null and public.can_see_project(task_row.linked_project_id, caller_id))
    or (
      task_row.source_collaboration_draft_id is null
      and public.can_access_org(caller_id, task_row.org_id, 'read')
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.can_manage_task(target_task uuid, caller_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  task_row public.tasks;
begin
  if caller_id is null or public.auth_role(caller_id) = 'admin' then return false; end if;
  select * into task_row from public.tasks where id = target_task and deleted_at is null;
  if not found then return false; end if;
  if task_row.source_collaboration_draft_id is not null then
    return task_row.recommendation_lead_id = caller_id
      or public.is_organization_approver(task_row.org_id, caller_id);
  end if;
  return task_row.created_by = caller_id
    or task_row.recommendation_lead_id = caller_id
    or public.can_access_org(caller_id, task_row.org_id, 'manage');
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_completed_project(p_project_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare project_row public.projects;
begin
  perform public.get_project_completion_readiness(p_project_id);
  select * into project_row from public.projects where id = p_project_id for update;
  if project_row.status = 'archived' then return; end if;
  if project_row.status <> 'completed' then raise exception 'Complete the project before archiving it' using errcode = '22023'; end if;
  update public.projects set status = 'archived', archived_at = now(), updated_at = now() where id = p_project_id;
  insert into public.audit_events(actor_id, actor_name, entity_type, entity_id, action, reason, before_data, after_data, org_id)
  values (auth.uid(), coalesce((select full_name from public.profiles where id = auth.uid()), 'Project manager'),
    'project', p_project_id::text, 'project.archived', nullif(btrim(p_reason), ''),
    jsonb_build_object('status', project_row.status), jsonb_build_object('status', 'archived'), project_row.org_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_project(p_project_id uuid, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare project_row public.projects;
begin
  perform public.get_project_completion_readiness(p_project_id);
  select * into project_row from public.projects where id = p_project_id for update;
  if project_row.status = 'completed' then return; end if;
  if project_row.status = 'archived' then raise exception 'This project is already archived' using errcode = '22023'; end if;
  -- The trigger rechecks readiness at the actual update, never trusting the UI.
  update public.projects set status = 'completed', updated_at = now() where id = p_project_id;
  insert into public.audit_events(actor_id, actor_name, entity_type, entity_id, action, reason, before_data, after_data, org_id)
  values (auth.uid(), coalesce((select full_name from public.profiles where id = auth.uid()), 'Project manager'),
    'project', p_project_id::text, 'project.completed', nullif(btrim(p_note), ''),
    jsonb_build_object('status', project_row.status), jsonb_build_object('status', 'completed'), project_row.org_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.can_see_project(target_project uuid, caller_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  project_row public.projects;
begin
  if caller_id is null then return false; end if;
  if public.auth_role(caller_id) = 'admin' then return true; end if;
  select * into project_row from public.projects where id = target_project;
  if not found then return false; end if;
  if project_row.source_collaboration_draft_id is not null then
    return public.can_see_collaboration_project(target_project, caller_id)
      or public.is_collaboration_participant(project_row.source_collaboration_draft_id, caller_id);
  end if;
  return project_row.owner_id = caller_id
    or public.is_project_member(target_project, caller_id)
    or exists (
      select 1 from public.tasks task
      where task.linked_project_id = target_project and task.deleted_at is null
        and (
          task.assigned_to = caller_id
          or task.recommendation_lead_id = caller_id
          or coalesce(to_jsonb(task.team_member_ids), '[]'::jsonb) ? caller_id::text
        )
    )
    or public.can_access_org(caller_id, project_row.org_id, 'read');
end;
$function$

CREATE OR REPLACE FUNCTION public.can_create_scoped_work(target_org uuid, caller_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller_profile public.profiles;
begin
  if caller_id is null then return false; end if;
  select * into caller_profile
  from public.profiles
  where id = caller_id and is_active;
  if not found then return false; end if;
  if caller_profile.role = 'admin' then return true; end if;
  return caller_profile.role in ('dept_head', 'department_head', 'assistant_head')
    and target_org is not null
    and target_org = caller_profile.org_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.settle_accounting_liquidation(p_liquidation_id uuid, p_approve boolean, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare caller uuid := auth.uid(); liquidation public.petty_cash_liquidations; request public.petty_cash_requests;
begin
  select * into liquidation from public.petty_cash_liquidations where id = p_liquidation_id for update;
  if not found then raise exception 'Liquidation not found' using errcode = 'P0002'; end if;
  select * into request from public.petty_cash_requests where id = liquidation.request_id for update;
  if not public.can_manage_department_accounting(request.org_id, caller) then
    raise exception 'Only department accounting staff, the Head, or Assistant Head can settle this liquidation' using errcode = '42501';
  end if;
  if caller in (request.cash_recipient_id, request.requester_id) then raise exception 'You cannot settle your own liquidation' using errcode = '42501'; end if;
  if caller = liquidation.leader_decided_by then raise exception 'Leader review and settlement must be performed by different people' using errcode = '42501'; end if;
  if liquidation.status <> 'pending_department_settlement' or request.status <> 'pending_department_settlement' then
    raise exception 'This liquidation is not awaiting accounting settlement' using errcode = '22023';
  end if;
  if not p_approve and nullif(btrim(p_reason), '') is null then raise exception 'Explain what must be corrected' using errcode = '22023'; end if;
  update public.petty_cash_liquidations set status = case when p_approve then 'approved' else 'changes_requested' end,
    decided_by = caller, decision_reason = nullif(btrim(p_reason), ''), decided_at = now(),
    department_decided_by = caller, department_decision_reason = nullif(btrim(p_reason), ''), department_decided_at = now()
  where id = liquidation.id;
  if p_approve then
    update public.petty_cash_requests set status = 'settled', actual_spent = liquidation.declared_spent,
      returned_amount = liquidation.returned_amount, settled_by = caller, settled_at = now(), updated_at = now()
    where id = request.id;
    insert into public.budget_ledger_entries(fiscal_budget_id, org_id, commitment_id, allocation_id, petty_cash_request_id, entry_type, amount, description, actor_id)
    values (request.fiscal_budget_id, request.org_id, request.commitment_id, request.allocation_id, request.id,
      'expense_posted', liquidation.declared_spent, 'Verified receipts posted as actual task spending', caller);
    if liquidation.returned_amount > 0 then
      insert into public.budget_ledger_entries(fiscal_budget_id, org_id, commitment_id, allocation_id, petty_cash_request_id, entry_type, amount, description, actor_id)
      values (request.fiscal_budget_id, request.org_id, request.commitment_id, request.allocation_id, request.id,
        'cash_returned', liquidation.returned_amount, 'Unused released cash returned to the department', caller);
    end if;
  else
    update public.petty_cash_requests set status = 'changes_requested', updated_at = now() where id = request.id;
  end if;
  insert into public.notifications(user_id, type, title, message, task_id, actor_id, actor_name, reason, financial_record_id, financial_record_type)
  select request.cash_recipient_id, 'petty_cash_liquidation_decision',
    case when p_approve then 'Expense liquidation settled' else 'Liquidation changes requested' end,
    case when p_approve then 'Accounting verified the receipts and posted the balanced journal entry.' else 'Your liquidation needs corrections before settlement.' end,
    request.task_id, caller, coalesce(full_name, ''), coalesce(p_reason, ''), liquidation.id, 'petty_cash_liquidation'
  from public.profiles where id = caller;
end;
$function$

CREATE OR REPLACE FUNCTION public.post_general_journal_adjustment(p_fiscal_budget_id uuid, p_entry_date date, p_reference_number text, p_memo text, p_lines jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  budget public.department_fiscal_budgets;
  item jsonb;
  debit_total numeric := 0;
  credit_total numeric := 0;
  journal_id uuid;
  account_title_value text;
  line_value int := 0;
begin
  select * into budget from public.department_fiscal_budgets where id = p_fiscal_budget_id;
  if not found then raise exception 'Fiscal budget not found' using errcode = 'P0002'; end if;
  if not public.can_manage_department_accounting(budget.org_id, caller) then raise exception 'Accounting access denied' using errcode = '42501'; end if;
  if nullif(btrim(p_reference_number), '') is null or nullif(btrim(p_memo), '') is null then
    raise exception 'Reference and memo are required' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' or jsonb_array_length(p_lines) < 2 then
    raise exception 'A journal entry needs at least two lines' using errcode = '22023';
  end if;
  for item in select value from jsonb_array_elements(p_lines) loop
    debit_total := debit_total + coalesce((item ->> 'debit')::numeric, 0);
    credit_total := credit_total + coalesce((item ->> 'credit')::numeric, 0);
    if (coalesce((item ->> 'debit')::numeric, 0) > 0) = (coalesce((item ->> 'credit')::numeric, 0) > 0) then
      raise exception 'Each journal line must contain either a debit or a credit' using errcode = '22023';
    end if;
    if not exists (select 1 from public.accounting_accounts where code = item ->> 'accountCode' and is_active) then
      raise exception 'Choose an active account for every journal line' using errcode = '22023';
    end if;
  end loop;
  if debit_total <= 0 or abs(debit_total - credit_total) > 0.009 then
    raise exception 'Journal debits and credits must balance' using errcode = '22023';
  end if;
  insert into public.general_journal_entries(
    fiscal_budget_id, org_id, entry_date, reference_number, source_type, memo, posted_by
  ) values (
    budget.id, budget.org_id, coalesce(p_entry_date, current_date), btrim(p_reference_number),
    'manual_adjustment', btrim(p_memo), caller
  ) returning id into journal_id;
  for item in select value from jsonb_array_elements(p_lines) loop
    line_value := line_value + 1;
    select title into account_title_value from public.accounting_accounts where code = item ->> 'accountCode';
    insert into public.general_journal_lines(journal_entry_id, line_number, account_code, account_title, debit, credit)
    values (journal_id, line_value, item ->> 'accountCode', account_title_value,
      coalesce((item ->> 'debit')::numeric, 0), coalesce((item ->> 'credit')::numeric, 0));
  end loop;
  insert into public.audit_events(actor_id, actor_name, entity_type, entity_id, action, reason, after_data, org_id)
  select caller, profile.full_name, 'general_journal_entry', journal_id::text, 'manual_adjustment_posted',
    btrim(p_memo), jsonb_build_object('referenceNumber', btrim(p_reference_number), 'debit', debit_total, 'credit', credit_total), budget.org_id
  from public.profiles profile where profile.id = caller;
  return journal_id;
end;
$function$
